  public void cmdFileNewPage()
  {
    try
    {
      if (clsVar.appModes_0.NoValidLicense)
        buString5.MessageBoxError(AppLanguage.CadCamMessages[83]);
      else if (clsVar.appModes_0.TimePeriodExpire)
        buString5.MessageBoxError(AppLanguage.CadCamMessages[84]);
      else if (ccVars.Pages.Count >= clsVar.varProgram.MaxPageCount)
      {
        buString.MessageBoxWarning(AppLanguage.CadCamMessages[3]);
      }
      else
      {
        this.NewPage(new Pages(), true, "", "");
        // ISSUE: reference to a compiler-generated field
        if (this.formUpdate_0 != null)
        {
          // ISSUE: reference to a compiler-generated field
          this.formUpdate_0(false, false, true);
        }
        ++clsVar.NewCount;
      }
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void cmdFileNewScene()
  {
    try
    {
      if (clsVar.appModes_0.NoValidLicense)
        buString5.MessageBoxError(AppLanguage.CadCamMessages[83]);
      else if (clsVar.appModes_0.TimePeriodExpire)
      {
        buString5.MessageBoxError(AppLanguage.CadCamMessages[84]);
      }
      else
      {
        if (ccVars.Pages.Count <= 0)
          return;
        ccVars.Pages[ccVars.PageIndex].Scene.Add(new PageScene()
        {
          ScenePlane = devDept.Geometry.Plane.XY,
          SceneName = "Scene" + (ccVars.Pages[ccVars.PageIndex].Scene.Count + 1).ToString()
        });
        ccVars.Pages[ccVars.PageIndex].SceneIndex = ccVars.Pages[ccVars.PageIndex].Scene.Count - 1;
        this.MacroExecute(clsVar.macroNewScene);
        ccVars.Pages[ccVars.PageIndex].Changed = true;
        this.PagesUpdate(true, "");
      }
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void NewPage(Pages Page, bool NewPageEnable, string PageName, string FileName)
  {
    if (clsVar.appModes_0.TuftingMode.Enable && ccVars.Pages.Count > 0)
    {
      buString5.MessageBoxWarning(AppLanguage.CadCamMessages[95]);
    }
    else
    {
      if (clsVar.SingleNewPage && ccVars.Pages.Count > 0)
      {
        for (int Index = ccVars.Pages.Count - 1; Index >= 0; --Index)
          clsInit.appCommand.PageClose(Index);
      }
      F_Drawing fDrawing1 = new F_Drawing();
      fDrawing1.WindowState = FormWindowState.Maximized;
      fDrawing1.MdiParent = clsItem.FrmMain;
      F_Drawing fDrawing2 = fDrawing1;
      Page.Form = fDrawing2;
      Page.FileName = FileName;
      Page.PageName = $"{AppLanguage.CadCamDynamic[37]}-{(ccVars.Pages.Count + 1).ToString()}";
      FileInfo fileInfo = new FileInfo($"{Application.StartupPath}\\Undo{Page.PageName}.und");
      if (fileInfo.Exists)
        fileInfo.Delete();
      if (Page.Layers.Count <= 0)
      {
        Page.Layers.Add(new LayerBase5(AppLanguage.CadCamDynamic[24] + " 1")
        {
          LayerColor = Color.Black
        });
        Page.Layers.Add(new LayerBase5(AppLanguage.CadCamDynamic[24] + " 2")
        {
          LayerColor = Color.Red
        });
        Page.Layers.Add(new LayerBase5(AppLanguage.CadCamDynamic[24] + " 3")
        {
          LayerColor = Color.Gold
        });
      }
      Page.Scene.Add(new PageScene()
      {
        ScenePlane = devDept.Geometry.Plane.XY,
        SceneName = AppLanguage.CadCamDynamic[38] + (Page.Scene.Count + 1).ToString()
      });
      Page.Form.viewportcad.WorkCompleted += new WorkUnit.WorkCompletedEventHandler(this.ModelOpenFile_WorkCompleted);
      Page.Form.viewportcad.WorkFailed += new WorkUnit.WorkFailedEventHandler(this.ModelOpenFile_WorkFailed);
      Page.Form.viewportcad.WorkCancelled += new WorkUnit.WorkCancelledEventHandler(this.ModelOpenFile_WorkCancelled);
      ccVars.Pages.Add(Page);
      ccVars.PageIndex = ccVars.Pages.Count - 1;
      ccVars.Pages[ccVars.PageIndex].SceneIndex = 0;
      ccVars.Pages[ccVars.PageIndex].SceneName = ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].SceneName;
      ccVars.Pages[ccVars.PageIndex].Form.Tag = (object) ccVars.PageIndex;
      ccVars.Pages[ccVars.PageIndex].Form.Text = buFile.getFileName(FileName);
      ccVars.Pages[ccVars.PageIndex].LayerName = Page.Layers[0].Name;
      if (clsVar.appModes_0.ProfileMode.Enable && FileName.Length == 0)
        clsInit.appProfile.NewPageExtension();
      if (clsVar.appModes_0.DrillMode.Enable && FileName.Length == 0)
        clsInit.appDrill.NewPageExtension();
      if (clsVar.appModes_0.FoamCuttingMode.Enable && FileName.Length == 0)
        clsInit.appFoamCutting.doNewPage();
      if (clsVar.appModes_0.MarbleMode.Enable && FileName.Length == 0)
        clsInit.appMarble.doNewPage();
      if (clsVar.appModes_0.CompositeMode.Enable && FileName.Length == 0)
        clsInit.appRouter3AX.doNewPage();
      if (clsVar.appModes_0.NestingMode.PanelMode && FileName.Length == 0)
        clsInit.appPanelCut.doNewPage();
      if (clsVar.appModes_0.Printer3DMode.Enable && FileName.Length == 0)
        clsInit.appPrinter3D.NewPageExtension();
      if (clsVar.appModes_0.WoodMode.Enable && FileName.Length == 0)
        clsInit.appWood.NewPageExtension();
      if (clsVar.appModes_0.DoorMode.Enable && FileName.Length == 0)
        clsInit.appDoor.NewPageExtension();
      if (clsVar.appModes_0.CutterMode.Enable && FileName.Length == 0)
        clsInit.appCutter.doNewExtension();
      if (NewPageEnable)
        this.MacroExecute(clsVar.macroNewPage);
      if (clsItem.FrmTempMisc != null)
        clsItem.FrmTempMisc.txt_notes.Text = "";
      if (clsItem.FrmTempMaterial != null)
        clsItem.FrmTempMaterial.txt_notes.Text = "";
      fDrawing2.Init();
      fDrawing2.Show();
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers = this.LayerConvertFromBuLayerToEyeLayer(ccVars.Pages[ccVars.PageIndex].Layers);
      // ISSUE: reference to a compiler-generated field
      if (this.formUpdate_0 != null)
      {
        // ISSUE: reference to a compiler-generated field
        this.formUpdate_0(true, false, false);
      }
      ccVars.Pages[ccVars.PageIndex].LayerIndex = 0;
      ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex].Name;
      this.PagesUpdate(true, "");
      this.LayersUpdate(ccVars.Pages[ccVars.PageIndex].Layers, true, 0);
      this.undoBuffer();
      this.PageInfo(ccVars.Pages[ccVars.PageIndex], clsVar.varProgram.PagePanelSettings);
      this.MaterialUpdate(true, clsVar.varInterface.MaterialIndex);
      if (clsVar.appModes_0.TuftingMode.Enable)
        clsInit.appTufting.NewPageTuftingExtension();
      ccVars.Pages[ccVars.PageIndex].Changed = false;
    }
  }

