  public bool cmdFileOpenPreview(FileOpenType Type, string InitPath = "")
  {
    try
    {
      if (clsVar.appModes_0.NoValidLicense)
      {
        buString5.MessageBoxError(AppLanguage.CadCamMessages[83]);
        return false;
      }
      if (clsVar.appModes_0.TimePeriodExpire)
      {
        buString5.MessageBoxError(AppLanguage.CadCamMessages[84]);
        return false;
      }
      if (ccVars.Pages.Count >= clsVar.varProgram.MaxPageCount)
      {
        buString.MessageBoxWarning($"{AppLanguage.CadCamMessages[3]} - {clsVar.varProgram.MaxPageCount.ToString()}");
        return false;
      }
      if (clsVar.appModes_0.TuftingMode.Enable && ccVars.Pages.Count > 0)
      {
        buString5.MessageBoxWarning(AppLanguage.CadCamMessages[95]);
        return false;
      }
      this.openFileDialog_0 = new OpenFileDialog();
      this.openDialogCtrlPreview.Extensions.Clear();
      if (Type == FileOpenType.ImportAsPage | Type == FileOpenType.ImportAsScene)
      {
        for (int index = 0; index <= AppExtension.ImportFileExtension.Count - 1; ++index)
        {
