      }
      else
      {
        switch (Type)
        {
          case FileOpenType.Add:
            this.OpenPage(this.openFileDialog_0.FileNames);
            clsVar.varFile.FileAddMode.PreviewEnable = this.openDialogCtrlPreview.chk_preview.Checked;
            clsVar.varFile.FileAddMode.InitPath = buFile.GetPath(this.openFileDialog_0.FileName);
            clsVar.varFile.FileAddMode.FileFilterIndex = this.openFileDialog_0.FilterIndex;
            buFile.SetFileInitPathByType(AppExtension.OpenFileExtension, clsVar.varFile.FileAddMode.FileFilterIndex - 1, clsVar.varFile.FileAddMode.InitPath, ref clsVar.varFile.FileAddMode);
            break;
          case FileOpenType.Insert:
            this.OpenPage(this.openFileDialog_0.FileNames);
            clsVar.varFile.FileInsertMode.PreviewEnable = this.openDialogCtrlPreview.chk_preview.Checked;
            clsVar.varFile.FileInsertMode.InitPath = buFile.GetPath(this.openFileDialog_0.FileName);
            clsVar.varFile.FileInsertMode.FileFilterIndex = this.openFileDialog_0.FilterIndex;
            buFile.SetFileInitPathByType(AppExtension.OpenFileExtension, clsVar.varFile.FileInsertMode.FileFilterIndex - 1, clsVar.varFile.FileInsertMode.InitPath, ref clsVar.varFile.FileInsertMode);
            break;
          case FileOpenType.ProfileDrawImport:
            clsInit.appProfile.fileNameOperation = this.openFileDialog_0.FileNames[0];
            break;
        }
      }
      clsFiles.SaveParameter();
      return true;
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
      return false;
    }
  }

  public void cmdFileOpen(FileOpenType Type)
  {
    try
    {
      if (clsVar.appModes_0.NoValidLicense)
        buString5.MessageBoxError(AppLanguage.CadCamMessages[83]);
      else if (clsVar.appModes_0.TimePeriodExpire)
        buString5.MessageBoxError(AppLanguage.CadCamMessages[84]);
      else if (ccVars.Pages.Count >= clsVar.varProgram.MaxPageCount)
        buString.MessageBoxWarning($"{AppLanguage.CadCamMessages[3]} - {clsVar.varProgram.MaxPageCount.ToString()}");
      else if (clsVar.appModes_0.TuftingMode.Enable && ccVars.Pages.Count > 0)
      {
        buString5.MessageBoxWarning(AppLanguage.CadCamMessages[95]);
      }
      else
      {
        string initPath = clsVar.varFile.FileOpenMode.InitPath;
        int fileFilterIndex = clsVar.varFile.FileOpenMode.FileFilterIndex;
        if (Type == FileOpenType.ImportAsPage | Type == FileOpenType.ImportAsScene)
        {
          initPath = clsVar.varFile.FileImportMode.InitPath;
          fileFilterIndex = clsVar.varFile.FileImportMode.FileFilterIndex;
          ccVars.Action = actionTypeBU.fileImportAsPage;
        }
        if (Type == FileOpenType.Add)
        {
          initPath = clsVar.varFile.FileAddMode.InitPath;
          fileFilterIndex = clsVar.varFile.FileAddMode.FileFilterIndex;
          ccVars.Action = actionTypeBU.fileAdd;
        }
        if (Type == FileOpenType.Insert)
        {
          initPath = clsVar.varFile.FileInsertMode.InitPath;
          fileFilterIndex = clsVar.varFile.FileInsertMode.FileFilterIndex;
          ccVars.Action = actionTypeBU.fileInsert;
        }
        OpenFileDialog openFileDialog = new OpenFileDialog();
        openFileDialog.InitialDirectory = initPath;
        if (AppExtension.OpenFileExtension.Count == 0)
        {
          openFileDialog.Filter = "buCad Cad/Cam Files (*.bucad)|*.bucad";
        }
        else
        {
          for (int index = 0; index <= AppExtension.OpenFileExtension.Count - 1; ++index)
          {
            if (index == 0)
              openFileDialog.Filter = AppExtension.OpenFileExtension[index].ToString();
            else
              openFileDialog.Filter = $"{openFileDialog.Filter}|{AppExtension.OpenFileExtension[index].ToString()}";
          }
        }
        openFileDialog.FilterIndex = fileFilterIndex;
        openFileDialog.FileName = "";
        if (openFileDialog.ShowDialog() != DialogResult.OK)
          return;
        this.OpenPage(openFileDialog.FileNames);
        if (Type == FileOpenType.OpenAsPage | Type == FileOpenType.OpenAsScene)
        {
          clsVar.varFile.FileOpenMode.InitPath = buFile.GetPath(openFileDialog.FileName);
          clsVar.varFile.FileOpenMode.FileFilterIndex = openFileDialog.FilterIndex;
        }
        else if (Type == FileOpenType.ImportAsPage | Type == FileOpenType.ImportAsScene)
        {
          clsVar.varFile.FileImportMode.InitPath = buFile.GetPath(openFileDialog.FileName);
          clsVar.varFile.FileImportMode.FileFilterIndex = openFileDialog.FilterIndex;
        }
        else
        {
          switch (Type)
          {
            case FileOpenType.Add:
              clsVar.varFile.FileAddMode.InitPath = buFile.GetPath(openFileDialog.FileName);
              clsVar.varFile.FileAddMode.FileFilterIndex = openFileDialog.FilterIndex;
              break;
            case FileOpenType.Insert:
              clsVar.varFile.FileInsertMode.InitPath = buFile.GetPath(openFileDialog.FileName);
              clsVar.varFile.FileInsertMode.FileFilterIndex = openFileDialog.FilterIndex;
              break;
          }
        }
        clsFiles.SaveParameter();
      }
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

