  public void SetPreviewImage()
  {
    clsItem.ModelOpenPreview.Invalidate();
    clsItem.ModelOpenPreview.Entities.RegenAllCurved();
    clsItem.ModelOpenPreview.SetView(buConversion5.buViewTypeToEyeViewType(this.openDialogCtrlPreview.ViewType), true, false);
    clsItem.ModelOpenPreview.Invalidate();
    clsItem.ModelOpenPreview.CopyToClipboardRaster(new Size(this.openDialogCtrlPreview.picture_preview.Width, this.openDialogCtrlPreview.picture_preview.Height));
    this.openDialogCtrlPreview.DrawPreviewImage(Clipboard.GetImage());
    this.openDialogCtrlPreview.ShowLoading(false);
    clsVar.PreviewLoaded = true;
  }

  public void OpenPage(string[] FileNames)
  {
    if (FileNames.Length == 0)
      return;
    FileInfo fileInfo = new FileInfo(FileNames[0]);
    if (fileInfo.Extension.ToLower() == ".buprofile" & clsVar.appModes_0.ProfileMode.Enable)
    {
      clsInit.appProfile.OpenProfileJobFile(fileInfo.FullName, true, true, false, ref clsInit.appProfile.activeProfile, true);
      clsInit.appProfile.FileOpenCommonCommands();
    }
    else
    {
      clsVar.OpeningFileName = FileNames[0];
      bool ClearEntities = false;
      if (ccVars.Action == actionTypeBU.fileOpenAsPage | ccVars.Action == actionTypeBU.fileImportAsPage)
      {
        Pages Page = new Pages();
        if (!clsVar.NewPageViewportMode)
          this.NewPage(Page, true, "", FileNames[0]);
        else
          this.NewViewport(Page, true, "", FileNames[0]);
        ClearEntities = true;
      }
      if (ccVars.Action == actionTypeBU.fileOpenAsScene | ccVars.Action == actionTypeBU.fileImportAsScene)
        this.NewScene(true, "", FileNames[0]);
      Design model = (Design) null;
      if (ccVars.Action == actionTypeBU.fileInsert)
        clsInit.appFiles.OpenCadFiles(FileNames[0], ClearEntities, ref clsItem.ModelOpenInsert);
      else
        clsInit.appFiles.OpenCadFiles(FileNames[0], ClearEntities, ref model);
      if (fileInfo.Extension.ToLower() == ".bucadv5" | fileInfo.Extension.ToLower() == ".bucad" | fileInfo.Extension.ToLower() == ".ply" | fileInfo.Extension.ToLower() == ".cf2")
        clsInit.appFiles.CommonOperationAfterFileLoading();
      if (ccVars.Action == actionTypeBU.fileOpenAsPage | ccVars.Action == actionTypeBU.fileOpenAsScene)
        buString.AddFileToRecentFileList(FileNames[0], 10, ref clsVar.varInterface.LastLoadedFiles);
      if (ccVars.Action == actionTypeBU.fileImportAsPage | ccVars.Action == actionTypeBU.fileImportAsScene)
        buString.AddFileToRecentFileList(FileNames[0], 10, ref clsVar.varInterface.LastImportedFiles);
      if (ccVars.Action == actionTypeBU.fileOpenAsPage)
        this.MacroExecute(clsVar.macroOpen);
      if (ccVars.Action == actionTypeBU.fileImportAsPage)
        this.MacroExecute(clsVar.macroImport);
      // ISSUE: reference to a compiler-generated field
      if (this.formUpdate_0 != null)
      {
        // ISSUE: reference to a compiler-generated field
        this.formUpdate_0(true, false, false);
      }
      if (ccVars.Action == actionTypeBU.fileImportAsPage | ccVars.Action == actionTypeBU.fileOpenAsPage && fileInfo.Extension.ToLower() == ".bucadv5" | fileInfo.Extension.ToLower() == ".bucad" | fileInfo.Extension.ToLower() == ".ply" | fileInfo.Extension.ToLower() == ".cf2" | fileInfo.Extension.ToLower() == ".cnc" | fileInfo.Extension.ToLower() == ".nc" | fileInfo.Extension.ToLower() == ".mpf")
        this.MaterialUpdate(true, clsVar.varInterface.MaterialIndex);
      if (clsVar.appModes_0.FoamCuttingMode.Enable)
        clsInit.appFoamCutting.doOpenPage();
      if (clsVar.appModes_0.MarbleMode.Enable)
        clsInit.appMarble.doOpenPage();
      if (clsVar.appModes_0.CutterMode.Enable)
        clsInit.appCutter.doOpenPage();
      if (clsVar.appModes_0.CompositeMode.Enable)
        clsInit.appRouter3AX.doOpenPage();
      if (clsVar.appModes_0.NestingMode.PanelMode)
        clsInit.appPanelCut.doOpenPage();
      if (clsVar.appModes_0.DrillMode.Enable)
        clsInit.appDrill.OpenExtension();
      this.Reset(false);
    }
  }

  public void SavePage(string FileName)
  {
    string path = "";
    try
    {
      if (FileName.Length <= 0)
        return;
      FileInfo fileInfo1 = new FileInfo(FileName);
      string withoutExtension = buFile.getFileNameWithoutExtension(fileInfo1.FullName);
      if (fileInfo1.Extension.ToLower() == ".buprofile" & clsVar.appModes_0.ProfileMode.Enable)
      {
        clsInit.appProfile.SaveProfileJobFile(fileInfo1.FullName, true);
        buEyeBaseVer5.Apps.buProfileCalc.varProfileRunSettings.LastSavedProfileJobName = fileInfo1.FullName;
        clsInit.appProfile.SaveProfileFile();
      }
      else
      {
        if (fileInfo1.Extension.ToLower() == ".bucadv5")
        {
          DirectoryInfo directoryInfo = new DirectoryInfo($"{fileInfo1.DirectoryName}\\{withoutExtension}");
          if (directoryInfo.Exists)
            directoryInfo.Delete(true);
          Directory.CreateDirectory(directoryInfo.FullName);
          path = directoryInfo.FullName;
          ArrayList StringList = new ArrayList();
          buCadCamFileInfo buCadCamFileInfo = new buCadCamFileInfo();
          buCadCamFileInfo.ProgramVersionNo = Application.ProductVersion;
          string str = clsItem.FrmTempMisc.txt_notes.Text + Environment.NewLine + clsItem.FrmTempMaterial.txt_notes.Text;
          buCadCamFileInfo.Notes = str;
          buCadCamFileInfo.Notes = buCadCamFileInfo.Notes.Replace("\r\n", "{[NewLine]}");
          StringList.AddRange((ICollection) buCadCamFileInfo.ToDefAll("", 2, SerilizationMode.MultiLine).ToArray());
          for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; ++index)
            StringList.AddRange((ICollection) ccVars.Pages[ccVars.PageIndex].Layers[index].ToDefAll("", 2, SerilizationMode5.MultiLine).ToArray());
          for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Scene.Count - 1; ++index)
            StringList.AddRange((ICollection) ccVars.Pages[ccVars.PageIndex].Scene[index].ToDef("", 2).ToArray());
          for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1; ++index)
            StringList.AddRange((ICollection) ccVars.Pages[ccVars.PageIndex].Cams[index].ToDefAll("", 2, SerilizationMode5.MultiLine).ToArray());
          List<Entity> entityList = new List<Entity>();
          for (int index = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; index >= 0; --index)
          {
            if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].GetType() == typeof (buMaterial))
            {
              Entity entity = buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]);
              entityList.Add(entity);
              ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(index);
            }
          }
          buFile.SaveToFile(StringList, $"{directoryInfo.FullName}\\{withoutExtension}.busets");
          WriteFileParams writeFileParams = new WriteFileParams(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Document);
          writeFileParams.Content = contentType.GeometryAndTessellation;
          writeFileParams.SerializationMode = serializationType.Uncompressed;
          writeFileParams.SelectedOnly = false;
          writeFileParams.Purge = false;
          writeFileParams.Tag = MyFileSerializer.CustomTag;
          int SelectedCount = 0;
          clsInit.cVector5.getSelectedEntitiesCount(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref SelectedCount);
          if (SelectedCount > 0 & clsVar.varFile.IfSelectedAvailableSaveOnlySelected)
            writeFileParams.SelectedOnly = true;
          new WriteFile(writeFileParams, $"{directoryInfo.FullName}\\{withoutExtension}.bupage", (FileSerializer) new MyFileSerializer()).DoWork();
          FileInfo fileInfo2 = new FileInfo(FileName);
          if (fileInfo2.Exists)
            fileInfo2.Delete();
