  public void ModelOpenPreview_WorkCompleted(object sender, WorkCompletedEventArgs e)
  {
    try
    {
      bool flag1 = false;
      bool flag2 = false;
      if (e.WorkUnit is BallPivoting)
      {
        Mesh result = ((BallPivoting) e.WorkUnit).Result;
        result.EdgeStyle = Mesh.edgeStyleType.Free;
        clsItem.ModelOpenPreview.Entities.Clear();
        clsItem.ModelOpenPreview.Entities.Add((Entity) result, "Default", Color.Beige);
      }
      else if (e.WorkUnit is ReadFileAsync)
      {
        ReadFileAsync workUnit1 = (ReadFileAsync) e.WorkUnit;
        RegenOptions ro = new RegenOptions();
        bool flag3 = e.WorkUnit is ReadFile workUnit2 && workUnit2.Camera != null;
        clsItem.ModelOpenPreview.Shaded.ShadowMode = shadowType.None;
        clsItem.ModelOpenPreview.Rendered.ShadowMode = shadowType.None;
        clsItem.ModelOpenPreview.Rendered.SilhouettesDrawingMode = devDept.Eyeshot.silhouettesDrawingType.Never;
        clsItem.ModelOpenPreview.Rendered.PlanarReflections = false;
        workUnit1.OpenTo((IDesign) clsItem.ModelOpenPreview, ro);
        FileInfo fileInfo = new FileInfo(workUnit1.FilePath);
        if (clsItem.ModelOpenPreview.Layers.Count == 1 & fileInfo.Extension.ToLower() == ".stl" && clsItem.ModelOpenPreview.Layers[0].Color == Color.Black)
          clsItem.ModelOpenPreview.Layers[0].Color = Color.LightSeaGreen;
        if ((flag2 ? 0 : (!flag3 ? 1 : 0)) != 0)
          clsItem.ModelOpenPreview.SetView(viewType.Top, true, false);
        clsItem.ModelOpenPreview.CopyToClipboardRaster(new Size(this.openDialogCtrlPreview.picture_preview.Width, this.openDialogCtrlPreview.picture_preview.Height), true);
        this.openDialogCtrlPreview.picture_preview.Image = Clipboard.GetImage();
        this.openDialogCtrlPreview.ShowLoading(false);
      }
      else if (e.WorkUnit is Regeneration)
      {
        clsItem.ModelOpenPreview.UpdateBoundingBox();
        if (!flag1)
          clsItem.ModelOpenPreview.ZoomFit();
        clsItem.ModelOpenPreview.Invalidate();
      }
      clsVar.PreviewLoaded = true;
    }
    catch (Exception ex)
    {
      clsVar.PreviewLoaded = true;
    }
  }

