              for (int index2 = 0; index2 <= clsItem.ModelOpenInsert.Entities.Count - 1; ++index2)
              {
                if (clsItem.ModelOpenInsert.Entities[index2] is BlockReference)
                {
                  Entity[] collection = ((BlockReference) clsItem.ModelOpenInsert.Entities[index2]).Explode(clsItem.ModelOpenInsert.Blocks);
                  if (collection != null && collection.Length != 0)
                  {
                    List<Entity> entityList = new List<Entity>((IEnumerable<Entity>) collection);
                    entityListList2.Add(entityList);
                  }
                  intList.Add(index2);
                }
              }
              if (intList.Count > 0)
