                intList.Reverse();
                for (int index3 = 0; index3 <= intList.Count - 1; ++index3)
                  clsItem.ModelOpenInsert.Entities.RemoveAt(intList[index3]);
              }
              else
                index1 = 11;
              for (int index4 = 0; index4 <= entityListList2.Count - 1; ++index4)
              {
