          else if (clsVar.varEntities.InsertEntititesMode == InsertEntitiesTYpe.OriginalePosition)
            this.InsertFromFile(0.0, 0.0, 0.0);
          else if (clsVar.varEntities.InsertEntititesMode == InsertEntitiesTYpe.AddToMaxX | clsVar.varEntities.InsertEntititesMode == InsertEntitiesTYpe.AddToMaxY)
          {
            if (ccVars.Pages.Count > 0)
