  public void cmdInternalEntitiesToLayer()
  {
    try
    {
      if (ccVars.Pages.Count <= 0)
        return;
      this.Reset();
      List<EntitiesGroup> Groups = new List<EntitiesGroup>();
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData == null)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData = (object) new CustomData()
          {
            RefIndex = index
          };
        else if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData is CustomData)
          ((CustomData) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData).RefIndex = index;
        else
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData = (object) new CustomData()
          {
            RefIndex = index
          };
      }
      clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList<Entity>(), ccVars.planeActive, ref Groups);
      if (Groups.Count <= 0)
        return;
      DialogBoxList dialogBoxList = new DialogBoxList();
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; ++index)
      {
        LayerBase5 layerBase5 = new LayerBase5(ccVars.Pages[ccVars.PageIndex].Layers[index]);
        dialogBoxList.Items.Add($"[{(index + 1).ToString()}] {layerBase5.Name} - {layerBase5.LayerColor.ToString()}");
      }
      dialogBoxList.Init();
      int num = (int) dialogBoxList.ShowDialog();
      if (dialogBoxList.Result != DialogResult.OK)
        return;
      if (dialogBoxList.SelectedIndex >= 0 & dialogBoxList.SelectedIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)
      {
        string str = "";
        if (dialogBoxList.SelectedIndex >= 0 & dialogBoxList.SelectedIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)
          str = ccVars.Pages[ccVars.PageIndex].Layers[dialogBoxList.SelectedIndex].Name;
        for (int index1 = 0; index1 <= Groups.Count - 1; ++index1)
        {
          if (Groups[index1].Inside != null & str.Trim().Length > 0)
          {
            for (int index2 = 0; index2 <= Groups[index1].Inside.Count - 1; ++index2)
            {
              for (int index3 = 0; index3 <= Groups[index1].Inside[index2].Count - 1; ++index3)
              {
                if ((Groups[index1].Inside[index2][index3].EntityData == null ? 0 : (Groups[index1].Inside[index2][index3].EntityData is CustomData ? 1 : 0)) != 0)
                {
                  CustomData entityData = Groups[index1].Inside[index2][index3].EntityData as CustomData;
                  if (entityData.RefIndex >= 0 & entityData.RefIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
                    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[entityData.RefIndex].LayerName = str;
                }
              }
            }
          }
        }
      }
      this.Reset(ReDraw: true);
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

