  public void cmdEntitiesProperties()
  {
    F_EntitiesProps fEntitiesProps = new F_EntitiesProps();
    for (int index1 = 0; index1 <= ccVars.SelectionOP.Selections.Count - 1; ++index1)
    {
      int index2 = ccVars.SelectionOP.Selections[index1].Index;
      if (index2 >= 0 & index2 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
      {
        Entity entity = buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2]);
        fEntitiesProps.Entities.Add(entity);
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RegenAllCurved();
    fEntitiesProps.Layers.Clear();
    fEntitiesProps.InitViewport();
    fEntitiesProps.viewportPort.Layers = clsInit.cVector5.LayerCopy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers);
    fEntitiesProps.viewportPort.TextStyles = clsInit.cVector5.TextStyleCopy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.TextStyles);
    fEntitiesProps.viewportPort.HatchPatterns = clsInit.cVector5.HatchPatternCopy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.HatchPatterns);
    fEntitiesProps.viewportPort.Materials = clsInit.cVector5.MaterialCopy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Materials);
    fEntitiesProps.Init();
    int num = (int) fEntitiesProps.ShowDialog();
    fEntitiesProps.Entities.Clear();
    fEntitiesProps.Dispose();
  }

