  public void doMeshRemoveTrianlge(devDept.Geometry.Plane refPlane, Point3D pntLeftBottom, Point3D pntRigthTop)
  {
    for (int index = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; index >= 0; --index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is Mesh)
      {
        Mesh entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] as Mesh;
        MeshEditor meshEditor = new MeshEditor(entity.Vertices, entity.Triangles);
        int num = 0;
        for (int triangle = entity.Triangles.Length - 1; triangle >= 0; --triangle)
        {
          if (clsInit.cVector5.IsPointInsideBoxsize(entity.Vertices[entity.Triangles[triangle].V1], pntLeftBottom, pntRigthTop, refPlane))
          {
            meshEditor.DeleteTriangle(triangle);
            ++num;
          }
        }
        meshEditor.Apply();
        if ((num <= 0 || meshEditor.Vertices.Length <= 1 ? 0 : (meshEditor.Triangles.Length > 1 ? 1 : 0)) != 0)
        {
          Mesh mesh = new Mesh((IList<Point3D>) meshEditor.Vertices, (IList<IndexTriangle>) meshEditor.Triangles);
          mesh.Color = entity.Color;
          mesh.ColorMethod = entity.ColorMethod;
          mesh.LayerName = entity.LayerName;
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] = (Entity) mesh;
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Regen(0.1);
        }
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

