        {
          camTpPoint camTpPoint = new camTpPoint(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex].CamPoints[index1]);
          for (int index2 = 0; index2 <= camTpPoint.Points.Count - 1; ++index2)
            text = text + camTpPoint.Points[index2].ToString() + Environment.NewLine;
