  public void cmdCamMoveUp()
  {
    try
    {
      if (ccVars.Pages.Count <= 0 || !(ccVars.Pages[ccVars.PageIndex].Cams.Count >= 0 & ccVars.Pages[ccVars.PageIndex].CamIndex > 0 & ccVars.Pages[ccVars.PageIndex].CamIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1))
        return;
      camTp camTp = new camTp(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex]);
      ccVars.Pages[ccVars.PageIndex].Cams.RemoveAt(ccVars.Pages[ccVars.PageIndex].CamIndex);
      --ccVars.Pages[ccVars.PageIndex].CamIndex;
      ccVars.Pages[ccVars.PageIndex].Cams.Insert(ccVars.Pages[ccVars.PageIndex].CamIndex, camTp);
      this.CamsUpdate(true, ccVars.Pages[ccVars.PageIndex].CamIndex);
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void cmdCamMoveDown()
  {
    if (ccVars.Pages.Count <= 0 || !(ccVars.Pages[ccVars.PageIndex].Cams.Count >= 0 & ccVars.Pages[ccVars.PageIndex].CamIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 2 & ccVars.Pages[ccVars.PageIndex].CamIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1))
      return;
    camTp camTp = new camTp(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex]);
    ccVars.Pages[ccVars.PageIndex].Cams.RemoveAt(ccVars.Pages[ccVars.PageIndex].CamIndex);
    ++ccVars.Pages[ccVars.PageIndex].CamIndex;
    ccVars.Pages[ccVars.PageIndex].Cams.Insert(ccVars.Pages[ccVars.PageIndex].CamIndex, camTp);
    this.CamsUpdate(true, ccVars.Pages[ccVars.PageIndex].CamIndex);
  }

