  public void CamDraw(camTp cam, string LayerName = "")
  {
    bool flag = false;
    if (LayerName.Trim().Length > 0)
    {
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Name == LayerName)
          flag = true;
      }
    }
    if (clsVar.varCam.ShowCamG0Drawings)
    {
      for (int index = 0; index <= cam.EntitiesG0.Count - 1; ++index)
      {
        ccVars.UndoDont = true;
        Entity Ent = (Entity) null;
        this.CreateEntity(cam.EntitiesG0[index], ref Ent);
        if (Ent != null)
        {
          Ent.Color = clsVar.varCam.CamG0Draw.Color;
          Ent.LineWeight = clsVar.varCam.CamG0Draw.Thickness;
          Ent.ColorMethod = colorMethodType.byEntity;
          Ent.LineWeightMethod = colorMethodType.byEntity;
          if (flag)
          {
            Ent.LineTypeMethod = colorMethodType.byLayer;
            Ent.ColorMethod = colorMethodType.byLayer;
