  public void CamsUpdate(bool FillCam, int SelectedIndex)
  {
    try
    {
      if (clsItem.FrmTempCams == null)
        return;
      this.CamUpdating = true;
      if (ccVars.Pages[ccVars.PageIndex].Cams.Count != clsItem.FrmTempCams.tree_cam.Nodes.Count)
        FillCam = true;
      if (SelectedIndex >= 0 & SelectedIndex <= ccVars.Pages[ccVars.PageIndex].CamIndex)
        ccVars.Pages[ccVars.PageIndex].CamIndex = SelectedIndex;
      if (ccVars.Pages[ccVars.PageIndex].CamIndex >= ccVars.Pages[ccVars.PageIndex].Cams.Count)
        ccVars.Pages[ccVars.PageIndex].CamIndex = ccVars.Pages[ccVars.PageIndex].Cams.Count - 1;
      int num1 = Convert.ToInt32((object) CamType.Drill4X) + Convert.ToInt32((object) ToolType.Laser) + 3;
      int num2 = Convert.ToInt32((object) CamType.Drill4X) + Convert.ToInt32((object) ToolType.Laser) + 4;
      if (FillCam)
      {
        clsItem.FrmTempCams.tree_cam.Nodes.Clear();
        for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1; ++index)
        {
          TreeNodeSettings treeNodeSettings1 = new TreeNodeSettings(this.CamToName(ccVars.Pages[ccVars.PageIndex].Cams[index]));
          treeNodeSettings1.ImageIndex = Convert.ToInt32((object) ccVars.Pages[ccVars.PageIndex].Cams[index].TypeCam);
          treeNodeSettings1.SelectedImageIndex = Convert.ToInt32((object) ccVars.Pages[ccVars.PageIndex].Cams[index].TypeCam);
          treeNodeSettings1.Tag = (object) index.ToString();
          treeNodeSettings1.ClassIndex = index;
          treeNodeSettings1.ClassSubIndex = -1;
          treeNodeSettings1.ClassSubSubIndex = -1;
          treeNodeSettings1.Command = "cam";
          treeNodeSettings1.Checked = ccVars.Pages[ccVars.PageIndex].Cams[index].Enable;
          TreeNodeSettings node1 = treeNodeSettings1;
          string NodeText1 = "No Tool";
          int num3 = Convert.ToInt32((object) CamType.Drill4X) - Convert.ToInt32((object) CamType.None) + 1;
          if (ccVars.Pages[ccVars.PageIndex].Cams[index].Tool != null)
            NodeText1 = this.ToolToName(ccVars.Pages[ccVars.PageIndex].Cams[index].Tool);
          TreeNodeSettings treeNodeSettings2 = new TreeNodeSettings(NodeText1);
          treeNodeSettings2.ImageIndex = Convert.ToInt32((object) ccVars.Pages[ccVars.PageIndex].Cams[index].Tool.Geometry.GeometryType) + num3;
          treeNodeSettings2.SelectedImageIndex = Convert.ToInt32((object) ccVars.Pages[ccVars.PageIndex].Cams[index].Tool.Geometry.GeometryType) + num3;
          treeNodeSettings2.Tag = (object) index.ToString();
          treeNodeSettings2.ClassIndex = index;
          treeNodeSettings2.ClassSubIndex = index;
          treeNodeSettings2.ClassSubSubIndex = -1;
          treeNodeSettings2.Command = "tool";
          treeNodeSettings2.Checked = ccVars.Pages[ccVars.PageIndex].Cams[index].Enable;
          TreeNodeSettings node2 = treeNodeSettings2;
          node1.Nodes.Add((TreeNode) node2);
          string NodeText2 = "Parameter";
          int num4 = Convert.ToInt32((object) ToolType.Laser) + num3;
          TreeNodeSettings treeNodeSettings3 = new TreeNodeSettings(NodeText2);
          treeNodeSettings3.ImageIndex = num4 + 1;
          treeNodeSettings3.SelectedImageIndex = num4 + 1;
          treeNodeSettings3.Tag = (object) index.ToString();
          treeNodeSettings3.ClassIndex = index;
          treeNodeSettings3.ClassSubIndex = index;
          treeNodeSettings3.ClassSubSubIndex = -1;
          treeNodeSettings3.Command = "parameter";
          treeNodeSettings3.Checked = ccVars.Pages[ccVars.PageIndex].Cams[index].Enable;
          TreeNodeSettings node3 = treeNodeSettings3;
          node1.Nodes.Add((TreeNode) node3);
          TreeNodeSettings treeNodeSettings4 = new TreeNodeSettings("Toolpath Draw");
          treeNodeSettings4.ImageIndex = num2;
          treeNodeSettings4.SelectedImageIndex = num2;
          treeNodeSettings4.Tag = (object) index.ToString();
          treeNodeSettings4.ClassIndex = index;
          treeNodeSettings4.ClassSubIndex = index;
          treeNodeSettings4.ClassSubSubIndex = -1;
          treeNodeSettings4.Command = "toolpathvisible";
          treeNodeSettings4.Checked = ccVars.Pages[ccVars.PageIndex].Cams[index].Enable;
          TreeNodeSettings node4 = treeNodeSettings4;
          if (!ccVars.Pages[ccVars.PageIndex].Cams[index].Visible)
          {
            node4.ImageIndex = num1;
            node4.SelectedImageIndex = num1;
          }
          node1.Nodes.Add((TreeNode) node4);
          clsItem.FrmTempCams.tree_cam.Nodes.Add((TreeNode) node1);
        }
      }
      else
      {
        for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1; ++index)
        {
          clsItem.FrmTempCams.tree_cam.Nodes[index].Text = this.CamToName(ccVars.Pages[ccVars.PageIndex].Cams[index]);
          clsItem.FrmTempCams.tree_cam.Nodes[index].Nodes[0].Text = this.ToolToName(ccVars.Pages[ccVars.PageIndex].Cams[index].Tool);
          if (!ccVars.Pages[ccVars.PageIndex].Cams[index].Visible)
          {
            clsItem.FrmTempCams.tree_cam.Nodes[index].Nodes[2].ImageIndex = num1;
            clsItem.FrmTempCams.tree_cam.Nodes[index].Nodes[2].SelectedImageIndex = num1;
          }
          else
          {
            clsItem.FrmTempCams.tree_cam.Nodes[index].Nodes[2].ImageIndex = num2;
            clsItem.FrmTempCams.tree_cam.Nodes[index].Nodes[2].SelectedImageIndex = num2;
          }
        }
      }
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].CamIndex - 1; ++index)
        clsItem.FrmTempCams.tree_cam.Nodes[index].ForeColor = Color.Black;
      for (int index = ccVars.Pages[ccVars.PageIndex].CamIndex + 1; index <= clsItem.FrmTempCams.tree_cam.Nodes.Count - 1; ++index)
        clsItem.FrmTempCams.tree_cam.Nodes[index].ForeColor = Color.Black;
      if (ccVars.Pages[ccVars.PageIndex].CamIndex >= 0 & ccVars.Pages[ccVars.PageIndex].CamIndex <= clsItem.FrmTempCams.tree_cam.Nodes.Count - 1)
        clsItem.FrmTempCams.tree_cam.Nodes[ccVars.Pages[ccVars.PageIndex].CamIndex].ForeColor = Color.Red;
      this.CamUpdating = false;
    }
    catch (Exception ex)
    {
      this.CamUpdating = false;
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public string CamToName(camTp Cam)
  {
    string str = "";
    if (Cam.Name.Trim().Length > 0)
      str = Cam.Name + " ";
    return str + Cam.TypeCam.ToString();
  }

  public void CamControlResize(bool Vertical, bool Horizontal)
  {
    try
    {
      int height1 = clsItem.tabcontrolLeft.Height;
      int width1 = clsItem.tabcontrolLeft.Width;
      if (clsVar.varProgram.ToolLocation == LeftRightAlignment.Right)
      {
        height1 = clsItem.tabcontrolRight.Height;
        width1 = clsItem.tabcontrolRight.Width;
      }
      if (Vertical)
        clsItem.FrmTempCams.pnl_controls.Height = height1;
      if (Horizontal)
        clsItem.FrmTempCams.pnl_controls.Width = width1 - 50;
      if (clsVar.varProgram.CamLocation != LeftRightAlignment.Right)
        return;
      int height2 = clsItem.tabcontrolRight.Height;
      int width2 = clsItem.tabcontrolRight.Width;
    }
    catch (Exception ex)
    {
      Console.WriteLine((object) ex);
      throw;
    }
  }

  public void Cam_AfterSelect(object sender, TreeViewEventArgs e)
  {
    TreeNodeSettings node = (TreeNodeSettings) e.Node;
    if (!(node.ClassIndex >= 0 & node.ClassIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1))
      return;
    ccVars.Pages[ccVars.PageIndex].CamIndex = node.ClassIndex;
    this.CamsUpdate(false, ccVars.Pages[ccVars.PageIndex].CamIndex);
    this.CamInfo(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex], clsVar.varProgram.CamPanelSettings);
  }

  public void Cam_DoubleClick(object sender, EventArgs e)
  {
    if (clsItem.FrmTempCams.tree_cam.SelectedNode == null || !(clsItem.FrmTempCams.tree_cam.SelectedNode.GetType() == typeof (TreeNodeSettings)))
      return;
    TreeNodeSettings treeNodeSettings = new TreeNodeSettings();
    TreeNodeSettings selectedNode = (TreeNodeSettings) clsItem.FrmTempCams.tree_cam.SelectedNode;
    if (!(selectedNode.ClassSubIndex >= 0 & selectedNode.ClassSubIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1))
      return;
    if (selectedNode.Command == "toolpathvisible")
    {
      ccVars.Pages[ccVars.PageIndex].Cams[selectedNode.ClassSubIndex].Visible = !ccVars.Pages[ccVars.PageIndex].Cams[selectedNode.ClassSubIndex].Visible;
      this.CamsUpdate(false, ccVars.Pages[ccVars.PageIndex].CamIndex);
      this.CamEntitiesSetVisibily(ccVars.Pages[ccVars.PageIndex].Cams[selectedNode.ClassSubIndex].CamID, ccVars.Pages[ccVars.PageIndex].Cams[selectedNode.ClassSubIndex].Visible);
    }
    if (!(selectedNode.Command == "tool"))
      return;
    F_ToolList fToolList = new F_ToolList();
    for (int index1 = 0; index1 <= ccVars.Tools.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= ccVars.Tools[index1].Tools.Count - 1; ++index2)
        fToolList.Tools.Add(new ToolBase5(ccVars.Tools[index1].Tools[index2]));
    }
    fToolList.SelectedTool = new ToolBase5(ccVars.Pages[ccVars.PageIndex].Cams[selectedNode.ClassSubIndex].Tool);
    fToolList.Init();
    int num = (int) fToolList.ShowDialog();
    if (fToolList.PropertiesForm.Result != DialogResult.OK)
      return;
    this.CamsUpdate(false, ccVars.Pages[ccVars.PageIndex].CamIndex);
    this.CamEntitiesSetVisibily(ccVars.Pages[ccVars.PageIndex].Cams[selectedNode.ClassSubIndex].CamID, ccVars.Pages[ccVars.PageIndex].Cams[selectedNode.ClassSubIndex].Visible);
  }

