  public void CamRemoveEntities(int CamID)
  {
    try
    {
      for (int index = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; index >= 0; --index)
      {
        Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index];
        int camId = clsInit.cVector5.GetCamID(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]);
        if (CamID >= 0)
        {
          if (camId == CamID)
          {
            if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is buLineCam | ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is buArcCam | ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is buLinearPathCam | ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is buCompositeCurveCam)
              ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(index);
            else if ((entity.EntityData == null ? 0 : (entity.EntityData is CustomData ? 1 : 0)) != 0 && clsInit.cVector5.isEntityCamEntity(entity))
              ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(index);
          }
        }
        else if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is buLineCam | ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is buArcCam | ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is buLinearPathCam | ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is buCompositeCurveCam)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(index);
        else if ((entity.EntityData == null ? 0 : (entity.EntityData is CustomData ? 1 : 0)) != 0 && clsInit.cVector5.isEntityCamEntity(entity))
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(index);
      }
    }
    catch (Exception ex)
    {
    }
  }

  public void CamAvailableIDGet(ref int AvailableCamID)
  {
    if (ccVars.Pages.Count <= 0)
      return;
    AvailableCamID = 1;
    List<int> source = new List<int>();
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1; ++index)
      source.Add(ccVars.Pages[ccVars.PageIndex].Cams[index].CamID);
    if (source.Count > 0)
    {
      int num = source.Max();
      AvailableCamID = num + 1;
    }
    else
      AvailableCamID = ccVars.Pages[ccVars.PageIndex].Cams.Count + 1;
  }

  public void CamInfo(camTp cam, CamPanelSetting Settings)
  {
    if (clsItem.FrmTempCams == null)
      return;
    clsItem.FrmTempCams.txt_camexplanatiom.Text = "";
    if (Settings.ShowCamName)
      clsItem.FrmTempCams.txt_camexplanatiom.Text = $"{clsItem.FrmTempCams.txt_camexplanatiom.Text}{AppLanguage.CadCamDynamic[40]} : {cam.Name}{Environment.NewLine}";
    if (Settings.ShowCamType)
      clsItem.FrmTempCams.txt_camexplanatiom.Text = $"{clsItem.FrmTempCams.txt_camexplanatiom.Text}{AppLanguage.CadCamDynamic[84]} : {cam.TypeCam.ToString()}{Environment.NewLine}";
    if (Settings.ShowTool)
      clsItem.FrmTempCams.txt_camexplanatiom.Text = $"{clsItem.FrmTempCams.txt_camexplanatiom.Text}{AppLanguage.CadCamDynamic[25]} : {cam.Tool.Data.Name} | {AppLanguage.CadCamDynamic[84]}: {cam.Tool.Geometry.GeometryType.ToString()}{Environment.NewLine}";
    if (Settings.ShowProcessTime)
      clsItem.FrmTempCams.txt_camexplanatiom.Text = $"{clsItem.FrmTempCams.txt_camexplanatiom.Text}{AppLanguage.CadCamDynamic[85]} : {cam.Information.AllProcessTime}{Environment.NewLine}";
    if (!Settings.ShowTotalLength)
      return;
    clsItem.FrmTempCams.txt_camexplanatiom.Text = $"{clsItem.FrmTempCams.txt_camexplanatiom.Text}{AppLanguage.CadCamDynamic[0]} : {cam.Information.TotalLength.ToString()}{Environment.NewLine}";
  }

  public void CamReCalculate()
  {
    camTp camTp = new camTp(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex]);
    if (camTp.Action == actionTypeBU.camJewel3AXContour | camTp.Action == actionTypeBU.camJewel3AXPocket | camTp.Action == actionTypeBU.camJewel4AXContour | camTp.Action == actionTypeBU.camJewel4AXSpinRamp | camTp.Action == actionTypeBU.camJewel3AXSpinConstant | camTp.Action == actionTypeBU.camJewel3AXPunch | camTp.Action == actionTypeBU.camJewel4AXPunch | camTp.Action == actionTypeBU.camJewel4AXPointRotation | camTp.Action == actionTypeBU.camJewel3AXTriMeshRough | camTp.Action == actionTypeBU.camJewel3AXTriMeshParalelCut | camTp.Action == actionTypeBU.camJewel3AXTriMeshConstantZ)
    {
      camTp NewCam = new camTp();
      if (clsInit.appJewel.cmdCamContourReCalculate(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex], ref NewCam) >= 1)
      {
        this.CamRemoveEntities(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex].CamID);
        ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex] = NewCam;
        this.CamInfo(NewCam, clsVar.varProgram.CamPanelSettings);
        this.CamDraw(NewCam);
        this.CamsUpdate(true, ccVars.Pages[ccVars.PageIndex].CamIndex);
      }
    }
    if (!(camTp.Action == actionTypeBU.camContours | camTp.Action == actionTypeBU.camContours4AX | camTp.Action == actionTypeBU.camPocketing | camTp.Action == actionTypeBU.camDrill | camTp.Action == actionTypeBU.camTriangularMesh3DRough | camTp.Action == actionTypeBU.camTriangularMesh3DParalelCut | camTp.Action == actionTypeBU.camTriangularMesh3DConstantZ))
      return;
    camTp NewCam1 = new camTp();
    if (this.CamCalcReCalculate(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex], ref NewCam1) < 1)
      return;
    this.CamRemoveEntities(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex].CamID);
    ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex] = NewCam1;
    this.CamInfo(NewCam1, clsVar.varProgram.CamPanelSettings);
    this.CamDraw(NewCam1);
    this.CamsUpdate(true, ccVars.Pages[ccVars.PageIndex].CamIndex);
  }

  public int CamCalcReCalculate(camTp OldCam, ref camTp NewCam)
  {
    try
    {
      MWCalculationOptions MWCalcoptions = new MWCalculationOptions(OldCam.MWCalcOptions);
      clsMW.CamEntities.Clear();
      if (OldCam.Action == actionTypeBU.camContours)
      {
        clsVar.varCamWFContourPars.mwPar.MachParam = new MachiningParams((MachiningParams) OldCam.mwParameter);
        clsVar.varCamWFContourPars.buPar = new camParameters5(OldCam.Parameter);
        clsMW.CamEntities.Clear();
        clsMW.CamEntities = new List<Entity>();
        buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
        MWCalcoptions.AddToCamListInLocalCalculation = false;
        NewCam = new camTp();
        return this.doWireframeContour(MWCalcoptions, ccVars.toolActive, OldCam.Action, ref NewCam);
      }
      if (OldCam.Action == actionTypeBU.camPocketing)
      {
        clsVar.varCamWFPocketPars.mwPar.MachParam = new MachiningParams((MachiningParams) OldCam.mwParameter);
        clsVar.varCamWFPocketPars.buPar = new camParameters5(OldCam.Parameter);
        clsMW.CamEntities.Clear();
        clsMW.CamEntities = new List<Entity>();
        buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
        MWCalcoptions.AddToCamListInLocalCalculation = false;
        NewCam = new camTp();
        return this.doWireframeContour(MWCalcoptions, ccVars.toolActive, OldCam.Action, ref NewCam);
      }
      if (OldCam.Action == actionTypeBU.camContours4AX)
      {
        clsVar.varCamWFContour4XPars.mwPar.MachParam = new MachiningParams((MachiningParams) OldCam.mwParameter);
        clsVar.varCamWFContour4XPars.buPar = new camParameters5(OldCam.Parameter);
        clsMW.CamEntities.Clear();
        clsMW.CamEntities = new List<Entity>();
        buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
        MWCalcoptions.AddToCamListInLocalCalculation = false;
        NewCam = new camTp();
        return this.doWireframeContour(MWCalcoptions, ccVars.toolActive, OldCam.Action, ref NewCam);
      }
      if (OldCam.Action == actionTypeBU.camDrill)
      {
        clsVar.varCamDrillPars.mwPar.MachParam = new MachiningParams((MachiningParams) OldCam.mwParameter);
        clsVar.varCamDrillPars.buPar = new camParameters5(OldCam.Parameter);
        clsMW.CamEntities.Clear();
        clsMW.CamEntities = new List<Entity>();
        buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
        MWCalcoptions.AddToCamListInLocalCalculation = false;
        NewCam = new camTp();
        return this.doDrill(MWCalcoptions, ccVars.toolActive, OldCam.Action, ref NewCam);
      }
      if (OldCam.Action == actionTypeBU.camTriangularMesh3DRough)
      {
        clsVar.varCamMeshRoughPars.mwPar.MachParam = new MachiningParams((MachiningParams) OldCam.mwParameter);
        clsVar.varCamMeshRoughPars.buPar = new camParameters5(OldCam.Parameter);
        clsMW.CamEntities.Clear();
        clsMW.CamEntities = new List<Entity>();
        buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
        MWCalcoptions.AddToCamListInLocalCalculation = false;
        NewCam = new camTp();
        return this.doTriangleMesh(MWCalcoptions, ccVars.toolActive, OldCam.Action, ref NewCam);
      }
      if (OldCam.Action == actionTypeBU.camTriangularMesh3DParalelCut)
      {
        clsVar.varCamMeshParallelPars.mwPar.MachParam = new MachiningParams((MachiningParams) OldCam.mwParameter);
        clsVar.varCamMeshParallelPars.buPar = new camParameters5(OldCam.Parameter);
        clsMW.CamEntities.Clear();
        clsMW.CamEntities = new List<Entity>();
        buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
        MWCalcoptions.AddToCamListInLocalCalculation = false;
        NewCam = new camTp();
        return this.doTriangleMesh(MWCalcoptions, ccVars.toolActive, OldCam.Action, ref NewCam);
      }
      if (OldCam.Action != actionTypeBU.camTriangularMesh3DConstantZ)
        return -1;
      clsVar.varCamMeshConstantZPars.mwPar.MachParam = new MachiningParams((MachiningParams) OldCam.mwParameter);
      clsVar.varCamMeshConstantZPars.buPar = new camParameters5(OldCam.Parameter);
      clsMW.CamEntities.Clear();
      clsMW.CamEntities = new List<Entity>();
      buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
      MWCalcoptions.AddToCamListInLocalCalculation = false;
      NewCam = new camTp();
      return this.doTriangleMesh(MWCalcoptions, ccVars.toolActive, OldCam.Action, ref NewCam);
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
      return -1;
    }
  }

  public void CamEntitiesSetVisibily(int CamID, bool Visible)
  {
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].GetType() == typeof (buLinearPathCam) && ((buLinearPathCam) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).CamID == CamID)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Visible = Visible;
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void simStart()
  {
    if (ccVars.Pages.Count <= 0)
      return;
    if (ccVars.SimCamBaseIndex >= 0 & ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)
    {
      clsItem.timSim.Enabled = true;
    }
    else
    {
      if (ccVars.Pages[ccVars.PageIndex].Cams.Count == 0 || !(ccVars.SimCamBaseIndex < 0 & ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1))
        return;
      ccVars.SimCamBaseIndex = 0;
      if (ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool == null)
        ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool = new ToolBase5();
      if (ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic == null)
        ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic = new KinematicBase5();
      this.SimMachinePartAdd(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool, ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation(new int?(clsVar.varSimulation.SimulationInterval));
      clsItem.timSim.Enabled = true;
      clsFiles.SaveParameter();
    }
  }

  public void simToolCreate(ToolBase5 Tool, KinematicBase5 Kinematic)
  {
    if (ccVars.Pages.Count <= 0)
      return;
    this.SimMachinePartAdd(Tool, Kinematic);
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation(new int?(clsVar.varSimulation.SimulationInterval));
  }

