  {
    if (ccVars.Pages.Count <= 0)
      return;
    if (ccVars.SimCamBaseIndex >= 0 & ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)
      this.Sim_Tick((object) null, (EventArgs) null);
    if (ccVars.SimCamBaseIndex < 0)
      ;
  }

  public void simPre()
  {
    if (ccVars.Pages.Count <= 0 || ccVars.SimCamBaseIndex < 0 || !(ccVars.SimCamBaseIndex >= 0 & ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1))
      return;
    ccVars.SimCamPointIndex -= clsVar.varInterface.CamSimulationStep * 2;
    if (ccVars.SimCamPointIndex < 0 && ccVars.SimCamBaseIndex > 0)
    {
      --ccVars.SimCamBaseIndex;
      ccVars.SimCamPointIndex = ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationPoint.SimMove.Count - 1;
    }
    this.Sim_Tick((object) null, (EventArgs) null);
  }

  public void simNextGroup()
  {
    if (ccVars.Pages.Count <= 0 || !(ccVars.SimCamBaseIndex >= 0 & ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1) || ccVars.SimCamBaseIndex >= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)
      return;
    ++ccVars.SimCamBaseIndex;
    ccVars.SimCamPointIndex = 0;
    this.Sim_Tick((object) null, (EventArgs) null);
  }

  public void simPreGroup()
  {
    if (ccVars.Pages.Count <= 0 || !(ccVars.SimCamBaseIndex >= 0 & ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1) || ccVars.SimCamBaseIndex <= 0)
      return;
    --ccVars.SimCamBaseIndex;
    ccVars.SimCamPointIndex = 0;
    this.Sim_Tick((object) null, (EventArgs) null);
  }

  public void SimMachinePartAdd(ToolBase5 Tool, KinematicBase5 Kinematic)
  {
    List<Mesh> refMeshes = new List<Mesh>();
    if (!Tool.Geometry.FromFileEnable)
    {
      if (Tool.Geometry.ToolDirection.X != 0.0 | Tool.Geometry.ToolDirection.Y != 0.0)
        clsInit.appMW.CreateToolWithToolDirection(Tool, true, Tool.Geometry.DrawLength, Tool.Geometry.DrawArbor, Tool.Geometry.DrawHolder, false, ref refMeshes);
      else
        clsInit.appMW.CreateTool(Tool, true, Tool.Geometry.DrawLength, Tool.Geometry.DrawArbor, Tool.Geometry.DrawHolder, ref refMeshes);
    }
    else
    {
      FileInfo fileInfo = new FileInfo(Tool.Geometry.FromFileFileName);
      if (fileInfo.Exists)
      {
        Design design = new Design();
        ReadSTL readStl = new ReadSTL(fileInfo.FullName);
        readStl.DoWork();
        readStl.OpenTo((IDesign) design);
        if (design.Entities.Count > 0)
        {
          for (int index = 0; index <= design.Entities.Count - 1; ++index)
          {
            if (design.Entities[index] is Mesh)
            {
              Mesh mesh = (Mesh) design.Entities[index].Clone();
              mesh.ColorMethod = colorMethodType.byEntity;
              if (mesh.Color == Color.Black)
                mesh.Color = Color.DarkGray;
              mesh.Rotate(buConversion5.DegreeToRadian(Tool.Geometry.FromFileAngle), new Vector3D(0.0, 0.0, 1.0));
              refMeshes.Add(mesh);
            }
          }
        }
      }
    }
    this.SimToolRemove();
    Block block = new Block(nameof (Tool));
    Mesh mesh1 = new Mesh();
    if (refMeshes.Count == 1)
    {
      for (int index = 0; index <= refMeshes.Count - 1; ++index)
      {
        refMeshes[index].ColorMethod = colorMethodType.byEntity;
        if (Tool.Geometry.GeometryType == ToolType.Saw)
        {
          refMeshes[index].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 1.0, 0.0), new Point3D(0.0, 0.0, 0.0));
          refMeshes[index].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 0.0, 1.0), new Point3D(0.0, 0.0, 0.0));
          refMeshes[index].Translate(0.0 + Kinematic.MovePartRuntimeOffset.X, 0.0 + Kinematic.MovePartRuntimeOffset.Y, -(Tool.Geometry.Thickness / 1.0) + Kinematic.MovePartRuntimeOffset.Z);
        }
        block.Entities.Add((Entity) refMeshes[index]);
      }
    }
    else
    {
      for (int index = 0; index <= refMeshes.Count - 1; ++index)
      {
        refMeshes[index].ColorMethod = colorMethodType.byEntity;
        if (Tool.Geometry.GeometryType == ToolType.Saw)
        {
          refMeshes[index].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 1.0, 0.0), new Point3D(0.0, 0.0, 0.0));
          refMeshes[index].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 0.0, 1.0), new Point3D(0.0, 0.0, 0.0));
          refMeshes[index].Translate(0.0 + Kinematic.MovePartRuntimeOffset.X, 0.0 + Kinematic.MovePartRuntimeOffset.Y, -(Tool.Geometry.Thickness / 1.0) + Kinematic.MovePartRuntimeOffset.Z);
        }
        block.Entities.Add((Entity) refMeshes[index]);
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(block);
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add((Entity) new buTool(nameof (Tool))
    {
      CRotation = Tool.Limits.RotationC,
      BRotation = Tool.Limits.RotationB,
      ARotation = Tool.Limits.RotationA
    });
    ccVars.SimToolEntityIndex = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1;
  }

