  public void Sim_Tick(object sender, EventArgs e)
  {
    if (ccVars.Pages.Count <= 0)
      return;
    if (ccVars.SimCamBaseIndex > ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)
    {
      ccVars.SimCamBaseIndex = -1;
      ccVars.SimCamPointIndex = 0;
      clsItem.timSim.Enabled = false;
      this.simStop();
    }
    else
    {
      if (ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)
      {
        if (ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Enable)
        {
          if (ccVars.SimCamPointIndex >= 0 & ccVars.SimCamPointIndex <= ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationPoint.SimMove.Count - 1)
          {
            ccVars.pntSimulation = new Pnt6DSimMove(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationPoint.SimMove[ccVars.SimCamPointIndex]);
            Pnt3D pnt3D1 = new Pnt3D(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool.CamData.SimMoveOffset);
            if (clsItem.FrmTempCams != null)
            {
              TextBox txtSimx = clsItem.FrmTempCams.txt_simx;
              double num1 = Math.Round(ccVars.pntSimulation.X, 3);
              string str1 = num1.ToString();
              txtSimx.Text = str1;
              TextBox txtSimy = clsItem.FrmTempCams.txt_simy;
              num1 = Math.Round(ccVars.pntSimulation.Y, 3);
              string str2 = num1.ToString();
              txtSimy.Text = str2;
              TextBox txtSimz = clsItem.FrmTempCams.txt_simz;
              double num2 = Math.Round(ccVars.pntSimulation.Z, 3);
              string str3 = num2.ToString();
              txtSimz.Text = str3;
              TextBox txtSima = clsItem.FrmTempCams.txt_sima;
              num2 = Math.Round(ccVars.pntSimulation.A, 3);
              string str4 = num2.ToString();
              txtSima.Text = str4;
              TextBox txtSimb = clsItem.FrmTempCams.txt_simb;
              double num3 = Math.Round(ccVars.pntSimulation.B, 3);
              string str5 = num3.ToString();
              txtSimb.Text = str5;
              TextBox txtSimc = clsItem.FrmTempCams.txt_simc;
              num3 = Math.Round(ccVars.pntSimulation.C, 3);
              string str6 = num3.ToString();
              txtSimc.Text = str6;
            }
            Pnt3D pnt3D2 = new Pnt3D(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfA.X - ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfC.X, ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfA.Y - ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfC.Y, ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfA.Z - ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfC.Z);
            if (ccVars.SimToolEntityIndex >= 0 & ccVars.SimToolEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
            {
              buTool entity1 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex] as buTool;
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).xRot = pnt3D2.X;
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).yRot = pnt3D2.Y;
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).zRot = pnt3D2.Z;
              buTool entity2 = (buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex];
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).xPos = ccVars.pntSimulation.X + ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationToolOffset.X;
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).yPos = ccVars.pntSimulation.Y + ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationToolOffset.Y;
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).zPos = ccVars.pntSimulation.Z + ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationToolOffset.Z;
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).aPos = ccVars.pntSimulation.A;
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).bPos = ccVars.pntSimulation.B;
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).cPos = ccVars.pntSimulation.C;
            }
            ccVars.SimCamPointIndex += clsVar.varInterface.CamSimulationStep;
          }
          else
          {
            ++ccVars.SimCamBaseIndex;
            ccVars.SimCamPointIndex = 0;
            if (ccVars.SimCamBaseIndex >= 0 & ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)
            {
              clsInit.appCommand.SimMachinePartAdd(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool, ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic);
            }
            else
            {
              ccVars.SimCamBaseIndex = -1;
              ccVars.SimCamPointIndex = 0;
              clsItem.timSim.Enabled = false;
              this.simStop();
            }
          }
        }
        else
          ++ccVars.SimCamBaseIndex;
      }
      else
      {
        ccVars.SimCamBaseIndex = -1;
        ccVars.SimCamPointIndex = 0;
        clsItem.timSim.Enabled = false;
        this.simStop();
      }
      if (clsInit.appPrinter3D != null)
        clsInit.appPrinter3D.Sim_Tick((object) null, (EventArgs) null);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
      if (!ccVars.SimStopAfterExecute)
        return;
      this.simStop();
      ccVars.SimStopAfterExecute = false;
    }
  }

  public void GetSimPointFromReverseKinematic(
    Pnt6D RefPoint,
    ToolBase5 Tool,
    KinematicBase Kinematic,
    ref Pnt6D CalcPoint)
  {
    try
    {
      if (Kinematic != null)
      {
        if (Kinematic.Type == KinemeticType.CartezianXYZ_3Axis)
        {
          CalcPoint = new Pnt6D(RefPoint);
        }
        else
        {
          double ToolLength = Tool.Geometry.Length;
          if (Tool.Geometry.GeometryType == ToolType.Saw)
            ToolLength = Tool.Geometry.Diameter / 2.0;
          clsInit.cKinematic.ReverseKinematix5Ax(ToolLength, Kinematic, new OrientationAngle(RefPoint), new Pnt3D(RefPoint), ref CalcPoint);
          CalcPoint.Z = CalcPoint.Z - Kinematic.RotateCenterOffsetOfC.Z + Kinematic.RotateCenterOffsetOfA.Z;
        }
      }
      else
        CalcPoint = new Pnt6D(RefPoint);
    }
    catch (Exception ex)
    {
      string str = "RefPoint: " + RefPoint.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

