  public void cmdAnalyseEntities()
  {
    try
    {
      AnalyseEntitiesResult Result = new AnalyseEntitiesResult();
      List<Entity> copiedEnt = new List<Entity>();
      buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref copiedEnt);
      clsInit.cVector5.AnalyseEntities(copiedEnt, clsVar.varInterface5.AnalyseEntitySetting, ref Result);
      if (Result.isError)
      {
        for (int index = 0; index <= copiedEnt.Count - 1; ++index)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = copiedEnt[index].Selected;
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
        F_AnalyseResult fAnalyseResult = new F_AnalyseResult();
        fAnalyseResult.Result = new AnalyseEntitiesResult(Result);
        fAnalyseResult.Init();
        int num = (int) fAnalyseResult.ShowDialog();
        if (fAnalyseResult.PropertiesForm.Result != DialogResult.OK)
          return;
        for (int index = 0; index <= copiedEnt.Count - 1; ++index)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = false;
        for (int index = 0; index <= fAnalyseResult.Result.ErrorList.Count - 1; ++index)
        {
          int indexEntity = fAnalyseResult.Result.ErrorList[index].IndexEntity;
          if (indexEntity >= 0 & indexEntity <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1 && fAnalyseResult.Result.ErrorList[index].Action == AnalyseEntitiesActionType.Delete & fAnalyseResult.Result.ErrorList[index].Enable)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[indexEntity].Selected = true;
        }
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
      }
      else
        buString5.MessageBoxInfo(AppLanguage.CadCamMessages[89]);
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

