  public void cmdMaterialAdd()
  {
    try
    {
      MaterialBase5 mat = !(clsVar.varInterface.MaterialIndex >= 0 & clsVar.varInterface.MaterialIndex <= ccVars.MaterialList.Count - 1) ? new MaterialBase5() : new MaterialBase5(ccVars.MaterialList[clsVar.varInterface.MaterialIndex]);
      clsItem.FrmMaterial = new F_Material();
      clsInit.cVector5.CreateModelControl(ref clsItem.FrmMaterial.viewportLayout, clsVar.UnlockKey, new CreateModelProperties()
      {
        CoordinateSystemIconVisible = false,
        ViewCubeIconVisible = false,
        OrigineCaptionVisible = false,
        ToolBorVisible = false
      });
      clsItem.FrmMaterial.pnl_model.Controls.Add((System.Windows.Forms.Control) clsItem.FrmMaterial.viewportLayout);
      clsItem.FrmMaterial.viewportLayout.Entities.Clear();
      clsItem.FrmMaterial.Properties.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmMaterial.Material = new MaterialBase5(mat);
      clsItem.FrmMaterial.Init();
      clsItem.FrmMaterial.StartPosition = FormStartPosition.CenterParent;
      int num = (int) clsItem.FrmMaterial.ShowDialog();
      if (clsItem.FrmMaterial.Properties.Result != DialogResult.OK)
        return;
      bool flag = false;
      for (int index = 0; index <= ccVars.MaterialList.Count - 1; ++index)
      {
        if (ccVars.MaterialList[index].Name.Trim().ToLower() == clsItem.FrmMaterial.Material.Name.Trim().ToLower())
          flag = true;
      }
      if (flag)
      {
        buString.MessageBoxWarning($"{AppLanguage.CadCamMessages[87]}{Environment.NewLine}{Environment.NewLine}[ {clsItem.FrmMaterial.Material.Name} ]");
      }
      else
      {
        ccVars.MaterialList.Add(new MaterialBase5(clsItem.FrmMaterial.Material));
