  public void cmdMaterialSave()
  {
    try
    {
      SaveFileDialog saveFileDialog = new SaveFileDialog();
      saveFileDialog.InitialDirectory = clsVar.varInterface.pathData;
      saveFileDialog.Filter = "buCad/Cam Material File (*.bumats)|*.bumats";
      saveFileDialog.FilterIndex = 1;
      if (saveFileDialog.ShowDialog() != DialogResult.OK)
        return;
      FileInfo fileInfo = new FileInfo(saveFileDialog.FileName);
      clsVar.varInterface.pathData = fileInfo.DirectoryName;
      ArrayList StringList = new ArrayList();
      StringList.Add((object) "------------------------------------------------------------------------");
      StringList.Add((object) "   Material ");
      StringList.Add((object) "------------------------------------------------------------------------");
      StringList.Add((object) "  <Material>");
      for (int index = 0; index <= ccVars.MaterialList.Count - 1; ++index)
        StringList.AddRange((ICollection) ccVars.MaterialList[index].ToDefAll("", 4, SerilizationMode5.MultiLine));
      StringList.Add((object) "  </Material>");
      buFile.SaveToFile(StringList, saveFileDialog.FileName);
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void cmdMaterialOpen()
  {
    try
    {
      OpenFileDialog openFileDialog = new OpenFileDialog();
      openFileDialog.InitialDirectory = clsVar.varInterface.pathData;
      openFileDialog.Multiselect = false;
      openFileDialog.Filter = "buCad/Cam Material File (*.bumats)|*.bumats";
      openFileDialog.FilterIndex = 1;
      if (openFileDialog.ShowDialog() != DialogResult.OK)
        return;
      FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
      clsVar.varInterface.pathData = fileInfo.DirectoryName;
      List<List<string>> CalcList = new List<List<string>>();
      ArrayList StringList = new ArrayList();
      buFile.OpenFromFile(fileInfo.FullName, ref StringList);
      buString.ListToSpecificList("<MaterialBase5>", "</MaterialBase5>", true, StringList, ref CalcList);
      if (CalcList.Count > 0)
        ccVars.MaterialList.Clear();
      for (int index = 0; index <= CalcList.Count - 1; ++index)
      {
        ArrayList AL = new ArrayList();
        AL.AddRange((ICollection) CalcList[index].ToArray());
        MaterialBase5 materialBase5 = new MaterialBase5();
        buSerilization.Decode(AL, "", SerilizationMode.MultiLine, (object) materialBase5);
        ccVars.MaterialList.Add(materialBase5);
      }
      clsFiles.SaveParameter();
      this.MaterialUpdate(true, 0);
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void cmdMaterialMoveUp()
  {
    try
    {
      if (!(ccVars.MaterialList.Count >= 0 & clsVar.varInterface.MaterialIndex > 0 & clsVar.varInterface.MaterialIndex <= ccVars.MaterialList.Count - 1))
