  public void MaterialInfo(MaterialBase5 Mat)
  {
    clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = "";
    clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[40]} : {Mat.Name}{Environment.NewLine}";
    clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[84]} : {Mat.Shapes.ToString()}{Environment.NewLine}";
    if (Mat.Shapes == MaterialShapes.Rectangle)
    {
      clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[15]} : {Mat.Size.Width.ToString()}{Environment.NewLine}";
      clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[16 /*0x10*/]} : {Mat.Size.Height.ToString()}{Environment.NewLine}";
    }
    if (Mat.Shapes == MaterialShapes.Circle)
      clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[19]} : {Mat.Radius.ToString()}{Environment.NewLine}";
    if (Mat.Shapes == MaterialShapes.Ellipse)
    {
      clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[15]} : {Mat.MajorRadius.ToString()}{Environment.NewLine}";
      clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[16 /*0x10*/]} : {Mat.MinorRadius.ToString()}{Environment.NewLine}";
    }
    if (Mat.Shapes == MaterialShapes.Irregular)
    {
      clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[15]} : {Mat.Size.Width.ToString()}{Environment.NewLine}";
      clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[16 /*0x10*/]} : {Mat.Size.Height.ToString()}{Environment.NewLine}";
    }
    clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = $"{clsItem.FrmTempMaterial.txt_materialexplanatiom.Text}{AppLanguage.CadCamDynamic[42]} : {Mat.Size.Depth.ToString()}{Environment.NewLine}";
  }

  public void MaterialUpdate(bool FillMaterial, int SelectedIndex)
  {
    try
    {
      if (clsItem.FrmTempMaterial == null)
        return;
      this.MaterialUpdating = true;
      if (FillMaterial)
      {
        clsItem.FrmTempMaterial.tree_mats.Nodes.Clear();
        for (int index = 0; index <= ccVars.MaterialList.Count - 1; ++index)
        {
          TreeNodeSettings treeNodeSettings = new TreeNodeSettings(ccVars.MaterialList[index].Name);
          treeNodeSettings.Tag = (object) index.ToString();
          treeNodeSettings.ClassIndex = index;
          treeNodeSettings.ClassSubIndex = -1;
          treeNodeSettings.ClassSubSubIndex = -1;
          treeNodeSettings.Command = "matitem";
          treeNodeSettings.Checked = true;
          TreeNodeSettings node = treeNodeSettings;
          if (ccVars.MaterialList[index].Shapes == MaterialShapes.Rectangle)
          {
            if (!ccVars.MaterialList[index].Enable)
            {
              node.ImageIndex = 0;
              node.SelectedImageIndex = 0;
            }
            else
            {
              node.ImageIndex = 1;
              node.SelectedImageIndex = 1;
            }
          }
          else if (ccVars.MaterialList[index].Shapes == MaterialShapes.Circle)
          {
            if (!ccVars.MaterialList[index].Enable)
            {
              node.ImageIndex = 2;
              node.SelectedImageIndex = 2;
            }
            else
            {
              node.ImageIndex = 3;
              node.SelectedImageIndex = 3;
            }
          }
          else if (ccVars.MaterialList[index].Shapes == MaterialShapes.Ellipse)
          {
            if (!ccVars.MaterialList[index].Enable)
            {
              node.ImageIndex = 4;
              node.SelectedImageIndex = 4;
            }
            else
            {
              node.ImageIndex = 5;
              node.SelectedImageIndex = 5;
            }
          }
          else if (ccVars.MaterialList[index].Shapes == MaterialShapes.Irregular)
          {
            if (!ccVars.MaterialList[index].Enable)
            {
              node.ImageIndex = 6;
              node.SelectedImageIndex = 6;
            }
            else
            {
              node.ImageIndex = 7;
              node.SelectedImageIndex = 7;
            }
          }
          else if (ccVars.MaterialList[index].Shapes == MaterialShapes.FromFile)
          {
            if (!ccVars.MaterialList[index].Enable)
            {
              node.ImageIndex = 8;
              node.SelectedImageIndex = 8;
            }
            else
            {
              node.ImageIndex = 9;
              node.SelectedImageIndex = 9;
            }
          }
          if (node != null)
            clsItem.FrmTempMaterial.tree_mats.Nodes.Add((TreeNode) node);
        }
      }
      else
      {
        for (int index = 0; index <= ccVars.MaterialList.Count - 1; ++index)
        {
          if (index <= clsItem.FrmTempMaterial.tree_mats.Nodes.Count - 1)
          {
            clsItem.FrmTempMaterial.tree_mats.Nodes[index].Text = ccVars.MaterialList[index].Name;
            if (ccVars.MaterialList[index].Shapes == MaterialShapes.Rectangle)
            {
              if (!ccVars.MaterialList[index].Enable)
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 0;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 0;
              }
              else
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 1;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 1;
              }
            }
            else if (ccVars.MaterialList[index].Shapes == MaterialShapes.Circle)
            {
              if (!ccVars.MaterialList[index].Enable)
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 2;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 2;
              }
              else
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 3;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 3;
              }
            }
            else if (ccVars.MaterialList[index].Shapes == MaterialShapes.Ellipse)
            {
              if (!ccVars.MaterialList[index].Enable)
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 4;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 4;
              }
              else
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 5;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 5;
              }
            }
            else if (ccVars.MaterialList[index].Shapes == MaterialShapes.Irregular)
            {
              if (!ccVars.MaterialList[index].Enable)
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 6;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 6;
              }
              else
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 7;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 7;
              }
            }
            else if (ccVars.MaterialList[index].Shapes == MaterialShapes.FromFile)
            {
              if (!ccVars.MaterialList[index].Enable)
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 8;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 8;
              }
              else
              {
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].ImageIndex = 9;
                clsItem.FrmTempMaterial.tree_mats.Nodes[index].SelectedImageIndex = 9;
              }
            }
          }
        }
      }
      clsItem.FrmTempMaterial.tree_mats.ExpandAll();
      for (int index = 0; index <= clsVar.varInterface.MaterialIndex - 1; ++index)
        clsItem.FrmTempMaterial.tree_mats.Nodes[index].ForeColor = Color.Black;
      for (int index = clsVar.varInterface.MaterialIndex + 1; index <= clsItem.FrmTempMaterial.tree_mats.Nodes.Count - 1; ++index)
        clsItem.FrmTempMaterial.tree_mats.Nodes[index].ForeColor = Color.Black;
      if (clsItem.FrmTempMaterial.tree_mats.Nodes.Count > 0 & clsVar.varInterface.MaterialIndex <= clsItem.FrmTempMaterial.tree_mats.Nodes.Count - 1)
        clsItem.FrmTempMaterial.tree_mats.Nodes[clsVar.varInterface.MaterialIndex].ForeColor = Color.Red;
      if (ccVars.Pages.Count > 0)
      {
        for (int index = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; index >= 0; --index)
        {
          if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].GetType() == typeof (buMaterial))
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
          if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].GetType() == typeof (Brep) && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData == null ? 0 : (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData is CustomData ? 1 : 0)) != 0 && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.Material)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
          if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].GetType() == typeof (Text) && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData == null ? 0 : (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData is CustomData ? 1 : 0)) != 0 && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.Material)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
        }
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
        for (int index = 0; index <= ccVars.MaterialList.Count - 1; ++index)
        {
          if (ccVars.MaterialList[index].Enable)
          {
            Entity entSurface = (Entity) null;
            clsInit.cVector5.MaterialToSurface(ccVars.MaterialList[index], ref entSurface);
            entSurface.Translate(ccVars.MaterialList[index].dX, ccVars.MaterialList[index].dY, ccVars.MaterialList[index].dZ);
            entSurface.ColorMethod = colorMethodType.byEntity;
            if (entSurface.BoxMin == (Point3D) null)
              entSurface.Regen(0.01);
            entSurface.EntityData = (object) new CustomData()
            {
              typeDefination = entityTypeDefination.Material
            };
            ccVars.MaterialList[index].BoxMinPoint = new Point3D(entSurface.BoxMin.X, entSurface.BoxMin.Y, entSurface.BoxMin.Z);
            ccVars.MaterialList[index].BoxMaxPoint = new Point3D(entSurface.BoxMax.X, entSurface.BoxMax.Y, entSurface.BoxMax.Z);
            if (entSurface != null)
            {
              entSurface.Selectable = false;
              ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(entSurface);
              double height = Math.Round(entSurface.BoxMax.Y * 0.05, 3);
              Text text = new Text(devDept.Geometry.Plane.XY, (index + 1).ToString(), height);
              double dx = entSurface.BoxMin.X + (entSurface.BoxMax.X - entSurface.BoxMin.X) / 2.0;
              text.Translate(dx, -(height + 10.0));
              text.EntityData = (object) new CustomData()
              {
                typeDefination = entityTypeDefination.Material
              };
              ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add((Entity) text);
            }
          }
        }
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
      }
      this.MaterialUpdating = false;
    }
    catch (Exception ex)
    {
      this.MaterialUpdating = false;
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

