  public void DrawTool(ToolBase5 Tool, bool DrawArbor, bool DrawHolder, ref Design viewportLayout)
  {
    viewportLayout.Entities.Clear();
    List<Mesh> refMeshes = new List<Mesh>();
    viewportLayout.Viewports.Count.ToString();
    if (viewportLayout.Viewports.Count == 0)
      clsInit.cVector5.CreateModelControl(ref viewportLayout, clsVar.UnlockKey, new CreateModelProperties()
      {
        CoordinateSystemIconVisible = false,
        ViewCubeIconVisible = false,
        OrigineCaptionVisible = true,
        ToolBorVisible = false
      });
    viewportLayout.ActiveViewport.CoordinateSystemIcon.Visible = false;
    if (!Tool.Geometry.FromFileEnable)
    {
      if (clsInit.appMW != null)
      {
        if (Tool.Geometry.GeometryType == ToolType.Saw)
          clsInit.appMW.CreateTool(Tool, true, Tool.Geometry.DrawLength, false, false, ref refMeshes);
        else
          clsInit.appMW.CreateTool(Tool, true, Tool.Geometry.DrawLength, DrawArbor & Tool.Geometry.DrawArbor, DrawHolder & Tool.Geometry.DrawHolder, ref refMeshes);
      }
      for (int index = 0; index <= refMeshes.Count - 1; ++index)
      {
        if (refMeshes[index].Vertices.Length != 0)
          viewportLayout.Entities.Add((Entity) refMeshes[index]);
      }
      List<Entity> dimEntities = new List<Entity>();
      clsInit.cVector5.ToolDimensionEntities(Tool, ref dimEntities);
      for (int index = 0; index <= dimEntities.Count - 1; ++index)
        viewportLayout.Entities.Add(dimEntities[index]);
      if (Tool.Geometry.GeometryType == ToolType.Saw)
      {
        viewportLayout.SetView(viewType.Front, true, false);
        viewportLayout.ZoomOut(2);
      }
      else
      {
        viewportLayout.SetView(viewType.Front, true, false);
        viewportLayout.ZoomOut(2);
      }
    }
    else
    {
      FileInfo fileInfo = new FileInfo(Tool.Geometry.FromFileFileName);
      if (fileInfo.Exists)
      {
        ReadSTL readStl = new ReadSTL(fileInfo.FullName);
        readStl.DoWork();
        readStl.OpenTo((IDesign) viewportLayout);
        if (viewportLayout.Entities.Count > 0)
        {
          for (int index = 0; index <= viewportLayout.Entities.Count - 1; ++index)
          {
            if (viewportLayout.Entities[index] is Mesh)
            {
              viewportLayout.Entities[index].ColorMethod = colorMethodType.byEntity;
              if (viewportLayout.Entities[index].Color == Color.Black)
                viewportLayout.Entities[index].Color = Color.DarkGray;
              viewportLayout.Entities[index].Rotate(buConversion5.DegreeToRadian(Tool.Geometry.FromFileAngle), new Vector3D(0.0, 0.0, 1.0));
            }
          }
          viewportLayout.Entities.Regen();
          viewportLayout.ActiveViewport.ViewCubeIcon.Visible = false;
          viewportLayout.ActiveViewport.Camera.ProjectionMode = projectionType.Orthographic;
          viewportLayout.SetView(viewType.Top, true, false);
          viewportLayout.ZoomOut(2);
        }
      }
    }
    viewportLayout.Invalidate();
  }

  public void DrawTool(ToolBase5 Tool, bool DrawArbor, bool DrawHolder, ref List<Mesh> ToolMeshes)
  {
    ToolMeshes = new List<Mesh>();
    if (Tool.Geometry.FromFileEnable)
      return;
    if (Tool.Geometry.GeometryType == ToolType.Saw)
      clsInit.appMW.CreateTool(Tool, true, Tool.Geometry.DrawLength, false, false, ref ToolMeshes);
    else
      clsInit.appMW.CreateTool(Tool, true, Tool.Geometry.DrawLength, DrawArbor & Tool.Geometry.DrawArbor, DrawHolder & Tool.Geometry.DrawHolder, ref ToolMeshes);
  }

  public void ToolUpdate(bool FillTool, int SelectedGroupIndex, int SelectedIndex)
  {
    try
    {
      this.ToolUpdating = true;
      if (clsItem.FrmTempTools != null)
      {
        if (FillTool)
        {
          clsItem.FrmTempTools.tree_tools.Nodes.Clear();
          for (int index1 = 0; index1 <= ccVars.Tools.Count - 1; ++index1)
          {
            TreeNodeSettings treeNodeSettings1 = new TreeNodeSettings(ccVars.Tools[index1].GroupName);
            treeNodeSettings1.ImageIndex = 13;
            treeNodeSettings1.SelectedImageIndex = 13;
            treeNodeSettings1.Tag = (object) index1.ToString();
            treeNodeSettings1.ClassIndex = index1;
            treeNodeSettings1.ClassSubIndex = -1;
            treeNodeSettings1.ClassSubSubIndex = -1;
            treeNodeSettings1.Command = "toolgroup";
            treeNodeSettings1.Checked = true;
            TreeNodeSettings node1 = treeNodeSettings1;
            for (int index2 = 0; index2 <= ccVars.Tools[index1].Tools.Count - 1; ++index2)
            {
              TreeNodeSettings treeNodeSettings2 = new TreeNodeSettings(this.ToolToName(ccVars.Tools[index1].Tools[index2]));
              treeNodeSettings2.ImageIndex = Convert.ToInt32((object) ccVars.Tools[index1].Tools[index2].Geometry.GeometryType);
              treeNodeSettings2.SelectedImageIndex = Convert.ToInt32((object) ccVars.Tools[index1].Tools[index2].Geometry.GeometryType);
              treeNodeSettings2.Tag = (object) index2.ToString();
              treeNodeSettings2.ClassIndex = index1;
              treeNodeSettings2.ClassSubIndex = index2;
              treeNodeSettings2.ClassSubSubIndex = -1;
              treeNodeSettings2.Command = "tool";
              treeNodeSettings2.Checked = true;
              TreeNodeSettings node2 = treeNodeSettings2;
              node1.Nodes.Add((TreeNode) node2);
            }
            if (node1 != null)
              clsItem.FrmTempTools.tree_tools.Nodes.Add((TreeNode) node1);
          }
        }
        else
        {
          for (int index3 = 0; index3 <= ccVars.Tools.Count - 1; ++index3)
          {
            clsItem.FrmTempTools.tree_tools.Nodes[index3].Text = ccVars.Tools[index3].GroupName;
            for (int index4 = 0; index4 <= ccVars.Tools[index3].Tools.Count - 1; ++index4)
            {
              if (index4 <= clsItem.FrmTempTools.tree_tools.Nodes[index3].Nodes.Count - 1)
                clsItem.FrmTempTools.tree_tools.Nodes[index3].Nodes[index4].Text = this.ToolToName(ccVars.Tools[index3].Tools[index4]);
            }
          }
        }
        clsItem.FrmTempTools.tree_tools.ExpandAll();
        for (int index5 = 0; index5 <= ccVars.ToolGroupIndex - 1; ++index5)
        {
          clsItem.FrmTempTools.tree_tools.Nodes[index5].ForeColor = Color.Black;
          for (int index6 = 0; index6 <= clsItem.FrmTempTools.tree_tools.Nodes[index5].Nodes.Count - 1; ++index6)
            clsItem.FrmTempTools.tree_tools.Nodes[index5].Nodes[index6].ForeColor = Color.Black;
        }
