  public void ToolUpdate(
    bool FillTool,
    int SelectedGroupIndex,
    int SelectedIndex,
    ref TreeView Tree)
  {
    try
    {
      this.ToolUpdating = true;
      if (FillTool)
      {
        Tree.Nodes.Clear();
        if (ccVars.Tools.Count > 1)
        {
          for (int index1 = 0; index1 <= ccVars.Tools.Count - 1; ++index1)
          {
            TreeNodeSettings treeNodeSettings1 = new TreeNodeSettings(ccVars.Tools[index1].GroupName);
            treeNodeSettings1.ImageIndex = 13;
            treeNodeSettings1.SelectedImageIndex = 13;
            treeNodeSettings1.Tag = (object) index1.ToString();
            treeNodeSettings1.ClassIndex = index1;
            treeNodeSettings1.ClassSubIndex = -1;
            treeNodeSettings1.ClassSubSubIndex = -1;
            treeNodeSettings1.Command = "toolgroup";
            treeNodeSettings1.Checked = true;
            TreeNodeSettings node1 = treeNodeSettings1;
            for (int index2 = 0; index2 <= ccVars.Tools[index1].Tools.Count - 1; ++index2)
            {
              TreeNodeSettings treeNodeSettings2 = new TreeNodeSettings(this.ToolToName(ccVars.Tools[index1].Tools[index2]));
              treeNodeSettings2.ImageIndex = Convert.ToInt32((object) ccVars.Tools[index1].Tools[index2].Geometry.GeometryType);
              treeNodeSettings2.SelectedImageIndex = Convert.ToInt32((object) ccVars.Tools[index1].Tools[index2].Geometry.GeometryType);
              treeNodeSettings2.Tag = (object) index2.ToString();
              treeNodeSettings2.ClassIndex = index1;
              treeNodeSettings2.ClassSubIndex = index2;
              treeNodeSettings2.ClassSubSubIndex = -1;
              treeNodeSettings2.Command = "tool";
              treeNodeSettings2.Checked = true;
              TreeNodeSettings node2 = treeNodeSettings2;
              node1.Nodes.Add((TreeNode) node2);
            }
            if (node1 != null)
              Tree.Nodes.Add((TreeNode) node1);
          }
        }
        else if (ccVars.Tools.Count == 1)
        {
          for (int index = 0; index <= ccVars.Tools[0].Tools.Count - 1; ++index)
          {
            TreeNodeSettings treeNodeSettings = new TreeNodeSettings(this.ToolToName(ccVars.Tools[0].Tools[index]));
            treeNodeSettings.ImageIndex = Convert.ToInt32((object) ccVars.Tools[0].Tools[index].Geometry.GeometryType);
            treeNodeSettings.SelectedImageIndex = Convert.ToInt32((object) ccVars.Tools[0].Tools[index].Geometry.GeometryType);
            treeNodeSettings.Tag = (object) index.ToString();
            treeNodeSettings.ClassIndex = 0;
            treeNodeSettings.ClassSubIndex = index;
            treeNodeSettings.ClassSubSubIndex = -1;
            treeNodeSettings.Command = "tool";
            treeNodeSettings.Checked = true;
            TreeNodeSettings node = treeNodeSettings;
            Tree.Nodes.Add((TreeNode) node);
          }
        }
      }
      else if (ccVars.Tools.Count > 1)
      {
        for (int index3 = 0; index3 <= ccVars.Tools.Count - 1; ++index3)
        {
          Tree.Nodes[index3].Text = ccVars.Tools[index3].GroupName;
          for (int index4 = 0; index4 <= ccVars.Tools[index3].Tools.Count - 1; ++index4)
            Tree.Nodes[index3].Nodes[index4].Text = this.ToolToName(ccVars.Tools[index3].Tools[index4]);
        }
      }
      else if (ccVars.Tools.Count == 1)
      {
        for (int index = 0; index <= ccVars.Tools[0].Tools.Count - 1; ++index)
          Tree.Nodes[index].Text = this.ToolToName(ccVars.Tools[0].Tools[index]);
      }
      Tree.ExpandAll();
      if (ccVars.Tools.Count > 1)
      {
        for (int index5 = 0; index5 <= ccVars.ToolGroupIndex - 1; ++index5)
        {
          Tree.Nodes[index5].ForeColor = Color.Black;
          for (int index6 = 0; index6 <= Tree.Nodes[index5].Nodes.Count - 1; ++index6)
            Tree.Nodes[index5].Nodes[index6].ForeColor = Color.Black;
        }
        for (int index7 = ccVars.ToolGroupIndex + 1; index7 <= Tree.Nodes.Count - 1; ++index7)
        {
          Tree.Nodes[index7].ForeColor = Color.Black;
          for (int index8 = 0; index8 <= Tree.Nodes[index7].Nodes.Count - 1; ++index8)
            Tree.Nodes[index7].Nodes[index8].ForeColor = Color.Black;
        }
        Tree.Nodes[ccVars.ToolGroupIndex].ForeColor = Color.Black;
        for (int index = 0; index <= Tree.Nodes[ccVars.ToolGroupIndex].Nodes.Count - 1; ++index)
          Tree.Nodes[ccVars.ToolGroupIndex].Nodes[index].ForeColor = index != ccVars.ToolIndex ? Color.Black : Color.Red;
      }
      else if (ccVars.Tools.Count == 1)
      {
        for (int index = 0; index <= Tree.Nodes[0].Nodes.Count - 1; ++index)
          Tree.Nodes[index].ForeColor = index != ccVars.ToolIndex ? Color.Black : Color.Red;
        if (SelectedIndex >= 0 & SelectedIndex <= Tree.Nodes.Count - 1)
        {
          Tree.SelectedNode = Tree.Nodes[SelectedIndex];
          Tree.Focus();
        }
      }
      this.ToolUpdating = false;
      if (clsInit.appMarble == null)
        return;
      clsInit.appMarble.doToolUpdate(SelectedGroupIndex, SelectedIndex);
    }
    catch (Exception ex)
    {
      this.ToolUpdating = false;
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

