  public string ToolToName(ToolBase5 Tool)
  {
    return $"{$"{Tool.Data.Name} - T{Tool.Data.No.ToString()}"} -  D: {Tool.Geometry.Diameter.ToString()} - {Tool.Geometry.GeometryType.ToString()}";
