  public void Tool_AfterSelect(object sender, TreeViewEventArgs e)
  {
    TreeNodeSettings node = (TreeNodeSettings) e.Node;
    if (clsItem.FrmToolList != null && clsItem.FrmToolList.Visible)
    {
      clsItem.FrmToolList.Viewport.Entities.Clear();
      if (node.ClassIndex >= 0 & node.ClassIndex <= ccVars.Tools.Count - 1)
      {
        ccVars.ToolGroupIndex = node.ClassIndex;
        if (node.ClassSubIndex >= 0 & node.ClassSubIndex <= ccVars.Tools[node.ClassIndex].Tools.Count - 1)
        {
          ccVars.ToolIndex = node.ClassSubIndex;
          ccVars.ToolGroupIndex = node.ClassIndex;
          clsItem.FrmToolList.SelectedIndex = node.ClassSubIndex;
          clsVar.varInterface.ToolIndex = ccVars.ToolIndex;
          clsVar.varInterface.ToolGroupIndex = ccVars.ToolGroupIndex;
          ccVars.toolActive = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
          clsItem.FrmToolList.txt_detail.Text = this.ToolInfo(ccVars.toolActive, clsVar.varProgram.ToolPanelSettings);
          this.ToolUpdate(false, ccVars.ToolGroupIndex, ccVars.ToolIndex, ref clsItem.FrmToolList.tree_tools);
          this.DrawTool(ccVars.toolActive, clsVar.varDisplay.ToolPreviewDrawArbor, clsVar.varDisplay.ToolPreviewDrawHolder, ref clsItem.FrmToolList.Viewport);
        }
        else if (node.ClassSubIndex == -1)
        {
          ccVars.ToolIndex = -1;
          clsItem.FrmToolList.SelectedIndex = node.ClassSubIndex;
        }
        clsItem.FrmToolList.Viewport.Invalidate();
        return;
      }
    }
    if (!(node.ClassIndex >= 0 & node.ClassIndex <= ccVars.Tools.Count - 1))
      return;
    ccVars.ToolGroupIndex = node.ClassIndex;
    if (node.ClassSubIndex >= 0 & node.ClassSubIndex <= ccVars.Tools[node.ClassIndex].Tools.Count - 1)
    {
      ccVars.ToolIndex = node.ClassSubIndex;
      ccVars.ToolGroupIndex = node.ClassIndex;
      clsVar.varInterface.ToolIndex = ccVars.ToolIndex;
      clsVar.varInterface.ToolGroupIndex = ccVars.ToolGroupIndex;
      ccVars.toolActive = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
      if (clsItem.FrmTempTools != null)
        clsItem.FrmTempTools.txt_toolexplanatiom.Text = this.ToolInfo(ccVars.toolActive, clsVar.varProgram.ToolPanelSettings);
      this.ToolUpdate(false, ccVars.ToolGroupIndex, ccVars.ToolIndex);
      this.DrawTool(ccVars.toolActive, clsVar.varDisplay.ToolPreviewDrawArbor, clsVar.varDisplay.ToolPreviewDrawHolder, ref clsItem.ModelToolPreview);
      if (clsInit.appMarble == null)
        return;
      clsInit.appMarble.doToolSelected(ccVars.toolActive);
    }
    else
    {
      if (node.ClassSubIndex != -1)
        return;
      ccVars.ToolIndex = -1;
    }
  }

