  public string ToolInfo(ToolBase5 tool, ToolPanelSetting Settings)
  {
    string str = $"T{tool.Data.No.ToString()}";
    if (Settings.ShowToolName)
      str = $"{str} - {AppLanguage.CadCamDynamic[40]} : {tool.Data.Name}{Environment.NewLine}";
    if (Settings.ShowToolType)
      str = $"{str}{AppLanguage.CadCamDynamic[84]} : {tool.Geometry.GeometryType.ToString()}{Environment.NewLine}";
    if (Settings.ShowDiameter)
      str = $"{str}{AppLanguage.CadCamDynamic[57]} : {tool.Geometry.Diameter.ToString()}{Environment.NewLine}";
    if (Settings.ShowLength)
      str = $"{str}{AppLanguage.CadCamDynamic[0]} : {tool.Geometry.Length.ToString()}{Environment.NewLine}";
    if (Settings.ShowPurpose)
      str = $"{str}{AppLanguage.CadCamDynamic[86]} : {tool.Purpose.ToString()}{Environment.NewLine}";
    if (Settings.ShowSpindleSpeed)
      str = $"{str}{AppLanguage.CadCamDynamic[87]} : {tool.CamData.SpindleSpeed.ToString()}{Environment.NewLine}";
    if (Settings.ShowFeed)
      str = $"{str}{AppLanguage.CadCamDynamic[88]} : {tool.CamData.FeedSpeed.ToString()}{Environment.NewLine}";
    if (Settings.ShowSafeDistance)
      str = $"{str}{AppLanguage.CadCamDynamic[89]} : {tool.CamData.SafeDistance.ToString()}{Environment.NewLine}";
    return str;
  }

  public List<ToolBase5> ToolSortByNo(List<ToolBase5> lst, SortDirection Direction)
  {
    List<ToolBase5> toolBase5List = new List<ToolBase5>();
    if (lst.Count > 0)
    {
      toolBase5List.Add(lst[this.NearestToolNo(new ToolBase5()
      {
        Data = {
          No = 0
        }
      }, lst)]);
      lst.Remove(toolBase5List[0]);
      int num = 0;
      for (int index = 0; index < lst.Count + num; ++index)
      {
        toolBase5List.Add(lst[this.NearestToolNo(toolBase5List[toolBase5List.Count - 1], lst)]);
        lst.Remove(toolBase5List[toolBase5List.Count - 1]);
        ++num;
      }
      if (Direction == SortDirection.LowerToBigger)
        toolBase5List.Reverse();
    }
    return toolBase5List;
  }

  public int NearestToolNo(ToolBase5 srcPt, List<ToolBase5> lookIn)
  {
    KeyValuePair<int, int> keyValuePair = new KeyValuePair<int, int>();
    for (int index = 0; index < lookIn.Count; ++index)
    {
      int key = srcPt.Data.No - lookIn[index].Data.No;
      if (index == 0)
        keyValuePair = new KeyValuePair<int, int>(key, index);
      else if (key < keyValuePair.Key)
        keyValuePair = new KeyValuePair<int, int>(key, index);
    }
    return keyValuePair.Value;
  }

  public void cmdToolProperties()
  {
    try
    {
      if (!(ccVars.ToolIndex >= 0 & ccVars.ToolGroupIndex >= 0))
        return;
      ToolBase5 tool = new ToolBase5(ccVars.toolActive);
      clsItem.FrmTool = new F_Tool();
      clsInit.cVector5.CreateModelControl(ref clsItem.FrmTool.viewportLayout, clsVar.UnlockKey, new CreateModelProperties()
      {
        CoordinateSystemIconVisible = false,
        ViewCubeIconVisible = false,
        OrigineCaptionVisible = false,
        ToolBorVisible = false
      });
      clsItem.FrmTool.viewportLayout.Entities.Clear();
      clsItem.FrmTool.Properties.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmTool.Tool = new ToolBase5(tool);
      clsItem.FrmTool.Init();
      clsItem.FrmTool.StartPosition = FormStartPosition.CenterParent;
      int num = (int) clsItem.FrmTool.ShowDialog();
      if (clsItem.FrmTool.Properties.Result != DialogResult.OK)
        return;
      ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex] = new ToolBase5(clsItem.FrmTool.Tool);
      ccVars.toolActive = new ToolBase5(clsItem.FrmTool.Tool);
      this.ToolUpdate(false, ccVars.ToolGroupIndex, ccVars.ToolIndex);
      if (ccVars.Pages.Count > 0)
        this.DrawingPropertiesUpdate();
      if (clsInit.appMarble != null)
        clsInit.appMarble.doToolUpdate(ccVars.ToolGroupIndex, ccVars.ToolIndex);
      clsVar.varInterface.pathTool = AppPath.Tool;
      clsVar.varInterface.pathToolHolder = AppPath.ToolHolder;
      clsFiles.SaveParameter();
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

