  public void GetToolIndexWithToolName(
    ToolBase5 refTool,
    ref int ToolGroupIndex,
    ref int ToolIndex)
  {
    for (int index1 = 0; index1 <= ccVars.Tools.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= ccVars.Tools[index1].Tools.Count - 1; ++index2)
      {
        if (refTool.Data.Name == ccVars.Tools[index1].Tools[index2].Data.Name)
        {
          ToolGroupIndex = index1;
          ToolIndex = index2;
          return;
        }
      }
    }
  }

