        if (buString.MessageBoxQuestion($"{AppLanguage.CadCamMessages[67]}{Environment.NewLine}{Environment.NewLine}[ {ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].SceneName} ]") != DialogResult.Yes)
