        for (int index = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; index >= 0; --index)
        {
          if (clsInit.cVector5.GetSceneName(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]) == sceneName)
