  public void cmdFilePagePreview()
  {
    if (clsItem.FrmPreview == null)
    {
      clsItem.FrmPreview = new F_Preview();
      CreateModelProperties Properties = new CreateModelProperties();
      this.EyeParameterToCreateModelProperties(clsVar.varPreviewViewport, clsVar.varMouse, ref Properties);
      clsInit.cVector5.CreateModelControl(ref clsItem.FrmPreview.viewportLayout, clsVar.UnlockKey, Properties);
      clsItem.FrmPreview.Controls.Add((System.Windows.Forms.Control) clsItem.FrmPreview.viewportLayout);
    }
    clsItem.FrmPreview.viewportLayout.Entities.Clear();
    clsItem.FrmPreview.viewportLayout.Layers = buConversion5.CopyEyeLayerToEyeLayer(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers);
    for (int index = clsItem.FrmPreview.viewportLayout.Blocks.Count - 1; index >= 1; --index)
      clsItem.FrmPreview.viewportLayout.Blocks.RemoveAt(index);
    clsItem.FrmPreview.viewportLayout.Blocks.AddRange((IEnumerable<Block>) clsInit.cVector5.CopyEyeBlockToEyeBlock(clsItem.FrmPreview.viewportLayout.Blocks, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks));
    if (ccVars.SelectedPageItem.Mode == PageModes.Scene)
    {
      string sceneName1 = ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].SceneName;
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        string sceneName2 = clsInit.cVector5.GetSceneName(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]);
        if (sceneName1 == sceneName2)
        {
          Entity entity = (Entity) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Clone();
          clsItem.FrmPreview.viewportLayout.Entities.Add(entity);
        }
        else if (sceneName2.Length == 0)
        {
          Entity entity = (Entity) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Clone();
          clsItem.FrmPreview.viewportLayout.Entities.Add(entity);
        }
      }
    }
    else if (ccVars.SelectedPageItem.Mode == PageModes.BlockItem)
    {
      string blockName = ccVars.SelectedPageItem.BlockName;
      for (int index1 = 0; index1 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Count - 1; ++index1)
      {
        if (blockName == ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[index1].Name)
        {
          for (int index2 = 0; index2 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[index1].Entities.Count - 1; ++index2)
          {
            Entity entity = (Entity) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[index1].Entities[index2].Clone();
            clsItem.FrmPreview.viewportLayout.Entities.Add(entity);
          }
        }
      }
    }
    else if (ccVars.SelectedPageItem.Mode == PageModes.EntityItem)
    {
      int entityIndex = ccVars.SelectedPageItem.EntityIndex;
      if (entityIndex >= 0 & entityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
      {
        Entity entity = (Entity) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[entityIndex].Clone();
        Line line = new Line(new Point3D(), new Point3D(100.0, 100.0, 0.0));
        line.Color = Color.Red;
        line.ColorMethod = colorMethodType.byEntity;
        line.LineWeightMethod = colorMethodType.byEntity;
        line.LineWeight = 2f;
        clsItem.FrmPreview.viewportLayout.Entities.Add((Entity) line);
      }
    }
    clsItem.FrmPreview.Init(viewType.Trimetric, true, true);
    clsItem.FrmPreview.Show();
  }

  public void cmdFileSceneSetPlane()
  {
    try
    {
      F_SetCadCamPlane fSetCadCamPlane = new F_SetCadCamPlane();
      fSetCadCamPlane.Plane = buVector5.PlaneToWorkPlane(ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane);
      fSetCadCamPlane.Init();
      int num = (int) fSetCadCamPlane.ShowDialog();
      if (fSetCadCamPlane.Properties.Result != DialogResult.OK)
        return;
      ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane = buVector5.WorkPlaneToPlane(fSetCadCamPlane.Plane);
      if (fSetCadCamPlane.Plane.PlaneName == planeNames.Free)
        ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane = new devDept.Geometry.Plane(new Vector3D(fSetCadCamPlane.Plane.Normalies.X, fSetCadCamPlane.Plane.Normalies.Y, fSetCadCamPlane.Plane.Normalies.Z));
      ccVars.planeActive = ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane;
      this.PagesUpdate(false, "");
      this.SetViewAccordingToPlane(ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane);
    }
    catch (Exception ex)
    {
      throw;
    }
  }

