  public void PageClose(int Index)
  {
    if (ccVars.Pages.Count > 0)
    {
      ccVars.Pages[Index].Cams.Clear();
      ccVars.Pages[Index].Form.viewportcad.Dispose();
      ccVars.Pages[Index].Form.Dispose();
      ccVars.Pages[Index].Layers.Clear();
      ccVars.Pages[Index].RedoBuffer.Clear();
      ccVars.Pages[Index].UndoBuffer.Clear();
      for (int index = 0; index <= ccVars.Pages[Index].Scene.Count - 1; ++index)
        ccVars.Pages[Index].Scene[index].Dispose();
      ccVars.Pages[Index].Scene.Clear();
      ccVars.Pages[Index].Dispose();
      ccVars.Pages.RemoveAt(Index);
      for (int index = 0; index <= ccVars.Pages.Count - 1; ++index)
      {
        ccVars.Pages[index].Form.Tag = (object) index;
        ccVars.Pages[index].Form.viewportcad.Tag = (object) index;
      }
      if (ccVars.PageIndex >= ccVars.Pages.Count)
      {
        ccVars.PageIndex = ccVars.Pages.Count - 1;
        if (ccVars.PageIndex < 0)
          ccVars.PageIndex = 0;
      }
    }
    if (clsInit.appProfile != null)
      clsInit.appProfile.PageClosed();
    if (clsInit.appDrill != null)
      clsInit.appDrill.PageClosed();
    if (clsInit.appPrinter3D != null)
      clsInit.appPrinter3D.PageClosed();
    if (clsInit.appWood != null)
      clsInit.appWood.PageClosed();
    if (clsInit.appMarble != null)
      clsInit.appMarble.doPageClosed();
    this.PagesUpdate(true, "");
    if (ccVars.Pages.Count == 0)
    {
      if (clsItem.FrmTempCams != null)
        clsItem.FrmTempCams.tree_cam.Nodes.Clear();
      if (clsItem.FrmTempLayers != null)
        clsItem.FrmTempLayers.buLayerList1.LayerList.Clear();
    }
    // ISSUE: reference to a compiler-generated field
    if (this.formUpdate_0 == null)
      return;
    // ISSUE: reference to a compiler-generated field
    this.formUpdate_0(true, false, false);
  }

