  public void Pages_Click(object sender, EventArgs e)
  {
    if (!AppBool.ShiftKeyPressed || clsItem.FrmTempPages.tree_pages.SelectedNode == null)
      return;
    TreeNodeSettings treeNodeSettings = new TreeNodeSettings();
    TreeNodeSettings selectedNode = (TreeNodeSettings) clsItem.FrmTempPages.tree_pages.SelectedNode;
    if (!(selectedNode.ClassIndex == ccVars.PageIndex & selectedNode.ClassSubIndex == ccVars.Pages[ccVars.PageIndex].SceneIndex) || !(ccVars.Pages[ccVars.PageIndex].SceneIndex >= 0 & ccVars.Pages[ccVars.PageIndex].SceneIndex <= ccVars.Pages[ccVars.PageIndex].Scene.Count - 1))
      return;
    if (ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].Visible)
    {
      ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].Visible = false;
      clsItem.FrmTempPages.tree_pages.Nodes[selectedNode.ClassIndex].Nodes[selectedNode.ClassSubIndex].ImageIndex = 6;
      clsItem.FrmTempPages.tree_pages.Nodes[selectedNode.ClassIndex].Nodes[selectedNode.ClassSubIndex].SelectedImageIndex = 6;
      clsInit.appCommand.DrawingPropertiesUpdate();
    }
    else
    {
      ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].Visible = true;
      clsItem.FrmTempPages.tree_pages.Nodes[selectedNode.ClassIndex].Nodes[selectedNode.ClassSubIndex].ImageIndex = 1;
      clsItem.FrmTempPages.tree_pages.Nodes[selectedNode.ClassIndex].Nodes[selectedNode.ClassSubIndex].SelectedImageIndex = 1;
      clsInit.appCommand.DrawingPropertiesUpdate();
    }
  }

  public void PagesControlResize(bool Vertical, bool Horizontal)
  {
    try
    {
      int height = clsItem.tabcontrolLeft.Height;
      int width = clsItem.tabcontrolLeft.Width;
      if (clsVar.varProgram.PageLocation == LeftRightAlignment.Right)
      {
        height = clsItem.tabcontrolRight.Height;
        width = clsItem.tabcontrolRight.Width;
      }
      if (Vertical)
        clsItem.FrmTempPages.pnl_controls.Height = height;
      if (!Horizontal)
        return;
      clsItem.FrmTempPages.pnl_controls.Width = width - 50;
