  public void PageInfo(Pages page, PagePanelSetting Settings)
  {
    if (clsItem.FrmTempPages == null)
      return;
    clsItem.FrmTempPages.txt_pageexplanatiom.Text = "";
    if (Settings.ShowPageName)
      clsItem.FrmTempPages.txt_pageexplanatiom.Text = $"{clsItem.FrmTempPages.txt_pageexplanatiom.Text}{AppLanguage.CadCamDynamic[37]} {AppLanguage.CadCamDynamic[40]} : {page.PageName}{Environment.NewLine}";
    if (Settings.ShowSceneName)
      clsItem.FrmTempPages.txt_pageexplanatiom.Text = $"{clsItem.FrmTempPages.txt_pageexplanatiom.Text}{AppLanguage.CadCamDynamic[38]} {AppLanguage.CadCamDynamic[40]} : {page.SceneName}{Environment.NewLine}";
    if (Settings.ShowEntityCount)
      clsItem.FrmTempPages.txt_pageexplanatiom.Text = $"{clsItem.FrmTempPages.txt_pageexplanatiom.Text}{AppLanguage.CadCamDynamic[90]} : {page.Form.viewportcad.Entities.Count.ToString()}{Environment.NewLine}";
    if (!Settings.ShowPlane)
      return;
    WorkPlane workPlane = buVector5.PlaneToWorkPlane(page.Scene[page.SceneIndex].ScenePlane);
    clsItem.FrmTempPages.txt_pageexplanatiom.Text = $"{clsItem.FrmTempPages.txt_pageexplanatiom.Text}{AppLanguage.CadCamDynamic[43]} : {workPlane.PlaneName.ToString()}{Environment.NewLine}";
  }

  public void SceneGetByName(List<PageScene> Scenes, string SceneName, ref PageScene FoundScene)
  {
    FoundScene = (PageScene) null;
    for (int index = 0; index <= Scenes.Count - 1; ++index)
    {
      if (Scenes[index].SceneName == SceneName)
        FoundScene = new PageScene(Scenes[index]);
    }
  }

  public devDept.Geometry.Plane GetPlaneFromSceneName(string sceneName)
  {
    devDept.Geometry.Plane planeFromSceneName;
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Scene.Count - 1; ++index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Scene[index].SceneName == sceneName)
      {
        planeFromSceneName = ccVars.Pages[ccVars.PageIndex].Scene[index].ScenePlane;
        goto label_6;
      }
    }
    planeFromSceneName = devDept.Geometry.Plane.XY;
label_6:
    return planeFromSceneName;
  }

  public void SetViewAccordingToPlane(devDept.Geometry.Plane plane)
  {
    if (buVector5.isPlaneXY(plane))
      this.cmdViewTop(false, false);
    else if (buVector5.isPlaneYX(plane))
      this.cmdViewBottom(false, false);
    else if (buVector5.isPlaneXZ(plane))
      this.cmdViewFront(false, false);
    else if (buVector5.isPlaneZX(plane))
      this.cmdViewRear(false, false);
    else if (buVector5.isPlaneYZ(plane))
      this.cmdViewRight(false, false);
    else if (buVector5.isPlaneZY(plane))
    {
      this.cmdViewLeft(false, false);
    }
    else
    {
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.SetView(viewType.Top);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.SetView(ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.AxisZ, false);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    }
  }

  public void cmdLayerAdd()
  {
    try
    {
      if (ccVars.Pages.Count <= 0)
        return;
      if (clsVar.appModes_0.TuftingMode.Enable)
      {
        F_LayerTufting fLayerTufting = new F_LayerTufting();
        LayerBase5 layerBase5 = new LayerBase5();
        fLayerTufting.Yarns.AddRange((IEnumerable<TuftingYarn>) TuftingYarn.Copy(clsInit.appTufting.Yarns));
        fLayerTufting.layer = layerBase5;
        fLayerTufting.Init();
        fLayerTufting.StartPosition = FormStartPosition.CenterParent;
        int num = (int) fLayerTufting.ShowDialog();
        if (fLayerTufting.PropertiesForm.Result != DialogResult.OK)
          return;
        bool flag = false;
        for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; ++index)
        {
          if (ccVars.Pages[ccVars.PageIndex].Layers[index].Name.Trim().ToLower() == fLayerTufting.layer.Name.Trim().ToLower())
            flag = true;
        }
        if (!flag)
        {
          ccVars.Pages[ccVars.PageIndex].Layers.Add(new LayerBase5(fLayerTufting.layer));
          devDept.Eyeshot.Layer eyeLayer = (devDept.Eyeshot.Layer) null;
          buConversion5.buLayerToeyeLayer(fLayerTufting.layer, ref eyeLayer);
          if (eyeLayer != null)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Add(eyeLayer);
