  public void cmdLayerRemove()
  {
    try
    {
      if (ccVars.Pages.Count <= 0 || !(ccVars.Pages[ccVars.PageIndex].Layers.Count >= 0 & ccVars.Pages[ccVars.PageIndex].LayerIndex >= 0 & ccVars.Pages[ccVars.PageIndex].LayerIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1))
        return;
      LayerBase5 layerBase5 = new LayerBase5(ccVars.Pages[ccVars.PageIndex].Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex]);
      if (ccVars.Pages[ccVars.PageIndex].Layers.Count == 1)
      {
        buString.MessageBoxInfo($"{AppLanguage.CadCamMessages[2]}{Environment.NewLine}{Environment.NewLine}[ {AppLanguage.CadCamDynamic[24]} =  {layerBase5.Name} ]");
      }
      else
      {
        if (buString.MessageBoxQuestionYesNoCancel($"{AppLanguage.CadCamMessages[0]}{Environment.NewLine}{Environment.NewLine}[ {AppLanguage.CadCamDynamic[24]} =  {layerBase5.Name} ]") != DialogResult.Yes)
          return;
        bool flag = false;
        for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
        {
          if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].LayerName == ccVars.Pages[ccVars.PageIndex].Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex].Name)
          {
            flag = true;
            index = 2147483645;
          }
        }
        if (flag)
        {
          if (buString.MessageBoxQuestionYesNoCancel($"{AppLanguage.CadCamMessages[1]}{Environment.NewLine}{Environment.NewLine}[ {AppLanguage.CadCamDynamic[24]} =  {layerBase5.Name} ]") != DialogResult.Yes)
            return;
          this.LayerDelete(ccVars.Pages[ccVars.PageIndex].LayerIndex, true);
          --ccVars.Pages[ccVars.PageIndex].LayerIndex;
          if (ccVars.Pages[ccVars.PageIndex].LayerIndex < 0)
            ccVars.Pages[ccVars.PageIndex].LayerIndex = 0;
          if (ccVars.Pages[ccVars.PageIndex].LayerIndex > ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)
            ccVars.Pages[ccVars.PageIndex].LayerIndex = ccVars.Pages[ccVars.PageIndex].Layers.Count - 1;
          this.LayersUpdate(ccVars.Pages[ccVars.PageIndex].Layers, true, ccVars.Pages[ccVars.PageIndex].LayerIndex);
        }
        else
        {
          this.LayerDelete(ccVars.Pages[ccVars.PageIndex].LayerIndex, false);
          --ccVars.Pages[ccVars.PageIndex].LayerIndex;
          if (ccVars.Pages[ccVars.PageIndex].LayerIndex < 0)
            ccVars.Pages[ccVars.PageIndex].LayerIndex = 0;
          if (ccVars.Pages[ccVars.PageIndex].LayerIndex > ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)
            ccVars.Pages[ccVars.PageIndex].LayerIndex = ccVars.Pages[ccVars.PageIndex].Layers.Count - 1;
          this.LayersUpdate(ccVars.Pages[ccVars.PageIndex].Layers, true, ccVars.Pages[ccVars.PageIndex].LayerIndex);
        }
      }
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

