        LayerBase5 layerBase5 = new LayerBase5(ccVars.Pages[ccVars.PageIndex].Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex]);
        fLayer.Value = layerBase5;
        fLayer.Init((List<drawingPattern>) null, ccVars.Tools[ccVars.ToolGroupIndex].Tools);
        fLayer.StartPosition = FormStartPosition.CenterParent;
        int num = (int) fLayer.ShowDialog();
        if (fLayer.Result == DialogResult.OK)
        {
          bool flag = false;
          for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; ++index)
          {
            if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Name == layerBase5.Name)
            {
              devDept.Eyeshot.Layer eyeLayer = (devDept.Eyeshot.Layer) null;
              buConversion5.buLayerToeyeLayer(fLayer.Value, ref eyeLayer);
              ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index] = eyeLayer;
              flag = true;
            }
          }
          if (!flag && ccVars.Pages[ccVars.PageIndex].LayerIndex >= 0 & ccVars.Pages[ccVars.PageIndex].LayerIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1)
          {
            devDept.Eyeshot.Layer eyeLayer = (devDept.Eyeshot.Layer) null;
            buConversion5.buLayerToeyeLayer(fLayer.Value, ref eyeLayer);
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex] = eyeLayer;
          }
          ccVars.Pages[ccVars.PageIndex].Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex] = new LayerBase5(fLayer.Value);
          this.LayersUpdate(ccVars.Pages[ccVars.PageIndex].Layers, true, ccVars.Pages[ccVars.PageIndex].LayerIndex);
        }
      }
      this.DrawingPropertiesUpdate();
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

