  public void SelectedEntitiesToLayerByName(string LayerName)
  {
    int index1 = -1;
    for (int index2 = 0; index2 <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; ++index2)
    {
      if (ccVars.Pages[ccVars.PageIndex].Layers[index2].Name.Trim() == LayerName.Trim())
        index1 = index2;
    }
    if (index1 >= 0 & index1 <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)
    {
      for (int index3 = 0; index3 <= ccVars.SelectionOP.Selections.Count - 1; ++index3)
      {
        int index4 = ccVars.SelectionOP.Selections[index3].Index;
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index4].ColorMethod = colorMethodType.byLayer;
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index4].LineWeightMethod = colorMethodType.byLayer;
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index4].LineTypeMethod = colorMethodType.byLayer;
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index4].LayerName = ccVars.Pages[ccVars.PageIndex].Layers[index1].Name;
      }
    }
    this.Reset(ReDraw: true);
