  public void EntitiesToLayer()
  {
    if (ccVars.Pages.Count <= 0)
      return;
    this.Reset(false);
    if (ccVars.SelectionOP.Selections.Count <= 0)
      return;
    DialogBoxList dialogBoxList = new DialogBoxList();
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; ++index)
    {
      LayerBase5 layerBase5 = new LayerBase5(ccVars.Pages[ccVars.PageIndex].Layers[index]);
      dialogBoxList.Items.Add($"[{(index + 1).ToString()}] {layerBase5.Name} - {layerBase5.LayerColor.ToString()}");
    }
    dialogBoxList.Init();
    int num = (int) dialogBoxList.ShowDialog();
    if (dialogBoxList.Result != DialogResult.OK)
      return;
    for (int index1 = 0; index1 <= ccVars.SelectionOP.Selections.Count - 1; ++index1)
    {
      int index2 = ccVars.SelectionOP.Selections[index1].Index;
      if (dialogBoxList.SelectedIndex >= 0 & dialogBoxList.SelectedIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)
      {
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2].ColorMethod = colorMethodType.byLayer;
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2].LineWeightMethod = colorMethodType.byLayer;
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2].LineTypeMethod = colorMethodType.byLayer;
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2].LayerName = ccVars.Pages[ccVars.PageIndex].Layers[dialogBoxList.SelectedIndex].Name;
      }
    }
    this.Reset(ReDraw: true);
  }

