  public void LayerCreate(LayerBase5 Layer)
  {
    if (clsVar.appModes_0.CompositeMode.Enable)
      Layer.Router3AX = new LayerRouter3XProps();
    ccVars.Pages[ccVars.PageIndex].Layers.Add(Layer);
    devDept.Eyeshot.Layer eyeLayer = (devDept.Eyeshot.Layer) null;
    buConversion5.buLayerToeyeLayer(Layer, ref eyeLayer);
    if (eyeLayer == null)
      return;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Add(eyeLayer);
  }

  public void LayerDelete(int LayerIndex, bool DeleteEntities)
  {
    for (int index = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; index >= 0; --index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[index].Name == ccVars.Pages[ccVars.PageIndex].Layers[LayerIndex].Name)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.RemoveAt(index);
    }
    ccVars.Pages[ccVars.PageIndex].Layers.RemoveAt(LayerIndex);
  }

  public void LayerConvertFromEyeLayerToBuLayer(
    LayerKeyedCollection eyeLayers,
    ref List<LayerBase5> buLayers)
  {
    try
    {
      if (eyeLayers.Count != buLayers.Count)
      {
        buLayers.Clear();
        for (int index = 0; index <= eyeLayers.Count - 1; ++index)
        {
          LayerBase5 buLayer = (LayerBase5) null;
          buConversion5.eyeLayerTobuLayer(eyeLayers[index], ref buLayer);
          if (clsVar.appModes_0.CompositeMode.Enable)
            buLayer.Router3AX = new LayerRouter3XProps();
          if (clsVar.appModes_0.TuftingMode.Enable)
            buLayer.Tufting = new LayerTuftingProps();
          buLayers.Add(buLayer);
        }
      }
      else
      {
        for (int index = 0; index <= eyeLayers.Count - 1; ++index)
        {
          if (eyeLayers[index].Name != buLayers[index].Name)
          {
            LayerBase5 buLayer = (LayerBase5) null;
            buConversion5.eyeLayerTobuLayer(eyeLayers[index], ref buLayer);
            if (clsVar.appModes_0.CompositeMode.Enable)
              buLayer.Router3AX = new LayerRouter3XProps();
            if (clsVar.appModes_0.TuftingMode.Enable)
              buLayer.Tufting = new LayerTuftingProps();
            buLayers[index] = buLayer;
          }
        }
      }
      for (int index1 = 0; index1 <= ccVars.LayerOptions.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= buLayers.Count - 1; ++index2)
        {
          if (ccVars.LayerOptions[index1].LayerNewName == buLayers[index2].Name)
            buLayers[index2].NameExtra = ccVars.LayerOptions[index1].LayerExtraName;
        }
      }
    }
    catch (Exception ex)
    {
      this.LayerUpdating = false;
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

