  public void LayersUpdate(List<LayerBase5> Layers, bool FillLayer, int SelectedIndex)
  {
    try
    {
      if (clsItem.FrmTempLayers == null)
        return;
      this.LayerUpdating = true;
      if (Layers.Count != clsItem.FrmTempLayers.buLayerList1.LayerList.Count)
        FillLayer = true;
      if (FillLayer)
      {
        clsItem.FrmTempLayers.buLayerList1.RemoveAll();
        for (int index = 0; index <= Layers.Count - 1; ++index)
        {
          Layers[index].LayerColor.ToString();
          if (Layers[index].LayerColor.IsKnownColor)
            Layers[index].LayerColor.ToKnownColor().ToString();
          string name = Layers[index].Name;
          if (Layers[index].NameExtra.Length > 0)
            name = $"{name} {Layers[index].NameExtra}";
          if (clsVar.varProgram.LayerDefinationShow && Layers[index].Defination.Length > 0)
            name = $"{name} - {Layers[index].Defination}";
          if (clsVar.appModes_0.TuftingMode.Enable && Layers[index].Tufting != null)
            name = $"{name} , {Layers[index].Tufting.StitchMode.ToString()} , P: {Layers[index].Tufting.PileHeight.ToString("f1")} , S: {Layers[index].Tufting.StitchLength.ToString("f1")}";
          if (!clsVar.varProgram.LayerColorNameShow)
            ;
          buControls.Components.LayerData layer = new buControls.Components.LayerData(name, Layers[index].Lock, Layers[index].Enable, Layers[index].LayerColor);
          clsItem.FrmTempLayers.buLayerList1.Add(layer, false);
        }
        clsItem.FrmTempLayers.buLayerList1.DrawControls();
      }
      else
      {
        for (int index = 0; index <= Layers.Count - 1; ++index)
        {
          Layers[index].LayerColor.ToString();
          if (Layers[index].LayerColor.IsKnownColor)
            Layers[index].LayerColor.ToKnownColor().ToString();
          string str = Layers[index].Name;
          if (clsVar.varProgram.LayerDefinationShow && Layers[index].Defination.Length > 0)
            str = $"{str} - {Layers[index].Defination}";
          if (clsVar.appModes_0.TuftingMode.Enable && Layers[index].Tufting != null)
            $"{str} , {Layers[index].Tufting.StitchMode.ToString()} , P: {Layers[index].Tufting.PileHeight.ToString("f1")} , S: {Layers[index].Tufting.StitchLength.ToString("f1")}";
          if (!clsVar.varProgram.LayerColorNameShow)
            ;
        }
      }
      int num = 0;
      while (num <= Layers.Count - 1)
        ++num;
      if (SelectedIndex >= 0 & SelectedIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)
        this.LayerInfo(ccVars.Pages[ccVars.PageIndex].Layers[SelectedIndex], clsVar.varProgram.LayerPanelSettings);
      this.DrawingPropertiesUpdate();
      this.LayerUpdating = false;
    }
    catch (Exception ex)
    {
      this.LayerUpdating = false;
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

