  public LayerKeyedCollection LayerConvertFromBuLayerToEyeLayer(List<LayerBase5> buLayers)
  {
    try
    {
      LayerKeyedCollection eyeLayer1 = new LayerKeyedCollection();
      for (int index = 0; index <= buLayers.Count - 1; ++index)
      {
        devDept.Eyeshot.Layer eyeLayer2 = (devDept.Eyeshot.Layer) null;
        buConversion5.buLayerToeyeLayer(buLayers[index], ref eyeLayer2);
        eyeLayer1.Add(eyeLayer2);
      }
      return eyeLayer1;
    }
    catch (Exception ex)
    {
      this.LayerUpdating = false;
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
      return new LayerKeyedCollection();
    }
  }

  public void LayerInfo(LayerBase5 layer, LayerPanelSetting Settings)
  {
    clsItem.FrmTempLayers.txt_layerexplanatiom.Text = "";
    string str = layer.LayerColor.ToString();
    if (layer.LayerColor.IsKnownColor)
      str = layer.LayerColor.ToKnownColor().ToString();
    if (Settings.ShowLayerName)
      clsItem.FrmTempLayers.txt_layerexplanatiom.Text = $"{clsItem.FrmTempLayers.txt_layerexplanatiom.Text}{AppLanguage.CadCamDynamic[40]} : {layer.Name}{Environment.NewLine}";
    if (Settings.ShowLayerColor)
      clsItem.FrmTempLayers.txt_layerexplanatiom.Text = $"{clsItem.FrmTempLayers.txt_layerexplanatiom.Text}{AppLanguage.CadCamDynamic[17]} : {str}{Environment.NewLine}";
    if (!Settings.ShowLayerThickness)
      return;
    clsItem.FrmTempLayers.txt_layerexplanatiom.Text = $"{clsItem.FrmTempLayers.txt_layerexplanatiom.Text}{AppLanguage.CadCamDynamic[42]} : {layer.LayerThickness.ToString()}{Environment.NewLine}";
  }

