  public void cmdLibSaveFile()
  {
    if (clsVar.appModes_0.DemoMode)
    {
      int num = (int) MessageBox.Show("You can't save in Demo Mode");
    }
    else
    {
      if (ccVars.Pages.Count <= 0)
        return;
      SaveFileDialog saveFileDialog = new SaveFileDialog();
      saveFileDialog.InitialDirectory = clsVar.varLibrary.pathLibrary;
      saveFileDialog.Filter = "buCad/Cam Library File (*.bulib5)|*.bulib5";
      saveFileDialog.FilterIndex = 1;
      if (saveFileDialog.ShowDialog() != DialogResult.OK)
        return;
      List<buEntity> copiedEntities = new List<buEntity>();
      buEntity.Copy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList<Entity>(), ref copiedEntities);
      for (int index = 0; index <= copiedEntities.Count - 1; ++index)
      {
        if (copiedEntities[index] is buLinearDim)
        {
          copiedEntities[index].Dimension = new DimensionInfo();
          if (index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
          {
            CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData;
            copiedEntities[index].Dimension.ReSizedEntityIndex = entityData.RefIndex;
            copiedEntities[index].Dimension.ReSizedEntitySubIndex = -1;
            copiedEntities[index].Dimension.SelectedEntities = entityData.Tags;
            DimensionType result;
            Enum.TryParse<DimensionType>(entityData.ActionName, out result);
            copiedEntities[index].Dimension.Type = result;
            copiedEntities[index].Dimension.Chars = entityData.infoData;
            copiedEntities[index].Dimension.Distance = entityData.infoLength;
            copiedEntities[index].Dimension.Explanation = entityData.infoString;
            if (result == DimensionType.Length)
            {
              if (buCompare5.EQ(entityData.infoBasePoint, copiedEntities[entityData.RefIndex].EndPoint, 0.1))
              {
                copiedEntities[index].Dimension.BasePoint = buVector5.ToPoint3D(copiedEntities[entityData.RefIndex].EndPoint);
                copiedEntities[index].Dimension.CatchPoint = buVector5.ToPoint3D(copiedEntities[entityData.RefIndex].StartPoint);
              }
              else
              {
                copiedEntities[index].Dimension.BasePoint = buVector5.ToPoint3D(copiedEntities[entityData.RefIndex].StartPoint);
                copiedEntities[index].Dimension.CatchPoint = buVector5.ToPoint3D(copiedEntities[entityData.RefIndex].EndPoint);
              }
            }
          }
        }
      }
      clsInit.appFiles.SaveLibraryFile(saveFileDialog.FileName, copiedEntities, clsVar.varLibrary);
      clsVar.varLibrary.pathLibrary = buFile.GetPath(saveFileDialog.FileName);
      clsFiles.SaveParameter();
    }
  }

