  public void LibraryEntityCalculation(
    ref Entity dimEntity,
    string Char,
    string Explanation,
    double Length,
    DimensionType Type,
    Point3D pntBase)
  {
    ((CustomData) dimEntity.EntityData).infoData = Char;
    ((CustomData) dimEntity.EntityData).infoString = Explanation;
    ((CustomData) dimEntity.EntityData).infoLength = Length;
    ((CustomData) dimEntity.EntityData).ActionName = Type.ToString();
    ((CustomData) dimEntity.EntityData).infoBasePoint = buVector5.ToPoint3D(pntBase);
    if (!(ccVars.libSelectedEntityIndex >= 0 & ccVars.libSelectedEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1))
      return;
    ((CustomData) dimEntity.EntityData).RefIndex = ccVars.libSelectedEntityIndex;
    Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.libSelectedEntityIndex];
    if (!(entity is ICurve))
      return;
    List<Entity> entityList = new List<Entity>();
    List<Entity> SortedEntities = new List<Entity>();
    SortSettings Settings = new SortSettings();
    SortResult Result = new SortResult();
    Settings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
    buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref entityList);
    clsInit.cVector5.SortEntitiesByRefPoint(((ICurve) entity).StartPoint, ref entityList, Settings, ref SortedEntities, ref Result);
    if (SortedEntities.Count <= 0)
      return;
    int num = 0;
    for (int index = 0; index <= SortedEntities.Count - 1; ++index)
    {
      CustomData entityData1 = SortedEntities[index].EntityData as CustomData;
      if (entityData1.OriginalEntityIndex >= 0)
      {
        int originalEntityIndex;
        if (num == 0)
        {
          CustomData entityData2 = (CustomData) dimEntity.EntityData;
          string tags = ((CustomData) dimEntity.EntityData).Tags;
          originalEntityIndex = entityData1.OriginalEntityIndex;
          string str1 = originalEntityIndex.ToString();
          string str2 = tags + str1;
          entityData2.Tags = str2;
        }
        else
        {
          CustomData entityData3 = (CustomData) dimEntity.EntityData;
          string tags = ((CustomData) dimEntity.EntityData).Tags;
          originalEntityIndex = entityData1.OriginalEntityIndex;
          string str3 = originalEntityIndex.ToString();
          string str4 = $"{tags} ; {str3}";
          entityData3.Tags = str4;
        }
        ++num;
      }
    }
  }

