  public void KeyDown(KeyEventArgs e)
  {
    if (e.KeyCode == Keys.Return)
      ;
    if (e.KeyCode == Keys.F8)
    {
      if (buVector5.AskMe.FoundEntities.Count > 0)
      {
        if (buVector5.AskMe.SelectedIndex == buVector5.AskMe.FoundEntities.Count - 1)
        {
          buVector5.AskMe.SelectedIndex = 0;
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
          return;
        }
        if (buVector5.AskMe.SelectedIndex < buVector5.AskMe.FoundEntities.Count - 1)
        {
          ++buVector5.AskMe.SelectedIndex;
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
        }
      }
      if (buVector5.AskMeBu.FoundEntities.Count > 0)
      {
        if (buVector5.AskMeBu.SelectedIndex == buVector5.AskMeBu.FoundEntities.Count - 1)
        {
          buVector5.AskMeBu.SelectedIndex = 0;
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
          return;
        }
        if (buVector5.AskMeBu.SelectedIndex < buVector5.AskMeBu.FoundEntities.Count - 1)
        {
          ++buVector5.AskMeBu.SelectedIndex;
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
        }
      }
    }
    if (e.KeyCode != Keys.F9 || ccVars.Action != actionTypeBU.quiltingSelectPattern)
      return;
    clsInit.appQuilting.doAskMeReturn();
  }

  public void undoBuffer()
  {
    if (ccVars.Pages.Count <= 0)
      return;
    this.undoBuffer(ccVars.Pages[ccVars.PageIndex]);
  }

  public void undoBuffer(Pages page) => this.undoBuffer(page, false);

  public void undoBuffer(Pages page, bool ClearRedoBuffer)
  {
    if (clsVar.varProgram.UndoBufferCount <= 0 || !clsVar.varProgram.UndoEnable || ccVars.UndoDont)
      return;
    UndoV5 undoV5 = this.UndoNew(page);
    page.UndoBuffer.Add(undoV5);
    if (((page.UndoBuffer.Count > clsVar.varProgram.UndoBufferCount ? 1 : 0) | 0) != 0)
    {
      page.UndoBuffer.RemoveAt(0);
      GC.Collect();
    }
    if (!ClearRedoBuffer)
      return;
    page.RedoBuffer.Clear();
  }

  public void undoGetBack(Pages page)
  {
    if (!clsVar.varProgram.UndoEnable)
      return;
    if (clsVar.appModes_0.ProfileMode.Enable)
    {
      clsInit.appProfile.UndoGetBack();
    }
    else
    {
      if (ccVars.SimCamBaseIndex > 0 | ccVars.SimCamPointIndex > 0)
        this.simStop();
      if (page.UndoBuffer.Count == 0)
      {
        List<UndoV5> undoV5List = new List<UndoV5>();
        undoV5List.Reverse();
        for (int index = 0; index <= undoV5List.Count - 1; ++index)
        {
          UndoV5 undoV5 = new UndoV5(undoV5List[index]);
          page.UndoBuffer.Add(undoV5);
        }
      }
      if (page.UndoBuffer.Count <= 0)
        return;
      UndoV5 undoV5_1 = this.UndoNew(page);
      page.RedoBuffer.Add(undoV5_1);
      UndoV5 undoV5_2 = new UndoV5(page.UndoBuffer[page.UndoBuffer.Count - 1]);
      page.UndoBuffer.RemoveAt(page.UndoBuffer.Count - 1);
      this.UndoClassToPage(undoV5_2, ref page);
      this.CamsUpdate(true, ccVars.Pages[ccVars.PageIndex].CamIndex);
      if (clsInit.appProfile != null & clsVar.UserMode.ProfileMode.Enable)
        clsInit.appProfile.doUndoRedoGetBack(undoV5_2);
      if (ccVars.MaterialList.Count > 0)
        this.MaterialUpdate(true, -1);
      this.Reset(ReDraw: true);
      clsItem.timSim.Enabled = false;
      this.simStop();
    }
  }

  public void redoGetBack(Pages page)
  {
    if (!clsVar.varProgram.UndoEnable || page.RedoBuffer.Count <= 0)
      return;
    this.undoBuffer(page, false);
    UndoV5 undoV5 = new UndoV5(page.RedoBuffer[page.RedoBuffer.Count - 1]);
    page.RedoBuffer.RemoveAt(page.RedoBuffer.Count - 1);
    this.UndoClassToPage(undoV5, ref page);
    this.CamsUpdate(true, ccVars.Pages[ccVars.PageIndex].CamIndex);
    if (clsInit.appProfile != null & clsVar.UserMode.ProfileMode.Enable)
      clsInit.appProfile.doUndoRedoGetBack(undoV5);
    this.Reset(ReDraw: true);
  }

  public void UndoClassToPage(UndoV5 U, ref Pages page)
  {
    page.Form.viewportcad.Entities.Clear();
    for (int index = 0; index <= U.Entities.Count - 1; ++index)
    {
      Entity entity = buVector5.CopyEntities(U.Entities[index]);
      page.Form.viewportcad.Entities.Add(entity);
    }
    page.Cams.Clear();
    for (int index = 0; index <= U.Cams.Count - 1; ++index)
    {
      camTp copiedCam = new camTp();
      camTp.CopyCam(U.Cams[index], ref copiedCam);
      page.Cams.Add(copiedCam);
    }
    page.OsnapPoints.Clear();
    for (int index = 0; index <= U.Osnaps.Count - 1; ++index)
    {
      OsnapPoint osnapPoint = new OsnapPoint((Point3D) U.Osnaps[index], U.Osnaps[index].Type, U.Osnaps[index].EntName, U.Osnaps[index].LayerName, U.Osnaps[index].OtherEntName);
      page.OsnapPoints.Add(osnapPoint);
    }
  }

  public UndoV5 UndoNew(Pages page)
  {
    return !(clsInit.appProfile != null & clsVar.UserMode.ProfileMode.Enable) ? new UndoV5(page.Form.viewportcad.Entities, page.Cams, page.OsnapPoints, (ProfileBase) null) : new UndoV5(page.Form.viewportcad.Entities, page.Cams, page.OsnapPoints, (ProfileBase) null);
  }

  public void SpinLocation(
    ref NumericUpDown Spn,
    ref Panel Pnl,
    ContentAlignment Align,
    Pnt3D MinPoint,
    Pnt3D MidPoint,
    Pnt3D MaxPoint,
    bool Focus,
    bool SelectAll)
  {
    System.Drawing.Point point = new System.Drawing.Point();
    int height = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Height;
    int num = 4;
    if (Align == ContentAlignment.MiddleCenter)
    {
      point.X = (int) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(MidPoint.X, MidPoint.Y, MidPoint.Z).X;
      point.Y = height - (int) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(MidPoint.X, MidPoint.Y, MidPoint.Z).Y;
    }
    if (Align == ContentAlignment.MiddleRight)
    {
      Pnt3D pnt3D = new Pnt3D();
      if (buVector5.isPlaneXYorYX(ccVars.planeActive))
        pnt3D = new Pnt3D(MaxPoint.X, MidPoint.Y, MidPoint.Z);
      if (buVector5.isPlaneXZorZX(ccVars.planeActive))
        pnt3D = new Pnt3D(MaxPoint.X, MidPoint.Y, MidPoint.Z);
      if (buVector5.isPlaneYZ(ccVars.planeActive))
        pnt3D = new Pnt3D(MaxPoint.X, MaxPoint.Y, MidPoint.Z);
      point.X = (int) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(pnt3D.X, pnt3D.Y, pnt3D.Z).X + num;
      point.Y = height - (int) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(pnt3D.X, pnt3D.Y, pnt3D.Z).Y - Convert.ToInt32((float) Spn.Height / 2f);
    }
    if (Align == ContentAlignment.TopCenter)
    {
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = !buVector5.isPlaneXYorYX(ccVars.planeActive) ? (!buVector5.isPlaneXZorZX(ccVars.planeActive) ? (!buVector5.isPlaneYZ(ccVars.planeActive) ? new Pnt3D(MidPoint.X, MaxPoint.Y, MaxPoint.Z) : new Pnt3D(MidPoint.X, MidPoint.Y, MaxPoint.Z)) : new Pnt3D(MidPoint.X, MaxPoint.Y, MaxPoint.Z)) : new Pnt3D(MidPoint.X, MaxPoint.Y, MaxPoint.Z);
      point.X = (int) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(pnt3D2.X, pnt3D2.Y, pnt3D2.Z).X - Convert.ToInt32((float) Spn.Width / 2f);
      point.Y = height - (int) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(pnt3D2.X, pnt3D2.Y, pnt3D2.Z).Y - Spn.Height - num;
    }
    if (ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Visible)
      ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Location = point;
    Pnl.Location = point;
    if (Focus)
      Spn.Focus();
    if (SelectAll)
      Spn.Select(0, 100);
    Spn.Refresh();
  }

  public void SpinShow(int Index, bool Focus, bool SelectAll)
  {
    if (Index == 1)
    {
      ccVars.Spin1Prop.Visible = true;
      ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = true;
