  public void SpinHide(int Index)
  {
    if (Index == 1)
    {
      ccVars.Spin1Prop.Visible = false;
      ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
    }
    if (Index == 2)
    {
      ccVars.Spin2Prop.Visible = false;
      ccVars.Pages[ccVars.PageIndex].Form.pnl_val2.Visible = false;
    }
    if (Index == 3)
    {
      ccVars.Spin3Prop.Visible = false;
      ccVars.Pages[ccVars.PageIndex].Form.pnl_val3.Visible = false;
    }
    if (Index != 4)
      return;
    ccVars.Spin4Prop.Visible = false;
  }

  public void SpinPropsSet(
    int Index,
    ContentAlignment Alignment,
    bool Visible,
    bool Focus,
    bool SelectAll,
    string Caption)
  {
