    {
      ccVars.Spin1Prop.Alignment = Alignment;
      ccVars.Spin1Prop.Focus = Focus;
      ccVars.Spin1Prop.Caption = Caption;
      ccVars.Spin1Prop.SelectAll = SelectAll;
      ccVars.Spin1Prop.Visible = Visible;
