  public void SpinDrawData_KeyDown(object sender, KeyEventArgs e)
  {
    if (sender.GetType() != typeof (NumericUpDown))
      return;
    NumericUpDown numericUpDown1 = new NumericUpDown();
    NumericUpDown numericUpDown2 = (NumericUpDown) sender;
    Point3D EndPnt = new Point3D();
    if (ccVars.Pages.Count <= 0 || e.KeyCode != Keys.Return)
      return;
    if ((numericUpDown2.Name == "spn_val1" | numericUpDown2.Name == "spn_val2" | numericUpDown2.Name == "spn_val3") & e.Alt)
    {
      ccVars.Spin1Prop.PreVisible = ccVars.Spin1Prop.Visible;
      ccVars.Spin2Prop.PreVisible = ccVars.Spin2Prop.Visible;
      ccVars.Spin3Prop.PreVisible = ccVars.Spin3Prop.Visible;
      this.SpinHide(1);
      this.SpinHide(2);
      this.SpinHide(3);
      ccVars.ShowCoordinates = true;
      ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Left = 10 + (int) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(ccVars.pntActive.X, ccVars.pntActive.Y, ccVars.pntActive.Z).X;
      ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Top = 10 + ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Height - (int) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(ccVars.pntActive.X, ccVars.pntActive.Y, ccVars.pntActive.Z).Y;
      ccVars.Pages[ccVars.PageIndex].Form.spn_x.Value = (Decimal) Math.Round(ccVars.pntActive.X, 3);
      ccVars.Pages[ccVars.PageIndex].Form.spn_y.Value = (Decimal) Math.Round(ccVars.pntActive.Y, 3);
      ccVars.Pages[ccVars.PageIndex].Form.spn_z.Value = (Decimal) Math.Round(ccVars.pntActive.Z, 3);
      ccVars.Pages[ccVars.PageIndex].Form.spn_x.Focus();
      ccVars.Pages[ccVars.PageIndex].Form.spn_x.Select(0, 100);
    }
    else if ((numericUpDown2.Name == "spn_x" | numericUpDown2.Name == "spn_y" | numericUpDown2.Name == "spn_z") & e.Alt)
    {
      ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Visible = false;
      ccVars.ShowCoordinates = false;
      ccVars.Spin1Prop.Visible = ccVars.Spin1Prop.PreVisible;
      ccVars.Spin2Prop.Visible = ccVars.Spin2Prop.PreVisible;
      ccVars.Spin3Prop.Visible = ccVars.Spin3Prop.PreVisible;
    }
    else
    {
      if (numericUpDown2.Name == "spn_val1" & !e.Control & !e.Alt)
      {
        double num = (double) numericUpDown2.Value;
        if (!ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Visible)
        {
          if (ccVars.Action == actionTypeBU.drawLine | ccVars.Action == actionTypeBU.drawCircle | ccVars.Action == actionTypeBU.drawPolyline | ccVars.Action == actionTypeBU.drawPolygon | ccVars.Action == actionTypeBU.drawPolygonIrregular | ccVars.Action == actionTypeBU.drawTriangle | ccVars.Action == actionTypeBU.drawStar | ccVars.Action == actionTypeBU.drawSpline | ccVars.Action == actionTypeBU.drawBezeir)
          {
            clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
            this.viewportMouseDown(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
          }
          if (ccVars.Action == actionTypeBU.drawRectangle3Point | ccVars.Action == actionTypeBU.drawCircle2Point | ccVars.Action == actionTypeBU.drawCircle3Point | ccVars.Action == actionTypeBU.drawArc3PointSEM | ccVars.Action == actionTypeBU.drawArc3PointSME)
          {
            clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
            this.viewportMouseDown(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
          }
          if (ccVars.Action == actionTypeBU.drawEllipse | ccVars.Action == actionTypeBU.drawEllipseArc)
          {
            if (ccVars.stpDrawing == 3)
            {
              clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
              this.viewportMouseDown(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
            }
            if (ccVars.stpDrawing == 2)
            {
              clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
              this.viewportMouseDown(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
              ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
            }
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
          }
          if (ccVars.Action == actionTypeBU.drawArc)
          {
            if (ccVars.stpDrawing == 3 | ccVars.stpDrawing == 4)
            {
              clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, 100.0, num, ccVars.planeActive, ref EndPnt);
              this.viewportMouseDown(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
            }
            if (ccVars.stpDrawing == 2)
            {
              clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
              this.viewportMouseDown(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
            }
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
          }
          if (ccVars.Action == actionTypeBU.drawRectangle | ccVars.Action == actionTypeBU.drawRectangleRound | ccVars.Action == actionTypeBU.drawRectangleChamfer | ccVars.Action == actionTypeBU.drawObjectImage)
            this.SpinShow(2, true, true);
          if (ccVars.Action == actionTypeBU.eventMove | ccVars.Action == actionTypeBU.eventCopy)
          {
            clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
            this.viewportMouseDown(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
          }
          if (ccVars.Action == actionTypeBU.eventRotate)
          {
            this.Rotate(ccVars.pntBase, Utility.DegToRad(num), clsVar.varInterface.RotateVar.DeleteOriginal, clsVar.varProgram.EventCommandRepitation);
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
          }
          if (ccVars.Action == actionTypeBU.eventMoveAbsolute)
          {
            ccVars.Pages[ccVars.PageIndex].Form.spn_val1.ReadOnly = true;
            this.SpinShow(2, true, true);
          }
          if (ccVars.Action == actionTypeBU.eventMoveHorizontal)
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
          if (ccVars.Action == actionTypeBU.eventMoveHorizontalSequence)
          {
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
            return;
          }
          if (ccVars.Action == actionTypeBU.eventMoveVertical)
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
          if (ccVars.Action == actionTypeBU.eventScale)
          {
            if (clsVar.varInterface.ScaleVar.KeepTheRatio)
            {
              this.Scale(new Point3D(), clsVar.varInterface.ScaleVar.CenterType, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value, 0.0, 0.0, 0.0, clsVar.varInterface.ScaleVar.KeepTheRatio, clsVar.varInterface.ScaleVar.DeleteOriginal);
            }
            else
            {
              ccVars.Pages[ccVars.PageIndex].Form.spn_val1.ReadOnly = true;
              this.SpinShow(2, true, true);
            }
          }
        }
        else
        {
          ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Focus();
          ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Refresh();
        }
      }
      if (numericUpDown2.Name == "spn_val1" & e.Control)
      {
        double num = (double) numericUpDown2.Value;
        if (!ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Visible)
        {
          if (ccVars.Action == actionTypeBU.drawLine | ccVars.Action == actionTypeBU.drawPolyline)
          {
            ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Height = 44;
            ccVars.Pages[ccVars.PageIndex].Form.lbl_val1_1.Visible = true;
            ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Visible = true;
            ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Focus();
            ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Refresh();
          }
        }
        else
        {
          ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Height = 22;
          ccVars.Pages[ccVars.PageIndex].Form.lbl_val1_1.Visible = false;
          ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Visible = false;
          ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Focus();
          ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Refresh();
        }
      }
      if (numericUpDown2.Name == "spn_val2")
      {
        double num = (double) numericUpDown2.Value;
        if (ccVars.Action == actionTypeBU.drawLine | ccVars.Action == actionTypeBU.drawPolyline)
        {
          clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_val2.Value, ccVars.planeActive, ref EndPnt);
          this.viewportMouseDown(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
          ccVars.pntActive = EndPnt;
          ccVars.Pages[ccVars.PageIndex].Form.pnl_val2.Visible = false;
          this.SpinShow(1, true, true);
          this.viewportMouseMove(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
        }
        if (ccVars.Action == actionTypeBU.drawRectangle | ccVars.Action == actionTypeBU.drawRectangleRound | ccVars.Action == actionTypeBU.drawRectangleChamfer | ccVars.Action == actionTypeBU.drawObjectImage)
        {
          Point3D pntCalc = new Point3D();
          clsInit.cVector5.RectangleWithDxDy(ccVars.pntBase, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_val2.Value, ccVars.planeActive, ref pntCalc);
          this.viewportMouseDown(pntCalc, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
        }
        if (ccVars.Action == actionTypeBU.eventMoveAbsolute)
          ;
        if (ccVars.Action == actionTypeBU.eventScale)
          this.Scale(new Point3D(), clsVar.varInterface.ScaleVar.CenterType, 0.0, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_val2.Value, 0.0, clsVar.varInterface.ScaleVar.KeepTheRatio, clsVar.varInterface.ScaleVar.DeleteOriginal);
      }
      if (numericUpDown2.Name == "spn_val3")
      {
        double num1 = (double) numericUpDown2.Value;
      }
      if (numericUpDown2.Name == "spn_val1_1")
      {
        double num2 = (double) numericUpDown2.Value;
        if (ccVars.Action == actionTypeBU.drawLine | ccVars.Action == actionTypeBU.drawPolyline)
        {
          clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Value, ccVars.planeActive, ref EndPnt);
          this.viewportMouseDown(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
          ccVars.pntActive = EndPnt;
          ccVars.Pages[ccVars.PageIndex].Form.pnl_val2.Visible = false;
          this.SpinShow(1, true, true);
          this.viewportMouseMove(EndPnt, (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
        }
      }
      if (numericUpDown2.Name == "spn_x")
      {
        ccVars.Pages[ccVars.PageIndex].Form.spn_y.Focus();
        ccVars.Pages[ccVars.PageIndex].Form.spn_y.Select(0, 100);
      }
      if (numericUpDown2.Name == "spn_y")
      {
        if (clsVar.varProgram.Mode2D)
        {
          this.viewportMouseDown(new Point3D((double) ccVars.Pages[ccVars.PageIndex].Form.spn_x.Value, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_y.Value), (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
        }
        else
        {
          ccVars.Pages[ccVars.PageIndex].Form.spn_z.Focus();
          ccVars.Pages[ccVars.PageIndex].Form.spn_z.Select(0, 100);
        }
      }
      if (numericUpDown2.Name == "spn_z")
        this.viewportMouseDown(new Point3D((double) ccVars.Pages[ccVars.PageIndex].Form.spn_x.Value, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_y.Value, (double) ccVars.Pages[ccVars.PageIndex].Form.spn_z.Value), (object) null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    }
  }

