  public void cmdDrawUndo()
  {
    if (ccVars.Action == actionTypeBU.drawPolyline | ccVars.Action == actionTypeBU.profileFreeDraw)
    {
      if (ccVars.pntBuffered.Count <= 1)
        return;
      ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 1);
      ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
      ccVars.pntDrawDynamicArr = new Point3D[ccVars.pntBuffered.Count + 1];
      for (int index = 0; index <= ccVars.pntBuffered.Count - 1; ++index)
        ccVars.pntDrawDynamicArr[index] = buVector5.ToPoint3D(ccVars.pntBuffered[index]);
      ccVars.pntDrawDynamicArr[ccVars.pntBuffered.Count] = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
      if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
        return;
      ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
      if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
        return;
      ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
    }
    else
    {
      switch (ccVars.Action)
      {
        case actionTypeBU.drawPolygonIrregular:
          if (ccVars.pntBuffered.Count <= 2)
            break;
          ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 2);
          ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
          ccVars.pntDrawDynamicArr = new Point3D[ccVars.pntBuffered.Count + 1];
          for (int index = 0; index <= ccVars.pntBuffered.Count - 1; ++index)
            ccVars.pntDrawDynamicArr[index] = buVector5.ToPoint3D(ccVars.pntBuffered[index]);
          ccVars.pntDrawDynamicArr[ccVars.pntBuffered.Count] = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
          if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
            break;
          ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
          if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
            break;
          ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
          break;
        case actionTypeBU.drawSpline:
          if (ccVars.pntBuffered.Count > 2)
          {
            ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 1);
            ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
            if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
              break;
            ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
            if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
              break;
            ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
            break;
          }
          if (ccVars.pntBuffered.Count <= 1)
            break;
          ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 1);
          ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
          ccVars.stpDrawing = 2;
          if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
            break;
          ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
          if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
            break;
          ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
          break;
        case actionTypeBU.drawBezeir:
          if (ccVars.pntBuffered.Count <= 1)
            break;
          ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 1);
          ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
          if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
            break;
          ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
          if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count <= 0)
            break;
          ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
          break;
      }
    }
  }

  public void cmdDrawClose()
  {
    if (ccVars.Action != actionTypeBU.drawPolyline)
      return;
    if (ccVars.pntBuffered.Count > 2)
    {
      if (!Utility.IsClosedProfile((IList<Point3D>) ccVars.pntBuffered))
        ccVars.pntBuffered.Add(buVector5.ToPoint3D(ccVars.pntBuffered[0]));
      LinearPath Ent = (LinearPath) null;
      EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Polyline", (string) null, ccVars.pntBase);
      this.CreatePolyLine(ccVars.pntBuffered, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
      if (Ent != null)
        this.AddPolyline(Ent);
    }
    this.Reset();
  }

  public void cmdDrawFinish()
  {
    if (ccVars.Action == actionTypeBU.marbleDrawCompositeCurve && clsInit.appMarble != null)
      clsInit.appMarble.AddCompositeCurve();
    if (ccVars.Action == actionTypeBU.marbleDrawPolyline && clsInit.appMarble != null)
      clsInit.appMarble.AddPolyLine((Point3D) null);
    switch (ccVars.Action)
    {
      case actionTypeBU.drawPolygonIrregular:
        if (ccVars.pntBuffered.Count >= 2)
        {
          List<Entity> refEntities = new List<Entity>();
          for (int index = 1; index <= ccVars.pntBuffered.Count - 1; ++index)
            refEntities.Add((Entity) new Line(ccVars.pntBuffered[index - 1], ccVars.pntBuffered[index]));
          CompositeCurve Ent = (CompositeCurve) null;
          EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Irregular", (string) null, ccVars.pntBase);
          this.CreateCompositeCurve(refEntities, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
          if (Ent != null)
            this.AddCompositeCurve(Ent);
        }
        this.Reset();
        break;
      case actionTypeBU.drawSpline:
        if (ccVars.pntBuffered.Count >= 3)
        {
          if (clsVar.varInterface.SplineVar.Closed)
            ccVars.pntBuffered.Add(buVector5.ToPoint3D(ccVars.pntBuffered[0]));
          CustomData customData = new CustomData();
          string actionName = "";
          int num = 1;
          if (clsVar.varInterface.SplineVar.Type == entitySplineType.SplineCubic)
          {
            actionName = "SplineCubic";
            num = 3;
          }
          else if (clsVar.varInterface.SplineVar.Type == entitySplineType.BsplineCubic)
          {
            actionName = "BSplineCubic";
            num = 3;
          }
          else if (clsVar.varInterface.SplineVar.Type == entitySplineType.BsplineQuadratic)
          {
            actionName = "BSplineQuadratic";
            num = 2;
          }
          Curve Ent = (Curve) null;
          EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", actionName, (string) null, ccVars.pntBase);
          entityDataSet.Degree = num;
          this.CreateSpline(ccVars.pntBuffered, clsVar.varInterface.SplineVar.Type, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
          if (Ent != null)
            this.AddSpline(Ent);
        }
        this.Reset();
        break;
      case actionTypeBU.drawPolyline:
        if (ccVars.pntBuffered.Count >= 2)
        {
          LinearPath Ent = (LinearPath) null;
          if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
            ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
          EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Polyline", (string) null, ccVars.pntBase);
          this.CreatePolyLine(ccVars.pntBuffered, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
          if (Ent != null)
          {
            if (clsVar.appModes_0.TuftingMode.Enable)
              clsInit.appTufting.doAddManuelEntities((Entity) Ent);
            else
              this.AddPolyline(Ent);
          }
        }
        this.Reset();
        break;
      case actionTypeBU.drawFreeDraw:
        if (!clsVar.varInterface.FreeDrawVar.ConverToSpline)
        {
          for (int index = 0; index <= ccVars.pntDrawDynamicLinesArr.Count - 1; ++index)
          {
            if (ccVars.pntDrawDynamicLinesArr[index].Count >= 2)
            {
              LinearPath Ent = (LinearPath) null;
              EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "FreeDraw", (string) null, ccVars.pntBase);
              this.CreatePolyLine(ccVars.pntDrawDynamicLinesArr[index], entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
              if (Ent != null)
                this.AddPolyline(Ent);
            }
          }
        }
        else
        {
          for (int index = 0; index <= ccVars.pntDrawDynamicLinesArr.Count - 1; ++index)
          {
            if (ccVars.pntDrawDynamicLinesArr[index].Count >= 2)
            {
              CustomData customData = new CustomData();
              string actionName = "";
              int num = 1;
              if (clsVar.varInterface.FreeDrawVar.SplineType == entitySplineType.SplineCubic)
              {
                actionName = "SplineCubic";
                num = 3;
              }
              else if (clsVar.varInterface.FreeDrawVar.SplineType == entitySplineType.BsplineCubic)
              {
                actionName = "BSplineCubic";
                num = 3;
              }
              else if (clsVar.varInterface.FreeDrawVar.SplineType == entitySplineType.BsplineQuadratic)
              {
                actionName = "BSplineQuadratic";
                num = 2;
              }
              Curve Ent = (Curve) null;
              EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", actionName, (string) null, ccVars.pntBase);
              entityDataSet.Degree = num;
              this.CreateSpline(ccVars.pntDrawDynamicLinesArr[index], clsVar.varInterface.FreeDrawVar.SplineType, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
              if (Ent != null)
                this.AddSpline(Ent);
            }
          }
        }
        this.Reset();
        break;
      default:
        this.Reset();
        break;
    }
  }

  public void cmdDrawMeasure()
  {
    try
    {
      this.Reset(false);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActionMode = devDept.Eyeshot.actionType.SelectVisibleByPickDynamic;
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.SelectionFilterMode = buConversion5.buDynamicSelectionModeToEyeDynamicSelection(clsVar.varSelection.DynamicSelection);
      ccVars.Action = actionTypeBU.drawMeasure;
      ccVars.stpDrawing = 1;
      ccVars.selectionProcess = true;
      clsItem.FrmMeasure.tree_item.Nodes.Clear();
      clsItem.FrmMeasure.Properties.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmMeasure.TopMost = true;
      clsItem.FrmMeasure.chk_x.Checked = clsVar.varInterface.DynamicSelectionX;
      clsItem.FrmMeasure.chk_y.Checked = clsVar.varInterface.DynamicSelectionY;
      clsItem.FrmMeasure.chk_z.Checked = clsVar.varInterface.DynamicSelectionZ;
      if (clsVar.varSelection.DynamicSelectionDistanceType == MinMaxType.Min)
      {
        clsItem.FrmMeasure.radio_min.Checked = true;
        clsItem.FrmMeasure.radio_max.Checked = false;
      }
      if (clsVar.varSelection.DynamicSelectionDistanceType == MinMaxType.Max)
      {
        clsItem.FrmMeasure.radio_min.Checked = false;
        clsItem.FrmMeasure.radio_max.Checked = true;
      }
      if (clsVar.varSelection.DynamicSelection == DynamicalSelectionType.Face)
      {
        clsItem.FrmMeasure.btn_edge.BackColor = clsVar.varProgram.ButtonUnselectedColor;
        clsItem.FrmMeasure.btn_face.BackColor = clsVar.varProgram.ButtonSelectedColor;
        clsItem.FrmMeasure.btn_entity.BackColor = clsVar.varProgram.ButtonUnselectedColor;
        clsItem.FrmMeasure.btn_vertex.BackColor = clsVar.varProgram.ButtonUnselectedColor;
        clsItem.FrmMeasure.btn_points.BackColor = clsVar.varProgram.ButtonUnselectedColor;
      }
      if (clsVar.varSelection.DynamicSelection == DynamicalSelectionType.Edge)
      {
        clsItem.FrmMeasure.btn_edge.BackColor = clsVar.varProgram.ButtonSelectedColor;
        clsItem.FrmMeasure.btn_face.BackColor = clsVar.varProgram.ButtonUnselectedColor;
        clsItem.FrmMeasure.btn_entity.BackColor = clsVar.varProgram.ButtonUnselectedColor;
        clsItem.FrmMeasure.btn_vertex.BackColor = clsVar.varProgram.ButtonUnselectedColor;
        clsItem.FrmMeasure.btn_points.BackColor = clsVar.varProgram.ButtonUnselectedColor;
      }
      if (clsVar.varSelection.DynamicSelection == DynamicalSelectionType.Entity)
      {
        clsItem.FrmMeasure.btn_edge.BackColor = clsVar.varProgram.ButtonUnselectedColor;
