  public void cmdImageToVector()
  {
    try
    {
      clsVar.varInterface.FileNameImageProcess = Application.StartupPath + "\\OutputImage.png";
      F_ImageToVector fImageToVector = new F_ImageToVector();
      fImageToVector.pathInit = clsVar.varInterface.pathImageProcess;
      fImageToVector.Settings = new RasterToVectorVar(clsVar.varInterface.RasterVectorVar);
      fImageToVector.Init();
      int num = (int) fImageToVector.ShowDialog();
      if (fImageToVector.PropertiesForm.Result != DialogResult.OK)
        return;
      clsVar.varInterface.RasterVectorVar = new RasterToVectorVar(fImageToVector.Settings);
      clsVar.varInterface.pathImageProcess = fImageToVector.pathInit;
      if (fImageToVector.imageOutput != null)
      {
        clsVar.varInterface.InsertFileVar.InsertToZeroPosition = true;
        fImageToVector.imageOutput.Save(clsVar.varInterface.FileNameImageProcess);
        buFile.SaveToFile(new List<string>()
        {
          "; @echo off",
          "mwRaster2VectorSample.exe" + $" OutputImage.png {clsVar.varInterface.RasterVectorVar.ColorToBWThreshold.ToString()} {clsVar.varInterface.RasterVectorVar.DPI.ToString()} {clsVar.varInterface.RasterVectorVar.SimplifyTolerance.ToString("f2")} {clsVar.varInterface.RasterVectorVar.SplineToleranca.ToString("f2")} Outtt.igs",
          "PAUSE"
        }, Application.StartupPath + "\\Raster.bat");
        Process process = new Process();
        process.StartInfo.WorkingDirectory = Application.StartupPath;
        process.StartInfo.FileName = "Raster.bat";
        process.StartInfo.CreateNoWindow = true;
        process.Start();
        process.WaitForExit();
        clsInit.appFiles.OpenCadFiles(Application.StartupPath + "\\Outtt.igs", true, ref clsItem.ModelOpenInsert);
        fImageToVector.imageOutput = (Image) null;
        fImageToVector.Dispose();
        GC.Collect();
      }
      clsFiles.SaveParameter();
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void CreateEntity(Entity refEntity, ref Entity Ent)
  {
    switch (refEntity)
    {
      case buLinearPathCam _:
        Ent = (Entity) new buLinearPathCam((LinearPath) refEntity);
        break;
      case buLineCam _:
        Ent = (Entity) new buLineCam((Line) refEntity);
        break;
      case buArcCam _:
        Ent = (Entity) new buArcCam((Arc) refEntity);
        break;
      case buCompositeCurveCam _:
        Ent = (Entity) new buCompositeCurveCam((CompositeCurve) refEntity);
        break;
      case devDept.Eyeshot.Entities.Point _:
        this.CreatePoint(refEntity, ref Ent);
        break;
      case Line _:
        this.CreateLine(refEntity, ref Ent);
        break;
      case Arc _:
        this.CreateArc(refEntity, ref Ent);
        break;
      case Circle _:
        this.CreateCircle(refEntity, ref Ent);
        break;
      case LinearPath _:
        this.CreatePolyLine(refEntity, ref Ent);
        break;
      case Ellipse _:
        this.CreateEllipse(refEntity, ref Ent);
        break;
      case EllipticalArc _:
        this.CreateEllipseArc(refEntity, ref Ent);
        break;
      case Curve _:
        this.CreateSpline(refEntity, ref Ent);
        break;
      case CompositeCurve _:
        this.CreateCompositeCurve(refEntity, ref Ent);
        break;
      case Text _:
        this.CreateText(refEntity, ref Ent);
        break;
      case Picture _:
        this.CreatePicture(refEntity, ref Ent);
        break;
      case LinearDim _:
        this.CreateDimensionLinear(refEntity, ref Ent);
        break;
      case AngularDim _:
        this.CreateDimensionAngular(refEntity, ref Ent);
        break;
      case RadialDim _:
        this.CreateDimensionRadial(refEntity, ref Ent);
        break;
      case DiametricDim _:
        this.CreateDimensionDiametric(refEntity, ref Ent);
        break;
      case OrdinateDim _:
        this.CreateDimensionOrdinate(refEntity, ref Ent);
        break;
      case Leader _:
        this.CreateLeader(refEntity, ref Ent);
        break;
      default:
        Ent = (Entity) refEntity.Clone();
        break;
    }
    Ent.Regen(new RegenParams(clsVar.varEntities.RegenDeviation, (IWorkspace) ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
    ++ccVars.Pages[ccVars.PageIndex].EntityCounter;
  }

  public void AddTempEntity(Entity Ent)
  {
    if (Ent is Text)
      Ent.Regen(new RegenParams(clsVar.varEntities.RegenDeviation, (IWorkspace) ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
    if (!(Ent.EntityData is CustomData))
      return;
    ((CustomData) Ent.EntityData).typeDefination = entityTypeDefination.Temp;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Ent);
    ccVars.Pages[ccVars.PageIndex].Changed = true;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void AddEntity(Entity Ent, bool OsnapCalc = true)
  {
    if (Ent == null)
      return;
    this.undoBuffer(ccVars.Pages[ccVars.PageIndex]);
    if (Ent is Text)
      Ent.Regen(new RegenParams(clsVar.varEntities.RegenDeviation, (IWorkspace) ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
    bool flag = false;
    if (Ent is buLineCam | Ent is buLinearPathCam | Ent is buCompositeCurveCam | Ent is buArcCam)
      flag = true;
    if (!flag & OsnapCalc)
      this.OsnapCalculation(Ent);
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Ent);
    ccVars.Pages[ccVars.PageIndex].Changed = true;
    this.eventAddEntityToPage(Ent, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1);
  }

  public void CopyCommonProps(Entity baseEntity, ref Entity commonEntitiy)
  {
    commonEntitiy.ColorMethod = baseEntity.ColorMethod;
    commonEntitiy.LineTypeMethod = baseEntity.LineTypeMethod;
    commonEntitiy.LineWeightMethod = baseEntity.LineWeightMethod;
    commonEntitiy.Color = baseEntity.Color;
    commonEntitiy.Selectable = baseEntity.Selectable;
    commonEntitiy.LineWeight = baseEntity.LineWeight;
    if (baseEntity.LineTypeName != null)
      commonEntitiy.LineTypeName = baseEntity.LineTypeName;
    commonEntitiy.LineTypeScale = baseEntity.LineTypeScale;
  }

