  public void CreateArc3Point(
    Point3D FirstPoint,
    Point3D SecondPoint,
    Point3D ThirdPoint,
    devDept.Geometry.Plane refPlane,
    EntityDataSet entData,
    CustomData customData,
    ref Arc Ent)
  {
    Arc arc = new Arc(FirstPoint, SecondPoint, ThirdPoint, false);
    Ent = new Arc(refPlane, arc.Center, arc.Radius, arc.StartPoint, arc.EndPoint, false);
    if (!buCompare.EQ(arc.AngleInDegrees, Ent.AngleInDegrees, 0.001))
      Ent = new Arc(refPlane, arc.Center, arc.Radius, arc.StartPoint, arc.EndPoint, true);
    Ent.EntityData = (object) new CustomData(customData);
    Ent.LineTypeMethod = colorMethodType.byLayer;
    Ent.ColorMethod = colorMethodType.byLayer;
    Ent.LineWeightMethod = colorMethodType.byLayer;
    Ent.LayerName = entData.LayerName;
    ((CustomData) Ent.EntityData).GroupIdIndex = entData.GroupIDIndex;
    ((CustomData) Ent.EntityData).EntityName = nameof (Ent) + ccVars.Pages[ccVars.PageIndex].EntityCounter.ToString();
    ((CustomData) Ent.EntityData).SceneName = entData.SceneName;
    ((CustomData) Ent.EntityData).ActionName = entData.ActionName;
    ++ccVars.Pages[ccVars.PageIndex].EntityCounter;
  }

