  public void CreateSpline(
    List<Point3D> PointsList,
    entitySplineType Type,
    EntityDataSet entData,
    CustomData customData,
    ref Curve Ent)
  {
    switch (Type)
    {
      case entitySplineType.BsplineQuadratic:
        Ent = new Curve(2, (IList<Point3D>) PointsList);
        break;
      case entitySplineType.BsplineCubic:
        Ent = new Curve(3, (IList<Point3D>) PointsList);
        break;
      case entitySplineType.SplineCubic:
        Ent = Curve.CubicSplineInterpolation<Point3D>((IList<Point3D>) PointsList);
        break;
    }
    Ent.EntityData = (object) new CustomData(customData);
    Ent.LineTypeMethod = colorMethodType.byLayer;
    Ent.ColorMethod = colorMethodType.byLayer;
    Ent.LineWeightMethod = colorMethodType.byLayer;
    Ent.LayerName = entData.LayerName;
    ((CustomData) Ent.EntityData).GroupIdIndex = entData.GroupIDIndex;
    ((CustomData) Ent.EntityData).EntityName = nameof (Ent) + ccVars.Pages[ccVars.PageIndex].EntityCounter.ToString();
    ((CustomData) Ent.EntityData).SceneName = entData.SceneName;
    ((CustomData) Ent.EntityData).ActionName = entData.ActionName;
    ++ccVars.Pages[ccVars.PageIndex].EntityCounter;
  }

  public void CreateSpline(Entity baseEntity, ref Entity Ent)
  {
    if (!(baseEntity is Curve))
      return;
    Curve curve = (Curve) baseEntity;
    if (clsInit.cVector5.GetEntityCustomData(baseEntity).CurveType == entitySplineType.SplineCubic)
      Ent = (Entity) Curve.CubicSplineInterpolation<Point3D>((IList<Point3D>) buVector5.VerticeToPointsList((Point3D[]) curve.ControlPoints));
    else if (clsInit.cVector5.GetEntityCustomData(baseEntity).CurveType == entitySplineType.BsplineQuadratic)
      Ent = (Entity) new Curve(2, (Point3D[]) curve.ControlPoints);
    else if (clsInit.cVector5.GetEntityCustomData(baseEntity).CurveType == entitySplineType.BsplineCubic)
      Ent = (Entity) new Curve(3, (Point3D[]) curve.ControlPoints);
    Ent.EntityData = (object) new CustomData(clsInit.cVector5.GetEntityCustomData(baseEntity));
    Ent.LayerName = baseEntity.LayerName;
    this.CopyCommonProps(baseEntity, ref Ent);
    ((CustomData) Ent.EntityData).EntityName = nameof (Ent) + ccVars.Pages[ccVars.PageIndex].EntityCounter.ToString();
    ++ccVars.Pages[ccVars.PageIndex].EntityCounter;
  }

