  public void CreateFreeDraw(
    List<Point3D> Points,
    EntityDataSet entData,
    CustomData customData,
    ref Entity Ent)
  {
    if (Points.Count < 2)
      return;
    if (clsVar.varInterface.FreeDrawVar.ConverToSpline)
    {
      Curve Ent1 = (Curve) null;
      this.CreateSpline(Points, clsVar.varInterface.FreeDrawVar.SplineType, entData, customData, ref Ent1);
      Ent = (Entity) Ent1;
    }
    else
    {
      LinearPath Ent2 = (LinearPath) null;
      EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Polyline", (string) null, ccVars.pntBase);
      this.CreatePolyLine(ccVars.pntDrawDynamicLines, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent2);
      if (Ent2 == null)
        return;
      Ent = (Entity) Ent2;
    }
  }

