  public void CreateText(
    Point3D StartPoint,
    double Height,
    string TextString,
    bool Simplify,
    ContentAlignment Alignment,
    EntityDataSet entData,
    CustomData customData,
    ref Text Ent,
    ref Design Viewport)
  {
    bool flag = false;
    for (int index = 0; index <= Viewport.TextStyles.Count - 1; ++index)
    {
      if (Viewport.TextStyles[index].FontFamilyName == clsVar.varInterface.TextVar.Font.Name)
        flag = true;
    }
    if (!flag)
    {
      TextStyle textStyle = new TextStyle(clsVar.varInterface.TextVar.Font.Name, clsVar.varInterface.TextVar.Font.Name, (fontStyle) Convert.ToInt32((object) clsVar.varInterface.TextVar.Font.Style));
      Viewport.TextStyles.Add(textStyle);
    }
    Ent = new Text(ccVars.planeActive, StartPoint, TextString, Height, buConversion5.buAligntoEyeAlign(Alignment), clsVar.varInterface.TextVar.Font.Name, Simplify);
    Ent.EntityData = (object) new CustomData(customData);
    Ent.LineTypeMethod = colorMethodType.byLayer;
