  public void CreateAndAddVectorText(
    string Text,
    double Height,
    Point3D Points,
    bool isVectorText)
  {
    string actionName = "VectorText";
    if (!isVectorText)
      actionName = "CustomText";
    int GroupIndex = 0;
    clsInit.cVector5.GetAvailableGroupIndex(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref GroupIndex);
    for (int index1 = 0; index1 <= ccVars.ContourPoints5.Count - 1; ++index1)
    {
      ccVars.UndoDont = true;
      List<Point3D> copiedPoint = new List<Point3D>();
      List<Point3D> point3DList = new List<Point3D>();
      buVector5.Copy(ccVars.ContourPoints5[index1].Outter, ref point3DList);
      clsInit.cVector5.Move(new Point3D(), new Point3D(Points.X, Points.Y, Points.Z), ref point3DList);
      if (ccVars.VectorTextRunVar.DrawAsCurve & isVectorText)
      {
        List<Point3D> calculatedPoints = new List<Point3D>();
        bool Closed = false;
        if (clsInit.cVector5.IsClosed(point3DList))
        {
          point3DList.RemoveAt(point3DList.Count - 1);
          Closed = true;
        }
        clsInit.cVector5.BSplineQuadraticUniform(point3DList, 0.1, Closed, ref calculatedPoints);
        buVector5.Copy(calculatedPoints, ref copiedPoint);
      }
      else
        buVector5.Copy(point3DList, ref copiedPoint);
      LinearPath Ent1 = (LinearPath) null;
      EntityDataSet entData1 = new EntityDataSet(GroupIndex, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", actionName, (string) null, ccVars.pntBase);
      this.CreatePolyLine(copiedPoint, entData1, new CustomData()
      {
        infoString = Text,
        infoHeight = Height,
        infoBasePoint = buVector5.ToPoint3D(Points)
      }, ref Ent1);
      if (Ent1 != null)
        this.AddPolyline(Ent1);
      for (int index2 = 0; index2 <= ccVars.ContourPoints5[index1].Inside.Count - 1; ++index2)
      {
        ccVars.UndoDont = true;
        List<Point3D> refPoint = new List<Point3D>();
        buVector5.Copy(ccVars.ContourPoints5[index1].Inside[index2], ref refPoint);
        clsInit.cVector5.Move(new Point3D(), new Point3D(Points.X, Points.Y, Points.Z), ref refPoint);
        copiedPoint = new List<Point3D>();
        buVector5.Copy(refPoint, ref copiedPoint);
        LinearPath Ent2 = (LinearPath) null;
        EntityDataSet entData2 = new EntityDataSet(GroupIndex, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", actionName, (string) null, ccVars.pntBase);
        this.CreatePolyLine(copiedPoint, entData2, new CustomData()
        {
          infoString = Text,
          infoHeight = Height,
          infoBasePoint = buVector5.ToPoint3D(Points)
        }, ref Ent2);
        if (Ent2 != null)
        {
          if (clsVar.appModes_0.TuftingMode.Enable)
            clsInit.appTufting.doAddOutlineEntities((Entity) Ent2);
          else
            this.AddPolyline(Ent2);
        }
      }
    }
  }

  public void CreateDimensionLinear(
    Point3D StartPoint,
    Point3D EndPoint,
    Point3D LinePoint,
    double TextHeight,
    devDept.Geometry.Plane refPlane,
    bool isAligned,
    EntityDataSet entData,
    CustomData customData,
    ref Entity Ent)
  {
    Ent = (Entity) new LinearDim(refPlane, StartPoint, EndPoint, LinePoint, TextHeight);
    Ent.EntityData = (object) new CustomData(customData);
    Ent.LineTypeMethod = colorMethodType.byLayer;
    Ent.ColorMethod = colorMethodType.byLayer;
    Ent.LineWeightMethod = colorMethodType.byLayer;
    Ent.LayerName = entData.LayerName;
    ((CustomData) Ent.EntityData).GroupIdIndex = entData.GroupIDIndex;
    ((CustomData) Ent.EntityData).EntityName = nameof (Ent) + ccVars.Pages[ccVars.PageIndex].EntityCounter.ToString();
    ((CustomData) Ent.EntityData).SceneName = entData.SceneName;
    ((CustomData) Ent.EntityData).ActionName = entData.ActionName;
    if (!clsVar.varEntities.DimensionDrawingPropertiesFromLayer)
    {
      Ent.ColorMethod = colorMethodType.byEntity;
      Ent.LineTypeMethod = colorMethodType.byEntity;
      Ent.LineWeightMethod = colorMethodType.byEntity;
      Ent.Color = clsVar.varEntities.DimensionDrawing.Color;
      Ent.LineWeight = clsVar.varEntities.DimensionDrawing.Thickness;
    }
    if (isAligned)
      ((CustomData) Ent.EntityData).ActionName = "AlignedDim";
    ++ccVars.Pages[ccVars.PageIndex].EntityCounter;
  }

