  public void surfaceRevolveByPath(ref Entity surfEntity)
  {
    SortSettings Settings = new SortSettings();
    SortResult Result = new SortResult();
    List<Entity> entityList = new List<Entity>();
    List<Entity> SortedEntities = new List<Entity>();
    clsInit.appCommand.SelectionToEntities(ref entityList, new SelectionOption()
    {
      SplitArcIfGreatThen180 = true,
      CircleToArc = true
    });
    Settings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
    if (ccVars.SelectionOP.ClickList.Count > 0)
    {
      Settings.Option.ClickList = buVector5.ToPoint3D(ccVars.SelectionOP.ClickList);
      clsInit.cVector5.SortEntitiesByRefPoint(ccVars.SelectionOP.ClickList[0], ref entityList, Settings, ref SortedEntities, ref Result);
    }
    else
      clsInit.cVector5.SortEntitiesByRefPoint(ccVars.SelectionOP.Selections[0].pntClick, ref entityList, Settings, ref SortedEntities, ref Result);
    List<ICurve> curveList = new List<ICurve>();
    for (int index = 0; index <= SortedEntities.Count - 1; ++index)
    {
      if (SortedEntities[index] is Curve)
      {
        SortedEntities[index].Regen(0.1);
        LinearPath linearPath = new LinearPath(SortedEntities[index].Vertices);
        linearPath.Regen(0.01);
        ICurve curve = (ICurve) linearPath;
        curveList.Add(curve);
      }
      else
      {
        ICurve curve = (ICurve) SortedEntities[index].Clone();
        curveList.Add(curve);
      }
    }
    CompositeCurve refCurve = new CompositeCurve((IEnumerable<ICurve>) curveList);
    refCurve.Regen(0.01);
    clsInit.cVector5.surfaceRevolveByPath(refCurve, Vector3D.AxisX, Point3D.Origin, 0.0, 360.0, ref surfEntity);
  }

