  public void EntitiesToCompositeCurve(
    List<Entity> refEntities,
    double Regen,
    ref CompositeCurve Curve)
  {
    List<ICurve> curveList = new List<ICurve>();
    for (int index = 0; index <= refEntities.Count - 1; ++index)
    {
      if (refEntities[index] is Curve)
      {
        refEntities[index].Regen(Regen);
        LinearPath linearPath = new LinearPath(refEntities[index].Vertices);
        linearPath.Regen(0.01);
        ICurve curve = (ICurve) linearPath;
        curveList.Add(curve);
      }
      else
      {
        ICurve curve = (ICurve) refEntities[index].Clone();
        curveList.Add(curve);
      }
    }
    Curve = new CompositeCurve((IEnumerable<ICurve>) curveList);
    Curve.Regen(Regen);
  }

  public void CompositeCurveToEntities(
    CompositeCurve Curve,
    double Regen,
    ref List<Entity> refEntities)
  {
    try
    {
      if (refEntities != null)
        refEntities.Clear();
      refEntities = new List<Entity>();
      if (Curve == null || Curve.CurveList == null || Curve.CurveList.Count <= 0)
        return;
      for (int index = 0; index <= Curve.CurveList.Count - 1; ++index)
      {
        Entity entity = (Entity) ((Entity) Curve.CurveList[index]).Clone();
        entity.Regen(new RegenParams(Regen));
        entity.EntityData = (object) new CustomData();
        refEntities.Add(entity);
      }
    }
    catch (Exception ex)
    {
    }
  }

  public void SplitEntitiesByClosedPointList(
    bool Selected,
    List<Point3D> Points,
    ref List<Entity> entSplited)
  {
    LinearPath linearPath = new LinearPath((ICollection<Point3D>) Points);
    entSplited.Clear();
    entSplited = new List<Entity>();
    for (int index1 = 0; index1 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index1)
    {
      ICurve entity1 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1] as ICurve;
      if (!(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].EntityData as CustomData).DontUseForCalculation)
      {
        Point3D[] collection = linearPath.IntersectWith(entity1, 0.0, true);
        if (collection != null && collection.Length != 0)
        {
          List<Point3D> points = new List<Point3D>();
          points.AddRange((IEnumerable<Point3D>) collection);
          ICurve[] segments = (ICurve[]) null;
          entity1.SplitBy((IList<Point3D>) points, out segments);
          if (segments != null && segments.Length != 0)
          {
            for (int index2 = 0; index2 <= segments.Length - 1; ++index2)
            {
              Entity entity2 = (Entity) segments[index2];
              entity2.LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].LayerName;
              entity2.EntityData = (object) new CustomData();
              entSplited.Add(entity2);
            }
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].Selected = Selected;
          }
        }
      }
    }
  }

  public void AnalyseEntities()
  {
    try
    {
      AnalyseEntitiesResult Result = new AnalyseEntitiesResult();
      List<Entity> copiedEnt = new List<Entity>();
      buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref copiedEnt);
      clsInit.cVector5.AnalyseEntities(copiedEnt, clsVar.varInterface5.AnalyseEntitySetting, ref Result);
      if (!Result.isError)
        return;
      for (int index = 0; index <= copiedEnt.Count - 1; ++index)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = copiedEnt[index].Selected;
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
      F_AnalyseResult fAnalyseResult = new F_AnalyseResult();
      fAnalyseResult.Result = new AnalyseEntitiesResult(Result);
      fAnalyseResult.Init();
      int num = (int) fAnalyseResult.ShowDialog();
      if (fAnalyseResult.PropertiesForm.Result != DialogResult.OK)
        return;
      for (int index = 0; index <= copiedEnt.Count - 1; ++index)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = false;
      for (int index = 0; index <= fAnalyseResult.Result.ErrorList.Count - 1; ++index)
      {
        int indexEntity = fAnalyseResult.Result.ErrorList[index].IndexEntity;
        if (indexEntity >= 0 & indexEntity <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1 && fAnalyseResult.Result.ErrorList[index].Action == AnalyseEntitiesActionType.Delete & fAnalyseResult.Result.ErrorList[index].Enable)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[indexEntity].Selected = true;
      }
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

