  public void DrawingPropertiesUpdate(Pages Page)
  {
    if (ccVars.Pages.Count == 0)
      return;
    int count = Page.Form.viewportcad.Materials.Count;
    for (int index = 0; index <= Page.Form.viewportcad.Layers.Count - 1; ++index)
    {
      LayerBase5 FoundLayer = (LayerBase5) null;
      clsInit.cVector5.LayerGetByName(Page.Layers, Page.Form.viewportcad.Layers[index].Name, ref FoundLayer);
      if (FoundLayer != null)
      {
        devDept.Eyeshot.Layer layer = Page.Form.viewportcad.Layers[index];
        buConversion5.buLayerToeyeLayer(FoundLayer, ref layer);
        Page.Form.viewportcad.Layers[index] = layer;
      }
    }
    for (int index1 = 0; index1 <= Page.Form.viewportcad.Blocks.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= Page.Form.viewportcad.Blocks[index1].Entities.Count - 1; ++index2)
      {
        if (clsVar.varDisplay.TransperancyOverwrite)
          Page.Form.viewportcad.Blocks[index1].Entities[index2].Color = Color.FromArgb(clsVar.varDisplay.Transperancy, Page.Form.viewportcad.Blocks[index1].Entities[index2].Color);
      }
    }
    for (int index = 0; index <= Page.Form.viewportcad.Entities.Count - 1; ++index)
    {
      PageScene FoundScene = (PageScene) null;
      bool flag = true;
      clsInit.cVector5.SceneGetByName(Page.Scene, clsInit.cVector5.GetEntityName(Page.Form.viewportcad.Entities[index]), ref FoundScene);
      if (Page.Form.viewportcad.Entities[index].ColorMethod == colorMethodType.byEntity && clsVar.varDisplay.TransperancyOverwrite)
        Page.Form.viewportcad.Entities[index].Color = Color.FromArgb(clsVar.varDisplay.Transperancy, Page.Form.viewportcad.Entities[index].Color);
      if (FoundScene != null && !FoundScene.Visible)
        flag = false;
      Page.Form.viewportcad.Entities[index].Visible = flag;
      FoundScene = (PageScene) null;
    }
    Page.Form.viewportcad.Entities.Regen();
    Page.Form.viewportcad.Invalidate();
  }

