  public void VectorTextCreate(
    string text,
    Font font,
    double height,
    ContentAlignment Alignment,
    devDept.Geometry.Plane plane,
    ref List<ContourPoints> contourPoints)
  {
    contourPoints.Clear();
    List<TriangulationPoints> CalculatedPoints = new List<TriangulationPoints>();
    clsInit.cVector.FontToVectorConvert(font, text, buVector5.PlaneToWorkPlane(plane), new Pnt3D(), ref CalculatedPoints);
    List<List<Pnt3D>> pnt3DListList = new List<List<Pnt3D>>();
    for (int index = 0; index <= CalculatedPoints.Count - 1; ++index)
      contourPoints.Add(new ContourPoints(CalculatedPoints[index]));
    List<List<Pnt3D>> Points = new List<List<Pnt3D>>();
    for (int index = 0; index <= CalculatedPoints.Count - 1; ++index)
      Points.Add(CalculatedPoints[index].Points);
    Pnt3D MinPoint1 = new Pnt3D();
    Pnt3D MaxPoint1 = new Pnt3D();
    clsInit.cVector.BoxSizeCalculate(Points, ref MinPoint1, ref MaxPoint1);
    double num1 = MaxPoint1.Y - MinPoint1.Y;
    double num2 = height / num1;
    clsInit.cVector.Scale(new Pnt3D(), num2, num2, 1.0, true, true, false, ref ccVars.ContourPoints);
    Pnt3D MinPoint2 = new Pnt3D();
    Pnt3D MaxPoint2 = new Pnt3D();
    clsInit.cVector.BoxSizeCalculate(ccVars.ContourPoints, ref MinPoint2, ref MaxPoint2);
    Pnt3D CalcPoint = new Pnt3D();
    clsInit.cVector.AlingementContentPointByPlane(MinPoint2, MaxPoint2, Alignment, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint);
    clsInit.cVector.Move(CalcPoint, MinPoint2, ref ccVars.ContourPoints);
    Points.Clear();
  }

  public void CustomTextCreate(
    string Text,
    double CharSpace,
    double SpaceValue,
    double CharHeight,
    ContentAlignment Alignment,
    devDept.Geometry.Plane plane,
    ref List<ContourPoints5> contourPoints)
  {
    contourPoints.Clear();
    List<buEntity> refEntities = new List<buEntity>();
    clsInit.appLibrary.doCreateEntitiesFromCustomText(Text, CharSpace, SpaceValue, CharHeight, ref refEntities);
    Point3D MinPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
    Point3D CalcPoint = new Point3D();
    clsInit.cVector5.AlingementContentPointByPlane(MinPoint, MaxPoint, Alignment, ccVars.planeActive, ref CalcPoint);
    clsInit.cVector5.Move(MinPoint.X - CalcPoint.X, MinPoint.Y - CalcPoint.Y, MinPoint.Z - CalcPoint.Z, ref refEntities);
    for (int index = 0; index <= refEntities.Count - 1; ++index)
    {
      ContourPoints5 contourPoints5 = new ContourPoints5();
      contourPoints5.Outter.AddRange((IEnumerable<Point3D>) refEntities[index].Vertices);
      contourPoints.Add(contourPoints5);
    }
  }

  public void EntityUpdate(int EntityIndex, CustomDataAdd Data)
  {
    double s = 0.0;
    double t1 = 0.0;
    double num1 = 0.0;
    if (!(EntityIndex >= 0 & EntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1))
      return;
    Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntityIndex];
    this.undoBuffer();
    if (entity is Line)
    {
      Line refEntity = (Line) entity;
      Line Ent = (Line) null;
      Vector3D vector3D = new Vector3D(refEntity.EndPoint.X - refEntity.StartPoint.X, refEntity.EndPoint.Y - refEntity.StartPoint.Y, refEntity.EndPoint.Z - refEntity.StartPoint.Z);
      Point3D EndPoint = buVector5.ToPoint3D(refEntity.EndPoint);
      if (Data.Length != 0.0)
      {
        double length = Data.Length;
        vector3D.Length = length;
        EndPoint = new Point3D(refEntity.StartPoint.X + vector3D.X, refEntity.StartPoint.Y + vector3D.Y, refEntity.StartPoint.Z + vector3D.Z);
      }
      this.OsnapDeleteByEntityName(clsInit.cVector5.GetEntityCustomData((Entity) refEntity).EntityName);
      EntityDataSet entData = new EntityDataSet(entity);
      this.CreateLine(refEntity.StartPoint, EndPoint, entData, clsInit.cVector5.GetEntityCustomData(entity), ref Ent);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntityIndex] = (Entity) Ent;
      this.DrawingPropertiesUpdate();
      this.OsnapCalculation((Entity) Ent);
    }
    if (entity is CompositeCurve)
    {
      CompositeCurve compositeCurve = (CompositeCurve) entity;
      if (clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).ActionName.Trim().ToLower() == "rectangle")
      {
        CompositeCurve Ent = (CompositeCurve) null;
        ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.Project(clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).infoBasePoint, out s, out t1);
        if (Data.Width != 0.0 & Data.Height != 0.0)
        {
          ((CustomData) compositeCurve.EntityData).infoWidth = Data.Width;
          ((CustomData) compositeCurve.EntityData).infoHeight = Data.Height;
        }
        this.OsnapDeleteByEntityName(clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).EntityName);
        EntityDataSet entityDataSet = new EntityDataSet((Entity) compositeCurve);
        this.CreateRectangle(s, t1, clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).infoWidth, clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).infoHeight, 0.0, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntityIndex] = (Entity) Ent;
        this.OsnapCalculation((Entity) Ent);
        this.DrawingPropertiesUpdate();
      }
      if (clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).ActionName.Trim().ToLower() == "rectangleround")
      {
        CompositeCurve Ent = (CompositeCurve) null;
        ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.Project(compositeCurve.BoxMin, out s, out t1);
        if (Data.Width != 0.0 & Data.Height != 0.0)
        {
          ((CustomData) compositeCurve.EntityData).infoWidth = Data.Width;
          ((CustomData) compositeCurve.EntityData).infoHeight = Data.Height;
          ((CustomData) compositeCurve.EntityData).infoRadius = Data.Radius;
        }
        List<eEntities> Entities = new List<eEntities>();
        clsInit.cVector.RectangleFillet(new Pnt3D(s, t1), new Pnt3D(s + clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).infoWidth, t1 + clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).infoHeight), clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).infoRadius, new WorkPlane(planeType.XY, 1), ref Entities);
        List<Entity> entityList = new List<Entity>();
        for (int index = 0; index <= Entities.Count - 1; ++index)
        {
          if (Entities[index] is eLine && Entities[index].geoLength > 0.0)
            entityList.Add((Entity) new Line(buConversion5.Pnt3DToPoint3D(((eLine) Entities[index]).StartPoint), buConversion5.Pnt3DToPoint3D(((eLine) Entities[index]).EndPoint)));
          if (Entities[index] is eArc)
            entityList.Add((Entity) new Arc(devDept.Geometry.Plane.XY, buConversion5.Pnt3DToPoint3D(((ePlaneEntities) Entities[index]).CenterPoint), ((eCircle) Entities[index]).Radius, Utility.DegToRad(((eArc) Entities[index]).StartAngle), Utility.DegToRad(((eArc) Entities[index]).EndAngle)));
        }
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane((ICollection<Entity>) entityList, ccVars.planeActive);
        this.OsnapDeleteByEntityName(clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).EntityName);
        EntityDataSet entityDataSet = new EntityDataSet((Entity) compositeCurve);
        this.CreateCompositeCurve(entityList, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntityIndex] = (Entity) Ent;
        this.OsnapCalculation((Entity) Ent);
        this.DrawingPropertiesUpdate();
      }
      if (clsInit.cVector5.GetEntityCustomData((Entity) compositeCurve).ActionName.Trim().ToLower() == "rectanglechamfer")
