  public void cmdEventScaleWithForm()
  {
    try
    {
      if (ccVars.SelectionOP.Selections.Count == 0)
        this.SelectAll();
      F_Scale fScale = new F_Scale();
      fScale.Settings = new ScaleEventFormVars(clsVar.varInterface5.scaleEventFormVar);
      fScale.Init();
      int num = (int) fScale.ShowDialog();
      if (fScale.Properties.Result != DialogResult.OK)
        return;
      clsVar.varInterface5.scaleEventFormVar = new ScaleEventFormVars(fScale.Settings);
      Point3D CalcPoint = new Point3D();
      this.SelectionBoxSizeCalculate();
      clsInit.cVector5.AlingementContentPointByPlane(ccVars.SelectionOP.SelectionBoxMin, ccVars.SelectionOP.SelectionBoxMax, fScale.Settings.Alignment, ccVars.planeActive, ref CalcPoint);
      double sX = 1.0;
      double sY = 1.0;
      double ScaleRatio = 0.0;
      if (ccVars.SelectionOP.SelectionBoxMax.X - ccVars.SelectionOP.SelectionBoxMin.X > 0.0)
        sX = clsVar.varInterface5.scaleEventFormVar.Ratio.X / (ccVars.SelectionOP.SelectionBoxMax.X - ccVars.SelectionOP.SelectionBoxMin.X);
      if (ccVars.SelectionOP.SelectionBoxMax.Y - ccVars.SelectionOP.SelectionBoxMin.Y > 0.0)
        sY = clsVar.varInterface5.scaleEventFormVar.Ratio.Y / (ccVars.SelectionOP.SelectionBoxMax.Y - ccVars.SelectionOP.SelectionBoxMin.Y);
      if (clsVar.varInterface5.scaleEventFormVar.KeepRatio)
        ScaleRatio = sX <= 0.0 ? sY : sX;
      this.Scale(new Point3D(), clsVar.varInterface5.scaleEventFormVar.Alignment, ScaleRatio, sX, sY, 1.0, clsVar.varInterface5.scaleEventFormVar.KeepRatio, true);
      this.Reset();
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

