    Vector3D v = new Vector3D(dX, dY, dZ);
    for (int index = 0; index <= ccVars.tempEntities.Count - 1; ++index)
    {
      ccVars.UndoDont = true;
      Entity Ent = (Entity) null;
      this.CreateEntity(ccVars.tempEntities[index], ref Ent);
      if (Ent != null)
      {
        Ent.Translate(v);
        this.AddEntity(Ent);
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
    this.Reset();
  }

  public void Join()
  {
    this.undoBuffer();
    List<buEntity> buEntityList = new List<buEntity>();
    clsInit.cVector5.SelectedEntitiesToEntityList(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref buEntityList);
    if (buEntityList.Count > 0)
    {
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
      SortbuSettings Settings = new SortbuSettings();
      Settings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
      List<buEntity> SortedEntities = new List<buEntity>();
      clsInit.cVector5.SortEntitiesByRefPoint(buEntityList[0].StartPoint, ref buEntityList, Settings, ref SortedEntities);
      List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
      clsInit.cVector5.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
      for (int index = 0; index <= SplitedEntitites.Count - 1; ++index)
      {
        buCompositeCurve calcCompositeCurve = (buCompositeCurve) null;
        clsInit.cVector5.CreateCompositeCurveFromEntitiesWithCamDirection(SplitedEntitites[index], ref calcCompositeCurve);
        if ((calcCompositeCurve == null ? 0 : (calcCompositeCurve.CurveList.Count > 0 ? 1 : 0)) != 0)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy((buEntity) calcCompositeCurve, ref copiedEntity);
          if (copiedEntity != null)
          {
            this.AddEntity(copiedEntity);
            this.OsnapCalculation(copiedEntity);
          }
        }
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
    this.Reset();
  }

  public void MoveZero(string Cmd)
  {
    List<Entity> refEntities = new List<Entity>();
    for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
    {
      Entity selectedEntity = ccVars.SelectionOP.Selections[index].SelectedEntity;
      refEntities.Add(selectedEntity);
    }
    Point3D MinPoint = new Point3D();
    Point3D MidPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MidPoint, ref MaxPoint);
    if (Cmd == "XY")
      this.Move(new Point3D(MinPoint.X, MinPoint.Y, 0.0), new Point3D());
    if (Cmd == "XYCenter")
      this.Move(new Point3D(MidPoint.X, MidPoint.Y, 0.0), new Point3D());
    if (Cmd == "ZUp")
      this.Move(new Point3D(0.0, 0.0, MaxPoint.Z), new Point3D());
    if (!(Cmd == "ZDown"))
      return;
    this.Move(new Point3D(0.0, 0.0, MinPoint.Z), new Point3D());
  }

  public void Move(Point3D pntStart, Point3D pntEnd)
  {
    this.undoBuffer();
    Vector3D v = new Vector3D(pntStart, pntEnd);
    List<int> Added = new List<int>();
    for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
    {
      Entity selectedEntity = ccVars.SelectionOP.Selections[index].SelectedEntity;
      this.OsnapDeleteByEntityName(clsInit.cVector5.GetEntityName(selectedEntity));
      selectedEntity.Translate(v);
      switch (selectedEntity)
      {
        case CompositeCurve _:
          if (clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint != (Point3D) null)
          {
            clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.X += v.X;
            clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Y += v.Y;
            clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Z += v.Z;
            break;
          }
          break;
        case LinearPath _:
          if (clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint != (Point3D) null)
          {
            clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.X += v.X;
            clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Y += v.Y;
            clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Z += v.Z;
            break;
          }
          break;
        case Text _:
          selectedEntity.Regen(new RegenParams(clsVar.varEntities.RegenDeviation, (IWorkspace) ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
          break;
        case ICurve _:
          selectedEntity.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
          break;
      }
      this.OsnapCalculation(selectedEntity);
      Added.Add(ccVars.SelectionOP.Selections[index].Index);
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
    this.Reset();
    if (!clsVar.varProgram.EventCommandRepitation)
      return;
    this.SelectedToSelectionAdd(Added);
    this.cmdEventMove();
    ccVars.Moved = true;
  }

  public void Copy(Point3D pntStart, Point3D pntEnd)
  {
    this.undoBuffer();
    Vector3D v = new Vector3D(pntStart, pntEnd);
    List<int> Values = new List<int>();
    for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
    {
      if ((ccVars.SelectionOP.Selections[index].SelectedEntity.EntityData == null ? 0 : (ccVars.SelectionOP.Selections[index].SelectedEntity.EntityData is CustomData ? 1 : 0)) != 0 && ((CustomData) ccVars.SelectionOP.Selections[index].SelectedEntity.EntityData).GroupIdIndex >= 0)
        Values.Add(((CustomData) ccVars.SelectionOP.Selections[index].SelectedEntity.EntityData).GroupIdIndex);
    }
    int GroupIndex = -1;
    if (Values.Count > 0)
    {
      Values.Sort();
      buNumeric5.CheckDuplicatedWithPrevious(ref Values);
      if (Values.Count == 1)
        clsInit.cVector5.GetAvailableGroupIndex(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref GroupIndex);
    }
    bool OsnapCalc = true;
    if (ccVars.SelectionOP.Selections.Count > 20)
      OsnapCalc = false;
    for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
    {
      Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index].SelectedEntity);
      ccVars.UndoDont = true;
      Entity Ent = (Entity) null;
      this.CreateEntity(refEntity, ref Ent);
      if (GroupIndex > 0 && (Ent.EntityData == null ? 0 : (Ent.EntityData is CustomData ? 1 : 0)) != 0 && ((CustomData) Ent.EntityData).GroupIdIndex > 0)
        ((CustomData) Ent.EntityData).GroupIdIndex = GroupIndex;
      if (Ent != null)
      {
        Ent.Translate(v);
        this.AddEntity(Ent, OsnapCalc);
      }
    }
    if (!OsnapCalc)
      ThreadCommands.OsnapCalculationAll = true;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void Rotate(
    Point3D pntBase,
    double angleInRadian,
    bool DeleteOriginal,
    bool CommandRepat)
  {
    this.undoBuffer();
    List<int> Added = new List<int>();
    bool OsnapCalc = true;
    if (ccVars.SelectionOP.Selections.Count > 20)
      OsnapCalc = false;
    for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
    {
      Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index].SelectedEntity);
      ccVars.UndoDont = true;
      Entity Ent = (Entity) null;
      this.CreateEntity(refEntity, ref Ent);
      if (Ent != null)
      {
        Ent.Rotate(angleInRadian, ccVars.planeActive.AxisZ, pntBase);
        this.AddEntity(Ent, OsnapCalc);
      }
      Added.Add(ccVars.SelectionOP.Selections[index].Index);
    }
    if (DeleteOriginal)
    {
      this.Delete(true);
      Added.Clear();
    }
    if (!OsnapCalc)
      ThreadCommands.OsnapCalculationAll = true;
    this.Reset();
    if (!CommandRepat)
      return;
    this.SelectedToSelectionAdd(Added);
    this.cmdEventRotate();
  }

  public void RotateVector(Point3D pntBase)
  {
    this.undoBuffer();
    bool OsnapCalc = true;
    if (ccVars.SelectionOP.Selections.Count > 20)
      OsnapCalc = false;
    for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
    {
      Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index].SelectedEntity);
      ccVars.UndoDont = true;
      Entity Ent = (Entity) null;
      this.CreateEntity(refEntity, ref Ent);
      if (Ent != null)
      {
        if (clsVar.varInterface.RotateVectorVar.Axis == VectorType.XVector)
          Ent.Rotate(buConversion5.DegreeToRadian(clsVar.varInterface.RotateVectorVar.Angle), new Vector3D(1.0, 0.0, 0.0), pntBase);
        else if (clsVar.varInterface.RotateVectorVar.Axis == VectorType.YVector)
          Ent.Rotate(buConversion5.DegreeToRadian(clsVar.varInterface.RotateVectorVar.Angle), new Vector3D(0.0, 1.0, 0.0), pntBase);
        else
          Ent.Rotate(buConversion5.DegreeToRadian(clsVar.varInterface.RotateVectorVar.Angle), new Vector3D(0.0, 0.0, 1.0), pntBase);
        this.AddEntity(Ent, OsnapCalc);
      }
    }
    if (clsVar.varInterface.RotateVar.DeleteOriginal)
      this.Delete(true);
    if (!OsnapCalc)
      ThreadCommands.OsnapCalculationAll = true;
    this.Reset();
    if (!clsVar.varProgram.EventCommandRepitation)
      return;
    this.cmdEventRotate();
  }

