  public void Mirror(
    Point3D pntBase,
    Point3D pntTip,
    bool DeleteOriginal,
    bool CommandRepat,
    bool ApplyReset)
  {
    this.undoBuffer();
    Vector3D X = new Vector3D(pntBase, pntTip);
    devDept.Geometry.Plane plane = new devDept.Geometry.Plane(ccVars.pntBase, X, ccVars.planeActive.AxisZ);
    List<int> Added = new List<int>();
    bool OsnapCalc = true;
    if (ccVars.SelectionOP.Selections.Count > 20)
      OsnapCalc = false;
    for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
    {
      Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index].SelectedEntity);
      ccVars.UndoDont = true;
      Entity Ent = (Entity) null;
      this.CreateEntity(refEntity, ref Ent);
      if (Ent != null)
      {
        devDept.Geometry.Mirror xform = new devDept.Geometry.Mirror(plane);
        Ent.TransformBy((Transformation) xform);
        this.AddEntity(Ent, OsnapCalc);
      }
    }
    if (DeleteOriginal)
    {
      this.Delete(ApplyReset);
      Added.Clear();
    }
    if (ApplyReset)
      this.Reset();
    if (!OsnapCalc)
      ThreadCommands.OsnapCalculationAll = true;
    if (!CommandRepat)
      return;
    this.SelectedToSelectionAdd(Added);
    this.cmdEventMirror();
  }

  public void Exchange()
  {
    this.undoBuffer();
    Entity selectedEntity1 = ccVars.SelectionOP.Selections[0].SelectedEntity;
    Entity selectedEntity2 = ccVars.SelectionOP.Selections[1].SelectedEntity;
    Pnt3D CalcPoint1 = new Pnt3D();
    Pnt3D CalcPoint2 = new Pnt3D();
    clsInit.cVector.AlingementContentPointByPlane(buConversion5.Point3DToPnt3D(selectedEntity1.BoxMin), buConversion5.Point3DToPnt3D(selectedEntity1.BoxMax), clsVar.varInterface.ExchangeVar.FirstGroupAlingement, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint1);
    clsInit.cVector.AlingementContentPointByPlane(buConversion5.Point3DToPnt3D(selectedEntity2.BoxMin), buConversion5.Point3DToPnt3D(selectedEntity2.BoxMax), clsVar.varInterface.ExchangeVar.SecondGroupAlingement, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint2);
    Point3D point3D1 = new Point3D(CalcPoint1.X, CalcPoint1.Y, CalcPoint1.Z);
    Point3D point3D2 = new Point3D(CalcPoint2.X, CalcPoint2.Y, CalcPoint2.Z);
    string entityName1 = clsInit.cVector5.GetEntityName(selectedEntity1);
    string entityName2 = clsInit.cVector5.GetEntityName(selectedEntity2);
    this.OsnapDeleteByEntityName(entityName1);
    this.OsnapDeleteByEntityName(entityName2);
    Vector3D v1 = new Vector3D(point3D1, point3D2);
    selectedEntity1.Translate(v1);
    this.OsnapCalculation(selectedEntity1);
    Vector3D v2 = new Vector3D(point3D2, point3D1);
    selectedEntity2.Translate(v2);
    this.OsnapCalculation(selectedEntity2);
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
    this.Reset();
    this.PagesUpdate(true, "");
    if (!clsVar.varProgram.EventCommandRepitation)
      return;
    this.cmdEventExchange();
  }

  public void LinearArray(Point3D pntEnd, bool OkButton)
  {
    this.undoBuffer();
    if (!OkButton)
    {
      Pnt3D CalcPoint = new Pnt3D();
      clsInit.cVector.AlingementContentPointByPlane(buConversion5.Point3DToPnt3D(ccVars.SelectionOP.SelectionBoxMin), buConversion5.Point3DToPnt3D(ccVars.SelectionOP.SelectionBoxMax), clsVar.varInterface.ArrayLineerVar.Alingement, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint);
      Point3D P0 = new Point3D(CalcPoint.X, CalcPoint.Y, CalcPoint.Z);
      for (int index1 = 0; index1 <= clsVar.varInterface.ArrayLineerVar.LevelCountZ - 1; ++index1)
      {
        for (int index2 = 0; index2 <= clsVar.varInterface.ArrayLineerVar.RowsCountY - 1; ++index2)
        {
          for (int index3 = 0; index3 <= clsVar.varInterface.ArrayLineerVar.ColomnsCountX - 1; ++index3)
          {
            if (index1 > 0 | index3 > 0 | index2 > 0)
            {
              for (int index4 = 0; index4 <= ccVars.SelectionOP.Selections.Count - 1; ++index4)
              {
                Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index4].SelectedEntity);
                ccVars.UndoDont = true;
                Entity Ent = (Entity) null;
                this.CreateEntity(refEntity, ref Ent);
                Vector3D v = new Vector3D(P0, pntEnd);
                v.X *= (double) index3;
                v.Y *= (double) index2;
                v.Z *= (double) index1;
                if (Ent != null)
                {
                  Ent.Translate(v);
                  this.AddEntity(Ent);
                }
              }
            }
          }
        }
      }
    }
    else
    {
      for (int index5 = 0; index5 <= clsVar.varInterface.ArrayLineerVar.LevelCountZ - 1; ++index5)
      {
        for (int index6 = 0; index6 <= clsVar.varInterface.ArrayLineerVar.RowsCountY - 1; ++index6)
        {
          for (int index7 = 0; index7 <= clsVar.varInterface.ArrayLineerVar.ColomnsCountX - 1; ++index7)
          {
            if (index5 > 0 | index7 > 0 | index6 > 0)
            {
              for (int index8 = 0; index8 <= ccVars.SelectionOP.Selections.Count - 1; ++index8)
              {
                Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index8].SelectedEntity);
                ccVars.UndoDont = true;
                Entity Ent = (Entity) null;
                this.CreateEntity(refEntity, ref Ent);
                Vector3D v = new Vector3D();
                v.X = clsVar.varInterface.ArrayLineerVar.ColomnsDistanceX * (double) index7;
                v.Y = clsVar.varInterface.ArrayLineerVar.RowDistanceY * (double) index6;
                v.Z = clsVar.varInterface.ArrayLineerVar.LevelDistanceZ * (double) index5;
                if (Ent != null)
                {
                  Ent.Translate(v);
                  this.AddEntity(Ent);
                }
              }
            }
          }
        }
      }
    }
    this.Reset();
  }

  public void PolarArray(Point3D pntCenter)
  {
    this.undoBuffer();
    for (int index1 = 1; index1 <= clsVar.varInterface.ArrayPolarVar.ItemCount - 1; ++index1)
    {
      for (int index2 = 0; index2 <= ccVars.SelectionOP.Selections.Count - 1; ++index2)
      {
        Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index2].SelectedEntity);
        ccVars.UndoDont = true;
        Entity Ent = (Entity) null;
        this.CreateEntity(refEntity, ref Ent);
        double degrees = (double) index1 * clsVar.varInterface.ArrayPolarVar.ItemAngle;
        if (clsVar.varInterface.ArrayPolarVar.Direction == ClockDirectionType.CW)
          degrees *= -1.0;
        if (Ent != null)
        {
          Ent.Rotate(Utility.DegToRad(degrees), ccVars.planeActive.AxisZ, pntCenter);
          this.AddEntity(Ent);
        }
      }
    }
    this.Reset();
  }

  public void Scale(
    Point3D pntEnd,
    ContentAlignment Alignmet,
    double ScaleRatio,
    double sX,
    double sY,
    double sZ,
    bool KeepRatio,
    bool DeleteOriginal)
  {
    this.undoBuffer();
    Pnt3D CalcPoint = new Pnt3D();
    Vec3D Size = new Vec3D();
    clsInit.cVector.AlingementContentPointByPlane(buConversion5.Point3DToPnt3D(ccVars.SelectionOP.SelectionBoxMin), buConversion5.Point3DToPnt3D(ccVars.SelectionOP.SelectionBoxMax), Alignmet, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint, ref Size);
    Point3D fixedPoint = new Point3D(CalcPoint.X, CalcPoint.Y, CalcPoint.Z);
    double num = Math.Sqrt(Size.X * Size.X + Size.Y * Size.Y + Size.Z * Size.Z);
    double sx = 1.0;
    double sy = 1.0;
    double sz = 1.0;
    if (Size.X > 0.0)
      sx = Math.Abs(pntEnd.X - fixedPoint.X) / Size.X;
    if (Size.Y > 0.0)
      sy = Math.Abs(pntEnd.Y - fixedPoint.Y) / Size.Y;
    if (Size.Z > 0.0)
      sz = Math.Abs(pntEnd.Z - fixedPoint.Z) / Size.Z;
    if (sz == 0.0)
      sz = 1.0;
    if (sX > 0.0 & sY > 0.0)
    {
      sx = sX;
      sy = sY;
      sz = 1.0;
    }
    else if (sX > 0.0 & sZ > 0.0)
    {
      sx = sX;
      sy = 1.0;
      sz = sZ;
    }
    else if (sY > 0.0 & sZ > 0.0)
    {
      sx = 1.0;
      sy = sY;
      sz = sZ;
    }
    if (clsVar.varEntities.ScaleMode == ScaleType.Size & !KeepRatio)
    {
      sx = 1.0;
      sy = 1.0;
      sz = 1.0;
      if (buVector5.isPlaneXZorZX(ccVars.planeActive) & sX > 0.0 & sZ > 0.0 & Size.X > 0.0 & Size.Z > 0.0)
      {
        sx = sX / Size.X;
        sz = sZ / Size.Z;
      }
      else if (buVector5.isPlaneYZorZY(ccVars.planeActive) & sY > 0.0 & sZ > 0.0 & Size.Y > 0.0 & Size.Z > 0.0)
      {
        sy = sY / Size.Y;
        sz = sZ / Size.Z;
      }
      else if (sX > 0.0 & sY > 0.0 & Size.X > 0.0 & Size.Y > 0.0)
      {
        sx = sX / Size.X;
        sy = sY / Size.Y;
      }
    }
    double factor = !(buNumeric.IsNumeric(num.ToString()) & num != 0.0) ? fixedPoint.DistanceTo(pntEnd) / fixedPoint.DistanceTo(ccVars.SelectionOP.SelectionBoxMax) : fixedPoint.DistanceTo(pntEnd) / num;
    if (ScaleRatio != 0.0 & ScaleRatio > 0.0)
      factor = ScaleRatio;
    ccVars.pntDrawDynamicLinesArr.Clear();
    if (KeepRatio)
    {
      for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
      {
        Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index].SelectedEntity);
        ccVars.UndoDont = true;
        Entity Ent = (Entity) null;
        this.CreateEntity(refEntity, ref Ent);
        Ent.Scale(fixedPoint, factor);
        this.AddEntity(Ent);
      }
    }
    else
    {
      for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
      {
        Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index].SelectedEntity);
        if (refEntity.GetType() != typeof (Line) & refEntity.GetType() != typeof (LinearPath) & refEntity.GetType() != typeof (Text) & refEntity.GetType() != typeof (MultilineText))
        {
          refEntity.Regen(clsVar.varEntities.RegenDeviation);
          refEntity = (Entity) new LinearPath(refEntity.Vertices);
          refEntity.LayerName = ccVars.SelectionOP.Selections[index].SelectedEntity.LayerName;
        }
        ccVars.UndoDont = true;
        Entity Ent = (Entity) null;
        this.CreateEntity(refEntity, ref Ent);
        Ent.Scale(fixedPoint, sx, sy, sz);
        this.AddEntity(Ent);
      }
    }
    if (DeleteOriginal)
      this.Delete(true);
    this.Reset();
  }

  public void Offset(Point3D pntEnd)
  {
    this.undoBuffer();
    int num1 = 0;
    Vector3D vector3D = (Vector3D) null;
    int count;
    while (true)
    {
      double num2;
      do
      {
        do
        {
          count = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count;
          for (int index1 = 0; index1 <= ccVars.SelectionOP.Selections.Count - 1; ++index1)
          {
            Entity ent = buVector5.CopyEntities(ccVars.SelectionOP.Selections[index1].SelectedEntity);
            ccVars.UndoDont = true;
            if (ent is ICurve)
            {
              List<Point2D> polygon = new List<Point2D>();
              List<Point3D> points = new List<Point3D>();
              points.AddRange((IEnumerable<Point3D>) ent.Vertices);
              if (points.Count >= 3)
              {
                Point3D pntIntersect = new Point3D();
                clsInit.cVector5.LineLineIntersection(points[0], points[1], points[points.Count - 2], points[points.Count - 1], ccVars.planeActive, ref pntIntersect);
                double num3 = Point3D.Distance(pntIntersect, points[0]);
                double num4 = Point3D.Distance(pntIntersect, points[points.Count - 1]);
                if (num3 < clsVar.varInterface.OffsetVar.Offset | num4 < clsVar.varInterface.OffsetVar.Offset)
                {
                  points[0] = buVector5.ToPoint3D(pntIntersect);
                  points[points.Count - 1] = buVector5.ToPoint3D(pntIntersect);
                }
              }
              for (int index2 = 0; index2 <= points.Count - 1; ++index2)
                polygon.Add(ccVars.planeActive.Project(ent.Vertices[index2]));
              bool flag1 = Utility.PointInPolygon(ccVars.planeActive.Project(pntEnd), (IList<Point2D>) polygon);
              LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
              Point3D b1 = new Point3D();
              Point3D b2 = new Point3D();
