          if (Ent1 != null)
          {
            ((CustomData) Ent1.EntityData).ActionName = actionName;
            Ent1.LayerName = entity.LayerName;
            this.AddEntity(Ent1);
          }
          Entity Ent2 = (Entity) null;
          ((Entity) upper).EntityData = (object) EntityDataSet.ConvertCustomData(EntData);
          this.CreateEntity((Entity) upper, ref Ent2);
          if (Ent2 != null)
          {
            ((CustomData) Ent2.EntityData).ActionName = actionName;
            Ent2.LayerName = entity.LayerName;
            this.AddEntity(Ent2);
          }
          entity.Selected = true;
          this.OsnapDeleteByEntityName(clsInit.cVector5.GetEntityName(entity));
          this.Delete(true);
          if (!clsVar.appModes_0.TuftingMode.Enable)
            ;
