  public void ResetSelectedEntities(int PageIndex)
  {
    if (ccVars.Pages.Count <= 0)
      return;
    for (int index1 = 0; index1 <= ccVars.Pages[PageIndex].Form.viewportcad.Entities.Count - 1; ++index1)
    {
      ccVars.Pages[PageIndex].Form.viewportcad.Entities[index1].Selected = false;
      if (ccVars.Pages[PageIndex].Form.viewportcad.Entities[index1].GetType() == typeof (Brep))
      {
        ((Brep) ccVars.Pages[PageIndex].Form.viewportcad.Entities[index1]).ClearEdgesSelection((Stack<BlockReference>) null);
        ((Brep) ccVars.Pages[PageIndex].Form.viewportcad.Entities[index1]).ClearFacesSelection((Stack<BlockReference>) null);
        ((Brep) ccVars.Pages[PageIndex].Form.viewportcad.Entities[index1]).ClearVerticesSelection((Stack<BlockReference>) null);
        for (int index2 = 0; index2 <= ((Brep) ccVars.Pages[PageIndex].Form.viewportcad.Entities[index1]).Edges.Length - 1; ++index2)
        {
          ICurve curve = ((Brep) ccVars.Pages[PageIndex].Form.viewportcad.Entities[index1]).Edges[index2].Curve;
          if (curve.GetType() == typeof (Line))
            ((Entity) curve).Selected = false;
          if (curve.GetType() == typeof (Arc))
            ((Entity) curve).Selected = false;
        }
      }
    }
  }

  public void MoveToPlane(double X, double Y, devDept.Geometry.Plane refPlane, ref Point3D refPoint)
  {
    Point3D point3D = new Point3D(X, Y);
    List<Point3D> points = new List<Point3D>();
    points.Add(point3D);
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane((IList<Point3D>) points, refPlane);
    refPoint = points[0];
  }

