                        ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Add(new OsnapPoint(buVector5.ToPoint3D(Points), osnapType.Point));
                        ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Add(new OsnapPoint(Point3D.MidPoint(ccVars.pntBase, Points), osnapType.Middle));
                        ccVars.pntBuffered.Add(buVector5.ToPoint3D(Points));
                        ccVars.pntDrawDynamicArr = new Point3D[ccVars.pntBuffered.Count + 1];
                        for (int index = 0; index <= ccVars.pntBuffered.Count - 1; ++index)
                          ccVars.pntDrawDynamicArr[index] = buVector5.ToPoint3D(ccVars.pntBuffered[index]);
                        ccVars.pntDrawDynamicArr[ccVars.pntBuffered.Count] = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
                        if (clsVar.varEntities.FinishPolylineIfClosed && ccVars.pntBuffered.Count >= 3 && buCompare5.EQ(ccVars.pntBuffered[0], ccVars.pntBuffered[ccVars.pntBuffered.Count - 1], clsVar.varSelection.CompareResolution))
