                        ccVars.pntBase = buVector5.ToPoint3D(Points);
                        return;
                      }
                      if (ccVars.Action == actionTypeBU.solid3DRemoveTriangle)
                      {
                        this.doMeshRemoveTrianlge(ccVars.planeActive, ccVars.pntBase, Points);
                        this.Reset();
                        return;
                      }
                      if (ccVars.Action == actionTypeBU.libraryLinePoint)
                      {
                        clsInit.appLibrary.doAddConstraints(Points);
                        return;
                      }
                      if (ccVars.Action != actionTypeBU.libraryPointPoint)
                        return;
                      clsInit.appLibrary.doAddConstraints(ccVars.pntStart, Points);
                      return;
                  }
              }
          }
        }
      }
    }
  }

