  public void DownStep4(Point3D Points, object sender, MouseEventArgs e)
  {
    double s1;
    double t1;
    ccVars.planeActive.Project(Points, out s1, out t1);
    double s2;
    double t2;
    ccVars.planeActive.Project(ccVars.pntBase, out s2, out t2);
    dynamicInfo.Len = clsInit.cVector5.Length2D(s1, t1, s2, t2);
    dynamicInfo.Ang = clsInit.cVector5.PointAngle(s1, t1, s2, t2);
    dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
    dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
    dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
    if (ccVars.Action == actionTypeBU.drawArc)
    {
      Arc Ent = new Arc(ccVars.planeActive, ccVars.pntBase, dynamicInfo.Rad, ccVars.pntTip, Points, false);
      EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Arc", (string) null, Ent.Center);
      this.CreateArc(ccVars.pntBase, dynamicInfo.Rad, ccVars.pntTip, Points, ccVars.planeActive, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
      if (Ent != null)
        this.AddArc(Ent);
      this.Reset();
      if (!clsVar.varProgram.DrawCommandRepitation)
        return;
      this.cmdDrawArcCenter();
    }
    else
    {
      if (ccVars.Action == actionTypeBU.drawEllipseArc && dynamicInfo.MinorRad > 0.001 & dynamicInfo.MajorRad > 0.001)
      {
        Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
        clsInit.cVector5.PointAngle(Points, ccVars.pntBase, ccVars.planeActive);
        Pnt3D EndPnt = new Pnt3D();
        clsInit.cVector.LineWithLengthAndAngle(buConversion5.Point3DToPnt3D(ccVars.pntBase), 1000.0, dynamicInfo.Ang, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref EndPnt);
        Line C2 = new Line(ccVars.pntBase, Points);
        Point3D[] point3DArray = ellipse.IntersectWith((ICurve) C2, 0.0, true);
        if (point3DArray != null && point3DArray.Length != 0)
        {
          ccVars.pntStart = buVector5.ToPoint3D(point3DArray[0]);
          ellipse.ClosestPointTo(point3DArray[0], out dynamicInfo.StartLen);
        }
        ccVars.stpDrawing = 5;
      }
      if (ccVars.Action != actionTypeBU.eventRotate)
        return;
      double s3 = 0.0;
      double t3 = 0.0;
      ccVars.planeActive.Project(ccVars.pntTip, out s3, out t3);
      Vector2D u = new Vector2D(new Point2D(s2, t2), new Point2D(s3, t3));
      u.Normalize();
      Vector2D v = new Vector2D(new Point2D(s2, t2), new Point2D(s1, t1));
      v.Normalize();
      double angleInRadian = Vector2D.SignedAngleBetween(u, v);
      this.Rotate(ccVars.pntBase, angleInRadian, clsVar.varInterface.RotateVar.DeleteOriginal, clsVar.varProgram.EventCommandRepitation);
    }
  }

  public void DownStep5(Point3D Points, object sender, MouseEventArgs e)
  {
    double s1;
    double t1;
    ccVars.planeActive.Project(Points, out s1, out t1);
    double s2;
    double t2;
    ccVars.planeActive.Project(ccVars.pntBase, out s2, out t2);
    dynamicInfo.Len = clsInit.cVector5.Length2D(s1, t1, s2, t2);
    dynamicInfo.Ang = clsInit.cVector5.PointAngle(s1, t1, s2, t2);
    dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
    dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
    dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
    if (ccVars.Action != actionTypeBU.drawEllipseArc || !(dynamicInfo.MinorRad > 0.001 & dynamicInfo.MajorRad > 0.001))
      return;
    Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
    EllipticalArc Ent = (EllipticalArc) null;
    Line C2 = new Line(ccVars.pntBase, Points);
    Point3D[] point3DArray = ellipse.IntersectWith((ICurve) C2, 0.0, true);
    if (point3DArray != null && point3DArray.Length != 0)
      ellipse.ClosestPointTo(point3DArray[0], out dynamicInfo.EndLen);
    if (dynamicInfo.StartLen > dynamicInfo.EndLen)
      dynamicInfo.EndLen += 2.0 * Math.PI;
    if (dynamicInfo.EndLen - dynamicInfo.StartLen > 2.0 * Math.PI)
      dynamicInfo.EndLen = dynamicInfo.StartLen + 2.0 * Math.PI;
    EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "EllipseArc", (string) null, ccVars.pntBase);
    this.CreateEllipseArc(ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad, dynamicInfo.StartLen, dynamicInfo.EndLen, ccVars.planeTemp, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
    if (Ent != null)
      this.AddEllipseArc(Ent);
    this.Reset();
    if (!clsVar.varProgram.DrawCommandRepitation)
      return;
    this.cmdDrawEllipseArcCenter();
  }

