      clsInit.cVector.Barrel(new Pnt3D(s, t), clsVar.varInterface.BarrelVar.HeadRadius, clsVar.varInterface.BarrelVar.TaleRadius, clsVar.varInterface.BarrelVar.Length, clsVar.varInterface.BarrelVar.Angle, clsVar.varInterface.BarrelVar.Reverse, new WorkPlane(), buSystem.EntitiesResolution, ref CalculatedPoints);
      ccVars.pntDrawDynamicArr = new Point3D[CalculatedPoints.Count];
      for (int index = 0; index <= CalculatedPoints.Count - 1; ++index)
        ccVars.pntDrawDynamicArr[index] = new Point3D(CalculatedPoints[index].X, CalculatedPoints[index].Y, CalculatedPoints[index].Z);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane((IList<Point3D>) ccVars.pntDrawDynamicArr, ccVars.planeActive);
    }
    if (ccVars.Action == actionTypeBU.drawSlotFast)
    {
      double s;
      double t;
      ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.Project(Points, out s, out t);
      CompositeCurve slot = CompositeCurve.CreateSlot(ccVars.planeActive, s, t, clsVar.varInterface.SlotVar.Length, clsVar.varInterface.SlotVar.Radius, Utility.DegToRad(clsVar.varInterface.SlotVar.Angle), true);
      slot.Regen(0.1);
      ccVars.pntDrawDynamicArr = new Point3D[slot.Vertices.Length];
      for (int index = 0; index <= slot.Vertices.Length - 1; ++index)
        ccVars.pntDrawDynamicArr[index] = buVector5.ToPoint3D(slot.Vertices[index]);
    }
    if (ccVars.Action == actionTypeBU.drawObjectText)
    {
      Text text = new Text(ccVars.planeActive, Points, clsVar.varInterface.TextVar.Text, clsVar.varInterface.TextVar.Height, buConversion5.buAligntoEyeAlign(clsVar.varInterface.TextVar.Alignment));
      RegenParams data = new RegenParams(0.1, (IWorkspace) ccVars.Pages[ccVars.PageIndex].Form.viewportcad);
      text.Regen(data);
      if (text.Vertices[0] != text.Vertices[text.Vertices.Length - 1])
      {
        ccVars.pntDrawDynamicArr = new Point3D[text.Vertices.Length + 1];
        ccVars.pntDrawDynamicArr[text.Vertices.Length] = buVector5.ToPoint3D(text.Vertices[0]);
      }
      else
        ccVars.pntDrawDynamicArr = new Point3D[text.Vertices.Length];
      for (int index = 0; index <= text.Vertices.Length - 1; ++index)
        ccVars.pntDrawDynamicArr[index] = buVector5.ToPoint3D(text.Vertices[index]);
    }
    if (ccVars.Action == actionTypeBU.drawVectorText)
    {
      ccVars.pntDrawDynamicLinesArr.Clear();
      for (int index1 = 0; index1 <= ccVars.ContourPoints.Count - 1; ++index1)
      {
        List<Point3D> CopiedPnt = new List<Point3D>();
        List<Pnt3D> pnt3DList = new List<Pnt3D>();
        Pnt3D.Copy(ccVars.ContourPoints[index1].Outter, ref pnt3DList);
        clsInit.cVector.Move(new Pnt3D(), new Pnt3D(Points.X, Points.Y, Points.Z), ref pnt3DList);
        if (ccVars.VectorTextRunVar.DrawAsCurve)
        {
          List<Pnt3D> CalculatedPoints = new List<Pnt3D>();
          clsInit.cVector.BSplineQuadraticUniform(pnt3DList, 0.1, true, ref CalculatedPoints);
          buConversion5.Pnt3DToPoint3D(CalculatedPoints, ref CopiedPnt);
        }
        else
          buConversion5.Pnt3DToPoint3D(pnt3DList, ref CopiedPnt);
        ccVars.pntDrawDynamicLinesArr.Add(CopiedPnt);
        for (int index2 = 0; index2 <= ccVars.ContourPoints[index1].Holes.Count - 1; ++index2)
        {
          pnt3DList = new List<Pnt3D>();
          Pnt3D.Copy(ccVars.ContourPoints[index1].Holes[index2], ref pnt3DList);
          clsInit.cVector.Move(new Pnt3D(), new Pnt3D(Points.X, Points.Y, Points.Z), ref pnt3DList);
          CopiedPnt = new List<Point3D>();
          buConversion5.Pnt3DToPoint3D(pnt3DList, ref CopiedPnt);
          ccVars.pntDrawDynamicLinesArr.Add(CopiedPnt);
        }
      }
    }
    if (ccVars.Action != actionTypeBU.drawCustomText)
      return;
    ccVars.pntDrawDynamicLinesArr.Clear();
    for (int index3 = 0; index3 <= ccVars.ContourPoints5.Count - 1; ++index3)
    {
      List<Point3D> point3DList = new List<Point3D>();
      List<Pnt3D> pnt3DList1 = new List<Pnt3D>();
      buVector5.Copy(ccVars.ContourPoints5[index3].Outter, ref point3DList);
      clsInit.cVector5.Move(new Point3D(), new Point3D(Points.X, Points.Y, Points.Z), ref point3DList);
      ccVars.pntDrawDynamicLinesArr.Add(point3DList);
      for (int index4 = 0; index4 <= ccVars.ContourPoints5[index3].Inside.Count - 1; ++index4)
      {
        List<Pnt3D> pnt3DList2 = new List<Pnt3D>();
        point3DList = new List<Point3D>();
        buVector5.Copy(ccVars.ContourPoints5[index3].Inside[index4], ref point3DList);
        clsInit.cVector5.Move(new Point3D(), new Point3D(Points.X, Points.Y, Points.Z), ref point3DList);
        ccVars.pntDrawDynamicLinesArr.Add(point3DList);
      }
    }
  }

  public void MoveStep2(Point3D Points, object sender, MouseEventArgs e)
