      ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.Project(ccVars.pntTip, out s3, out t3);
      dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[0]}: {dynamicInfo.Len.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      List<Pnt3D> Vertices = new List<Pnt3D>();
      clsInit.cVector.PolygonStar(new Pnt3D(s2, t2), new Pnt3D(s3, t3), new Pnt3D(s1, t1), new WorkPlane(), ref Vertices);
      ccVars.pntDrawDynamicArr = new Point3D[Vertices.Count];
      for (int index = 0; index <= Vertices.Count - 1; ++index)
        ccVars.pntDrawDynamicArr[index] = new Point3D(Vertices[index].X, Vertices[index].Y, Vertices[index].Z);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane((IList<Point3D>) ccVars.pntDrawDynamicArr, ccVars.planeActive);
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.Len, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action == actionTypeBU.drawCircle3Point)
    {
      if (ccVars.pntStart.DistanceTo(Points) > 0.001 & ccVars.pntTip.DistanceTo(Points) > 0.001 & ccVars.pntStart.DistanceTo(ccVars.pntTip) > 0.001)
      {
        Circle circle = new Circle(ccVars.pntStart, ccVars.pntTip, Points);
        int num = clsInit.cVector.CircleVerticeCountByResolution(circle.Radius, clsVar.varEntities.DynamicEntityResolution);
        dynamicInfo.Rad = circle.Radius;
        ccVars.pntDrawDynamicArr = new Point3D[num + 1];
        for (int index = 0; index <= num; ++index)
          ccVars.pntDrawDynamicArr[index] = circle.PointAt(circle.Domain.ParameterAt((double) index / (double) num));
      }
      dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[19]}: {dynamicInfo.Rad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.Rad, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action == actionTypeBU.drawArc3PointSME)
    {
      if (ccVars.pntStart.DistanceTo(Points) > 0.001 & ccVars.pntTip.DistanceTo(Points) > 0.001 & ccVars.pntStart.DistanceTo(ccVars.pntTip) > 0.001)
      {
        Arc arc = new Arc(ccVars.pntStart, ccVars.pntTip, Points, false);
        int num = clsInit.cVector.CircleVerticeCountByResolution(arc.Radius, clsVar.varEntities.DynamicEntityResolution);
        dynamicInfo.Rad = arc.Radius;
        ccVars.pntDrawDynamicArr = new Point3D[num + 1];
        for (int index = 0; index <= num; ++index)
          ccVars.pntDrawDynamicArr[index] = arc.PointAt(arc.Domain.ParameterAt((double) index / (double) num));
      }
      dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[19]}: {dynamicInfo.Rad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.Rad, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action == actionTypeBU.drawArc3PointSEM | ccVars.Action == actionTypeBU.marbleDrawArc)
    {
      if (ccVars.pntStart.DistanceTo(Points) > 0.001 & ccVars.pntTip.DistanceTo(Points) > 0.001 & ccVars.pntStart.DistanceTo(ccVars.pntTip) > 0.001)
      {
        Arc arc = new Arc(ccVars.pntStart, Points, ccVars.pntTip, false);
        int num = clsInit.cVector.CircleVerticeCountByResolution(arc.Radius, clsVar.varEntities.DynamicEntityResolution);
        dynamicInfo.Rad = arc.Radius;
        ccVars.pntDrawDynamicArr = new Point3D[num + 1];
        for (int index = 0; index <= num; ++index)
          ccVars.pntDrawDynamicArr[index] = arc.PointAt(arc.Domain.ParameterAt((double) index / (double) num));
      }
      dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[19]}: {dynamicInfo.Rad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.Rad, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action == actionTypeBU.drawArc)
    {
      dynamicInfo.StartAng = dynamicInfo.Ang;
      if (dynamicInfo.Rad > 0.001)
      {
        Circle circle = new Circle(ccVars.planeActive, ccVars.pntBase, dynamicInfo.Rad);
        int num = clsInit.cVector.CircleVerticeCountByResolution(circle.Radius, clsVar.varEntities.DynamicEntityResolution);
        dynamicInfo.Rad = circle.Radius;
        ccVars.pntDrawDynamicArr = new Point3D[num + 1];
        for (int index = 0; index <= num; ++index)
          ccVars.pntDrawDynamicArr[index] = circle.PointAt(circle.Domain.ParameterAt((double) index / (double) num));
      }
      dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[22]}: {dynamicInfo.StartAng.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.StartAng, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action == actionTypeBU.drawEllipse)
    {
      dynamicInfo.MinorRad = Points.DistanceTo(new Segment3D(ccVars.pntBase, ccVars.pntTip));
      if (dynamicInfo.MinorRad > 0.001 & dynamicInfo.MajorRad > 0.001)
      {
        ccVars.planeTemp = new devDept.Geometry.Plane(ccVars.pntBase, ccVars.pntTip, Points);
        Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
        int num = clsInit.cVector.CircleVerticeCountByResolution(ellipse.RadiusX, clsVar.varEntities.DynamicEntityResolution);
        ccVars.pntDrawDynamicArr = new Point3D[num + 1];
        for (int index = 0; index <= num; ++index)
          ccVars.pntDrawDynamicArr[index] = ellipse.PointAt(ellipse.Domain.ParameterAt((double) index / (double) num));
      }
      dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[20]}: {dynamicInfo.MajorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} - {AppLanguage.CadCamDynamic[21]}: {dynamicInfo.MinorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.MinorRad, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action == actionTypeBU.drawEllipseArc)
    {
      dynamicInfo.MinorRad = Points.DistanceTo(new Segment3D(ccVars.pntBase, ccVars.pntTip));
      if (dynamicInfo.MinorRad > 0.001 & dynamicInfo.MajorRad > 0.001)
      {
        ccVars.planeTemp = new devDept.Geometry.Plane(ccVars.pntBase, ccVars.pntTip, Points);
        Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
        int num = clsInit.cVector.CircleVerticeCountByResolution(ellipse.RadiusX, clsVar.varEntities.DynamicEntityResolution);
        ccVars.pntDrawDynamicArr = new Point3D[num + 1];
        for (int index = 0; index <= num; ++index)
          ccVars.pntDrawDynamicArr[index] = ellipse.PointAt(ellipse.Domain.ParameterAt((double) index / (double) num));
      }
      dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[20]}: {dynamicInfo.MajorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} - {AppLanguage.CadCamDynamic[21]}: {dynamicInfo.MinorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.MinorRad, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action == actionTypeBU.drawSpline)
    {
      ccVars.pntStart.DistanceTo(Points);
      ccVars.pntTip.DistanceTo(Points);
      ccVars.pntStart.DistanceTo(ccVars.pntTip);
      ccVars.pntDrawDynamicLines.Clear();
      for (int index = 0; index <= ccVars.pntBuffered.Count - 1; ++index)
        ccVars.pntDrawDynamicLines.Add(buVector5.ToPoint3D(ccVars.pntBuffered[index]));
      ccVars.pntDrawDynamicLines.Add(buVector5.ToPoint3D(Points));
      if (clsVar.varInterface.SplineVar.Closed)
        ccVars.pntDrawDynamicLines.Add(buVector5.ToPoint3D(ccVars.pntDrawDynamicLines[0]));
      Curve curve = (Curve) null;
      if (clsVar.varInterface.SplineVar.Type == entitySplineType.SplineCubic)
        curve = Curve.CubicSplineInterpolation<Point3D>((IList<Point3D>) ccVars.pntDrawDynamicLines);
      else if (clsVar.varInterface.SplineVar.Type == entitySplineType.BsplineQuadratic)
        curve = new Curve(2, (IList<Point3D>) ccVars.pntDrawDynamicLines);
      else if (clsVar.varInterface.SplineVar.Type == entitySplineType.BsplineCubic)
        curve = new Curve(3, (IList<Point3D>) ccVars.pntDrawDynamicLines);
      int num = 100;
      ccVars.pntDrawDynamicArr = new Point3D[101];
      for (int index = 0; index <= num; ++index)
        ccVars.pntDrawDynamicArr[index] = curve.PointAt(curve.Domain.ParameterAt((double) index / (double) num));
      dynamicInfo.Len = Point3D.Distance(Points, ccVars.pntBase);
      dynamicInfo.Ang = clsInit.cVector5.PointAngle(Points, ccVars.pntBase, ccVars.planeActive);
      dynamicInfo.Info = $"{dynamicInfo.Info}{AppLanguage.CadCamDynamic[0]}: {dynamicInfo.Len.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} - {AppLanguage.CadCamDynamic[2]}: {dynamicInfo.Ang.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}º";
      clsInit.cVector.BoxSizeCalculate(buConversion5.Point3DToPnt3D(Points), buConversion5.Point3DToPnt3D(ccVars.pntBase), ref ccVars.Spin1Prop.pntMin, ref ccVars.Spin1Prop.pntMid, ref ccVars.Spin1Prop.pntMax);
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.Rad, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action == actionTypeBU.drawDimLinear)
    {
      ccVars.pntDrawDynamicLinesArr.Clear();
      eEntities StartPointExtension = new eEntities();
      eEntities EndPointExtension = new eEntities();
      eEntities DimLine = new eEntities();
      double s4;
      double t4;
      ccVars.planeActive.Project(ccVars.pntStart, out s4, out t4);
      double s5;
      double t5;
      ccVars.planeActive.Project(ccVars.pntEnd, out s5, out t5);
      clsInit.cVector.DimensionLinear(new Pnt3D(s4, t4), new Pnt3D(s5, t5), new Pnt3D(s1, t1), clsVar.varEntities.DimensionTextHeight, ref StartPointExtension, ref EndPointExtension, ref DimLine);
      ccVars.pntDrawDynamicLinesArr.Add(buConversion5.Pnt3dToPoint3D(StartPointExtension.Vertice));
      ccVars.pntDrawDynamicLinesArr.Add(buConversion5.Pnt3dToPoint3D(EndPointExtension.Vertice));
      ccVars.pntDrawDynamicLinesArr.Add(buConversion5.Pnt3dToPoint3D(DimLine.Vertice));
      ccVars.pntText = buVector5.ToPoint3D(Points);
      ccVars.dynamicTextOnMouse = "L = " + clsInit.cVector.Length3D(DimLine.Vertice[0], DimLine.Vertice[1]).ToString("f3");
      for (int index = 0; index <= ccVars.pntDrawDynamicLinesArr.Count - 1; ++index)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane((IList<Point3D>) ccVars.pntDrawDynamicLinesArr[index], ccVars.planeActive);
    }
    if (ccVars.Action == actionTypeBU.drawDimAlinged)
    {
      ccVars.pntDrawDynamicLinesArr.Clear();
      eEntities StartPointExtension = new eEntities();
      eEntities EndPointExtension = new eEntities();
      eEntities DimLine = new eEntities();
      double s6;
      double t6;
      ccVars.planeActive.Project(ccVars.pntStart, out s6, out t6);
      double s7;
      double t7;
      ccVars.planeActive.Project(ccVars.pntEnd, out s7, out t7);
      clsInit.cVector.DimensionAlign(new Pnt3D(s6, t6), new Pnt3D(s7, t7), new Pnt3D(s1, t1), ref StartPointExtension, ref EndPointExtension, ref DimLine);
      ccVars.pntDrawDynamicLinesArr.Add(buConversion5.Pnt3dToPoint3D(StartPointExtension.Vertice));
      ccVars.pntDrawDynamicLinesArr.Add(buConversion5.Pnt3dToPoint3D(EndPointExtension.Vertice));
      ccVars.pntDrawDynamicLinesArr.Add(buConversion5.Pnt3dToPoint3D(DimLine.Vertice));
      ccVars.pntText = buVector5.ToPoint3D(Points);
      ccVars.dynamicTextOnMouse = "L = " + clsInit.cVector.Length3D(DimLine.Vertice[0], DimLine.Vertice[1]).ToString("f3");
      for (int index = 0; index <= ccVars.pntDrawDynamicLinesArr.Count - 1; ++index)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane((IList<Point3D>) ccVars.pntDrawDynamicLinesArr[index], ccVars.planeActive);
    }
    if (ccVars.Action == actionTypeBU.eventMove)
    {
      ccVars.pntDrawDynamicLinesArr.Clear();
      for (int index1 = 0; index1 <= ccVars.SelectionOP.Selections.Count - 1; ++index1)
      {
        if (ccVars.SelectionOP.Selections[index1].SelectedLinearPaths.Count > 0)
        {
          Entity tempEntity = (Entity) ccVars.SelectionOP.Selections[index1].SelectedLinearPaths[0].Clone();
          Vector3D v = new Vector3D(ccVars.pntBase, Points);
          tempEntity.Translate(v);
          List<List<Point3D>> refPoints = new List<List<Point3D>>();
          clsInit.cVector5.DrawCurveOrBlockRef(tempEntity, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref refPoints);
          for (int index2 = 0; index2 <= refPoints.Count - 1; ++index2)
            ccVars.pntDrawDynamicLinesArr.Add(refPoints[index2]);
        }
      }
    }
    if (ccVars.Action == actionTypeBU.eventCopy)
    {
      ccVars.pntDrawDynamicLinesArr.Clear();
      for (int index3 = 0; index3 <= ccVars.SelectionOP.Selections.Count - 1; ++index3)
      {
        Entity tempEntity = (Entity) ccVars.SelectionOP.Selections[index3].SelectedLinearPaths[0].Clone();
        Vector3D v = new Vector3D(ccVars.pntBase, Points);
        tempEntity.Translate(v);
        List<List<Point3D>> refPoints = new List<List<Point3D>>();
        clsInit.cVector5.DrawCurveOrBlockRef(tempEntity, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref refPoints);
        for (int index4 = 0; index4 <= refPoints.Count - 1; ++index4)
          ccVars.pntDrawDynamicLinesArr.Add(refPoints[index4]);
      }
    }
    if (ccVars.Action == actionTypeBU.eventRotate)
    {
      dynamicInfo.Info = $"{dynamicInfo.Info}{AppLanguage.CadCamDynamic[0]}: {dynamicInfo.Len.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} - {AppLanguage.CadCamDynamic[2]}: {dynamicInfo.Ang.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}º";
      if (clsVar.varView.ShowDxDyDzValuesDynamicText)
        dynamicInfo.Info = $"{dynamicInfo.Info} dx: {dynamicInfo.dX.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} dy: {dynamicInfo.dY.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} dz: {dynamicInfo.dZ.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      clsInit.cVector.BoxSizeCalculate(buConversion5.Point3DToPnt3D(Points), buConversion5.Point3DToPnt3D(ccVars.pntBase), ref ccVars.Spin1Prop.pntMin, ref ccVars.Spin1Prop.pntMid, ref ccVars.Spin1Prop.pntMax);
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.Ang, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action != actionTypeBU.eventMirror)
      return;
    Vector3D X = new Vector3D(ccVars.pntBase, Points);
    if (X.Length <= 0.0)
      return;
    devDept.Geometry.Plane plane = new devDept.Geometry.Plane(ccVars.pntBase, X, ccVars.planeActive.AxisZ);
    ccVars.pntDrawDynamicLinesArr.Clear();
    for (int index5 = 0; index5 <= ccVars.SelectionOP.Selections.Count - 1; ++index5)
    {
      Entity tempEntity = (Entity) ccVars.SelectionOP.Selections[index5].SelectedLinearPaths[0].Clone();
      devDept.Geometry.Mirror xform = new devDept.Geometry.Mirror(plane);
      tempEntity.TransformBy((Transformation) xform);
      List<List<Point3D>> refPoints = new List<List<Point3D>>();
      clsInit.cVector5.DrawCurveOrBlockRef(tempEntity, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref refPoints);
      for (int index6 = 0; index6 <= refPoints.Count - 1; ++index6)
        ccVars.pntDrawDynamicLinesArr.Add(refPoints[index6]);
    }
  }

  public void MoveStep4(Point3D Points, object sender, MouseEventArgs e)
  {
    double s1;
    double t1;
    ccVars.planeActive.Project(Points, out s1, out t1);
    double s2;
    double t2;
    ccVars.planeActive.Project(ccVars.pntBase, out s2, out t2);
    dynamicInfo.Len = clsInit.cVector5.Length2D(s1, t1, s2, t2);
    dynamicInfo.Ang = clsInit.cVector5.PointAngle(s1, t1, s2, t2);
    dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
    dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
    dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
    if (clsVar.varView.ShowCommandDynamicText)
      dynamicInfo.Info = dynamicInfo.Command + " = ";
    if (ccVars.Action == actionTypeBU.drawArc)
    {
      dynamicInfo.EndAng = dynamicInfo.Ang;
      if (dynamicInfo.EndAng < dynamicInfo.StartAng)
        dynamicInfo.EndAng += 360.0;
      if (dynamicInfo.Rad > 0.001 & dynamicInfo.EndAng > dynamicInfo.StartAng)
      {
        Arc arc = new Arc(ccVars.planeActive, ccVars.pntBase, dynamicInfo.Rad, ccVars.pntTip, Points, false);
        int num = clsInit.cVector.CircleVerticeCountByResolution(arc.Radius, clsVar.varEntities.DynamicEntityResolution);
        dynamicInfo.Rad = arc.Radius;
        ccVars.pntDrawDynamicArr = new Point3D[num + 1];
        for (int index = 0; index <= num; ++index)
          ccVars.pntDrawDynamicArr[index] = arc.PointAt(arc.Domain.ParameterAt((double) index / (double) num));
      }
      dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[23]}: {dynamicInfo.EndAng.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      clsInit.cVector.BoxSizeCalculate(buConversion5.Point3DToPnt3D(Points), buConversion5.Point3DToPnt3D(ccVars.pntBase), ref ccVars.Spin1Prop.pntMin, ref ccVars.Spin1Prop.pntMid, ref ccVars.Spin1Prop.pntMax);
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.EndAng, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action == actionTypeBU.drawEllipseArc)
    {
      if (dynamicInfo.MinorRad > 0.001 & dynamicInfo.MajorRad > 0.001)
      {
        Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
        int num = clsInit.cVector.CircleVerticeCountByResolution(ellipse.RadiusX, clsVar.varEntities.DynamicEntityResolution);
        ccVars.pntDrawDynamicArr = new Point3D[num + 1];
        for (int index = 0; index <= num; ++index)
          ccVars.pntDrawDynamicArr[index] = ellipse.PointAt(ellipse.Domain.ParameterAt((double) index / (double) num));
      }
      dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[20]}: {dynamicInfo.MajorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} - {AppLanguage.CadCamDynamic[21]}: {dynamicInfo.MinorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
      clsInit.cVector.BoxSizeCalculate(buConversion5.Point3DToPnt3D(Points), buConversion5.Point3DToPnt3D(ccVars.pntBase), ref ccVars.Spin1Prop.pntMin, ref ccVars.Spin1Prop.pntMid, ref ccVars.Spin1Prop.pntMax);
      ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.MinorRad, clsVar.varProgram.DecimalVisiblePoint);
    }
    if (ccVars.Action != actionTypeBU.eventRotate)
      return;
    ccVars.pntDrawDynamicLinesArr.Clear();
    for (int index1 = 0; index1 <= ccVars.SelectionOP.Selections.Count - 1; ++index1)
    {
      if (ccVars.SelectionOP.Selections[index1].SelectedLinearPaths.Count > 0)
      {
        Entity selectedLinearPath = ccVars.SelectionOP.Selections[index1].SelectedLinearPaths[0];
        double s3 = 0.0;
        double t3 = 0.0;
        ccVars.planeActive.Project(ccVars.pntTip, out s3, out t3);
        Vector2D u = new Vector2D(new Point2D(s2, t2), new Point2D(s3, t3));
        u.Normalize();
        Vector2D v = new Vector2D(new Point2D(s2, t2), new Point2D(s1, t1));
        v.Normalize();
        double num = Vector2D.SignedAngleBetween(u, v);
        dynamicInfo.Info = $"{dynamicInfo.Info} : {buConversion.RadianToDegree(num).ToString("f3")}";
        ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(buConversion.RadianToDegree(num), clsVar.varProgram.DecimalVisiblePoint);
        Entity tempEntity = (Entity) selectedLinearPath.Clone();
        tempEntity.Rotate(num, ccVars.planeActive.AxisZ, ccVars.pntBase);
        List<List<Point3D>> refPoints = new List<List<Point3D>>();
        clsInit.cVector5.DrawCurveOrBlockRef(tempEntity, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref refPoints);
        for (int index2 = 0; index2 <= refPoints.Count - 1; ++index2)
          ccVars.pntDrawDynamicLinesArr.Add(refPoints[index2]);
      }
    }
  }

  public void MoveStep5(Point3D Points, object sender, MouseEventArgs e)
  {
    double s1;
    double t1;
    ccVars.planeActive.Project(Points, out s1, out t1);
    double s2;
    double t2;
    ccVars.planeActive.Project(ccVars.pntBase, out s2, out t2);
    dynamicInfo.Len = clsInit.cVector5.Length2D(s1, t1, s2, t2);
    dynamicInfo.Ang = clsInit.cVector5.PointAngle(s1, t1, s2, t2);
    dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
    dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
    dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
    if (clsVar.varView.ShowCommandDynamicText)
      dynamicInfo.Info = dynamicInfo.Command + " = ";
    if (ccVars.Action != actionTypeBU.drawEllipseArc)
      return;
    if (dynamicInfo.MinorRad > 0.001 & dynamicInfo.MajorRad > 0.001)
    {
      Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
      double Angle = clsInit.cVector5.PointAngle(Points, ccVars.pntBase, ccVars.planeActive);
      Pnt3D EndPnt = new Pnt3D();
      clsInit.cVector.LineWithLengthAndAngle(buConversion5.Point3DToPnt3D(ccVars.pntBase), 1000.0, Angle, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref EndPnt);
      Line C2 = new Line(ccVars.pntBase, Points);
      Point3D[] point3DArray = ellipse.IntersectWith((ICurve) C2, 0.0, true);
      if (point3DArray != null && point3DArray.Length != 0)
        ellipse.ClosestPointTo(point3DArray[0], out dynamicInfo.EndLen);
      if (dynamicInfo.StartLen > dynamicInfo.EndLen)
        dynamicInfo.EndLen += 2.0 * Math.PI;
      if (dynamicInfo.EndLen - dynamicInfo.StartLen > 2.0 * Math.PI)
        dynamicInfo.EndLen = dynamicInfo.StartLen + 2.0 * Math.PI;
      EllipticalArc ellipticalArc = new EllipticalArc(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad, dynamicInfo.StartLen, dynamicInfo.EndLen);
      int num = clsInit.cVector.CircleVerticeCountByResolution(ellipticalArc.RadiusX, clsVar.varEntities.DynamicEntityResolution);
      ccVars.pntDrawDynamicArr = new Point3D[num + 1];
      for (int index = 0; index <= num; ++index)
        ccVars.pntDrawDynamicArr[index] = ellipticalArc.PointAt(ellipticalArc.Domain.ParameterAt((double) index / (double) num));
    }
    dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[20]}: {dynamicInfo.MajorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} - {AppLanguage.CadCamDynamic[21]}: {dynamicInfo.MinorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
    clsInit.cVector.BoxSizeCalculate(buConversion5.Point3DToPnt3D(Points), buConversion5.Point3DToPnt3D(ccVars.pntBase), ref ccVars.Spin1Prop.pntMin, ref ccVars.Spin1Prop.pntMid, ref ccVars.Spin1Prop.pntMax);
    ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (Decimal) Math.Round(dynamicInfo.MinorRad, clsVar.varProgram.DecimalVisiblePoint);
  }

  public void viewportMouseUp(Point3D Points, object sender, MouseEventArgs e)
  {
    try
    {
      if (Points != (Point3D) null)
      {
        ccVars.pntMouseUp.X = Points.X;
        ccVars.pntMouseUp.Y = Points.Y;
        ccVars.pntMouseUp.Z = Points.Z;
      }
      // ISSUE: reference to a compiler-generated field
      if (this.mouseDownViewport_1 != null)
      {
        // ISSUE: reference to a compiler-generated field
        this.mouseDownViewport_1(Points.X, Points.Y, Points.Z, sender, e);
      }
      if (clsInit.appDrill != null & clsVar.UserMode.DrillMode.Enable)
        clsInit.appDrill.viewportMouseUp(Points, sender, e);
      if (clsInit.appMarble != null & clsVar.UserMode.MarbleMode.Enable)
        clsInit.appMarble.viewportMouseUp(Points, sender, e);
      if (ccVars.stpDrawing == 0 & ccVars.Action == actionTypeBU.None & e.Button == MouseButtons.Left)
      {
        this.UpStep0(Points, sender, e);
      }
      else
      {
        switch (ccVars.stpDrawing)
        {
          case 1:
            this.UpStep1(Points, sender, e);
            break;
          case 2:
            this.UpStep2(Points, sender, e);
            break;
          case 3:
            this.UpStep3(Points, sender, e);
            break;
          case 4:
            this.UpStep4(Points, sender, e);
            break;
          case 5:
            this.UpStep5(Points, sender, e);
            break;
        }
      }
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

