            return;
          clsInit.appCutter.doOffsetDrawing();
        }
        else if (ccVars.Action == actionTypeBU.routerCamMesh3DParalelCut | ccVars.Action == actionTypeBU.routerCamMesh3DRough | ccVars.Action == actionTypeBU.routerCamMesh3DConstantZ | ccVars.Action == actionTypeBU.routerCamMesh3DFlatLand | ccVars.Action == actionTypeBU.routerCamMesh3DPencil && e.Button == MouseButtons.Right & clsInit.appRouter3AX != null)
        {
          if (ccVars.SelectionOP.Selections.Count <= 0)
            return;
          switch (ccVars.Action)
          {
            case actionTypeBU.routerCamMesh3DRough:
              clsInit.appRouter3AX.cmdCamMeshCommand(CamTriangularMeshType.Rough);
              break;
            case actionTypeBU.routerCamMesh3DParalelCut:
              clsInit.appRouter3AX.cmdCamMeshCommand(CamTriangularMeshType.ParallelCuts);
              break;
            case actionTypeBU.routerCamMesh3DConstantZ:
              clsInit.appRouter3AX.cmdCamMeshCommand(CamTriangularMeshType.ConstantZ);
              break;
            case actionTypeBU.routerCamMesh3DFlatLand:
              clsInit.appRouter3AX.cmdCamMeshCommand(CamTriangularMeshType.Flatlands);
              break;
            case actionTypeBU.routerCamMesh3DPencil:
              clsInit.appRouter3AX.cmdCamMeshCommand(CamTriangularMeshType.Pencil);
              break;
          }
        }
        else if (ccVars.Action == actionTypeBU.routerCamMesh5AXParalelCut | ccVars.Action == actionTypeBU.routerCamMesh5AXConstantZ | ccVars.Action == actionTypeBU.routerCamMesh5AXRough && e.Button == MouseButtons.Right & clsInit.appRouter3AX != null)
        {
          if (ccVars.SelectionOP.Selections.Count <= 0)
            return;
          switch (ccVars.Action)
          {
            case actionTypeBU.routerCamMesh5AXParalelCut:
              clsInit.appRouter3AX.cmdCamMesh5AXCommand(CamTriangularMesh5AxType.ParallelCuts);
              break;
            case actionTypeBU.routerCamMesh5AXConstantZ:
              clsInit.appRouter3AX.cmdCamMesh5AXCommand(CamTriangularMesh5AxType.ConstantZ);
              break;
            case actionTypeBU.routerCamMesh5AXRough:
              clsInit.appRouter3AX.cmdCamMesh5AXCommand(CamTriangularMesh5AxType.Rough);
              break;
          }
        }
        else
        {
          switch (ccVars.Action)
          {
            case actionTypeBU.libraryLinePoint:
              if (clsInit.appLibrary == null || ccVars.SelectionOP.Selections.Count < 1)
                break;
              ccVars.stpDrawing = 2;
              ccVars.selectionProcess = false;
              break;
            case actionTypeBU.libCharCreat:
              if (clsInit.appLibrary == null || ccVars.SelectionOP.Selections.Count < 1)
                break;
              ccVars.selectionProcess = false;
              clsInit.appLibrary.doAddChar();
              break;
            default:
              if (!(ccVars.Action == actionTypeBU.libraryHorizontal | ccVars.Action == actionTypeBU.libraryVertical | ccVars.Action == actionTypeBU.libraryEqualLength | ccVars.Action == actionTypeBU.libraryEqualRadius | ccVars.Action == actionTypeBU.libraryParalel | ccVars.Action == actionTypeBU.libraryLength | ccVars.Action == actionTypeBU.libraryPerpendiculat | ccVars.Action == actionTypeBU.libraryTangent | ccVars.Action == actionTypeBU.libraryLineLine | ccVars.Action == actionTypeBU.libraryCollinear | ccVars.Action == actionTypeBU.libraryAngle | ccVars.Action == actionTypeBU.libraryRadius) || e.Button != MouseButtons.Right || clsInit.appLibrary == null)
                break;
              clsInit.appLibrary.doAddConstraints(new Point3D());
              break;
          }
        }
      }
    }
  }

  public void UpStep2(Point3D Points, object sender, MouseEventArgs e)
  {
    if (ccVars.Action == actionTypeBU.eventRotateVerHor)
    {
      if (ViewportCC.PickedLastEntity == null || !(ViewportCC.PickedLastEntity is Line))
        return;
      double Degree = clsInit.cVector5.PointAngle(((ICurve) ViewportCC.PickedLastEntity).EndPoint, ((ICurve) ViewportCC.PickedLastEntity).StartPoint);
      if (!buCompare5.EQ(Degree, 0.0) & !buCompare5.EQ(Degree, 180.0))
      {
        ccVars.pntBase = buVector5.ToPoint3D(((ICurve) ViewportCC.PickedLastEntity).StartPoint);
        ccVars.pntTip = buVector5.ToPoint3D(((ICurve) ViewportCC.PickedLastEntity).EndPoint);
        this.Rotate(ccVars.pntBase, -buConversion5.DegreeToRadian(Degree), clsVar.varInterface.RotateVar.DeleteOriginal, false);
      }
      else
      {
        ccVars.pntBase = buVector5.ToPoint3D(((ICurve) ViewportCC.PickedLastEntity).StartPoint);
        ccVars.pntTip = buVector5.ToPoint3D(((ICurve) ViewportCC.PickedLastEntity).EndPoint);
        this.Rotate(ccVars.pntBase, buConversion5.DegreeToRadian(90.0), clsVar.varInterface.RotateVar.DeleteOriginal, false);
      }
    }
    else if (ccVars.Action == actionTypeBU.drawFreeDraw && clsVar.varInterface.FreeDrawVar.MouseMode == FreeDrawMouseModeType.DownUp)
    {
      if (ccVars.pntDrawDynamicLines.Count < 2)
        return;
      Entity Ent = (Entity) null;
      EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Polyline", (string) null, ccVars.pntBase);
      this.CreateFreeDraw(ccVars.pntDrawDynamicLines, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
      if (clsVar.appModes_0.TuftingMode.Enable)
        clsInit.appTufting.doAddManuelEntities(Ent);
      else
        this.AddEntity(Ent);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
      ccVars.pntDrawDynamicLines.Clear();
      ccVars.stpDrawing = 1;
    }
    else
    {
      switch (ccVars.Action)
      {
        case actionTypeBU.camContours:
          if (e.Button == MouseButtons.Left & ViewportCC.currPickState != pickStateType.Crossing & ViewportCC.currPickState != pickStateType.Enclosed)
          {
