        if (e.Button == MouseButtons.Left & ViewportCC.currPickState != pickStateType.Crossing & ViewportCC.currPickState != pickStateType.Enclosed)
        {
          GetChainEntitiesSettings Settings = new GetChainEntitiesSettings(true, ViewportCC.entityPickIndex, clsVar.varSelection.UseSelectedEntityLayerForChainEntities);
          clsInit.cVector5.GetChainEntities(Points, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList<Entity>(), ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, Settings, ref ccVars.SelectionOP);
          return;
        }
        if (e.Button == MouseButtons.Right)
        {
          clsInit.appSpinning.doSpinPattern();
          return;
        }
      }
      if (ccVars.Action == actionTypeBU.nestingAddPartFromSelection | ccVars.Action == actionTypeBU.nestingAddMaterialShapeFromSelection)
      {
        if (e.Button == MouseButtons.Left & ViewportCC.currPickState != pickStateType.Crossing & ViewportCC.currPickState != pickStateType.Enclosed)
        {
          GetChainEntitiesSettings Settings1 = new GetChainEntitiesSettings(true, ViewportCC.entityPickIndex, clsVar.varSelection.UseSelectedEntityLayerForChainEntities);
          Settings1.UseMinDistance = true;
          Settings1.MinDistance = 10.0;
          if (ViewportCC.entityPickIndex >= 0)
          {
            clsInit.cVector5.GetChainEntities(Points, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList<Entity>(), ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, Settings1, ref ccVars.SelectionOP);
            return;
          }
          List<Entity> entityList1 = new List<Entity>();
          List<int> intList1 = new List<int>();
          List<Entity> BaseRefEntities = new List<Entity>();
          List<Entity> entityList2 = new List<Entity>();
          List<Entity> SortedEntities = new List<Entity>();
          List<List<Entity>> entityListList = new List<List<Entity>>();
          for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
          {
            if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is ICurve)
            {
              if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].GetType() == typeof (LinearPath))
              {
                LinearPath entity1 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] as LinearPath;
                if (entity1.IsClosed)
                {
                  List<Point3D> PointList = new List<Point3D>();
                  buVector5.VerticeToPointsList(entity1.Vertices, ref PointList);
                  if (clsInit.cVector5.IsPointInsidePolygon(PointList, Points))
                  {
                    List<Entity> entityList3 = new List<Entity>();
                    Entity entity2 = buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]);
                    ((CustomData) entity2.EntityData).OriginalEntityIndex = index;
                    entityList3.Add(entity2);
                    if (clsNesting.ParNest.AddPart.OutterContourLayerName.Trim().Length == 0)
                      entityListList.Add(entityList3);
                    else if (entity1.LayerName == clsNesting.ParNest.AddPart.OutterContourLayerName)
                      entityListList.Add(entityList3);
                  }
                }
                else
                {
                  Entity entity3 = buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]);
                  ((CustomData) entity3.EntityData).OriginalEntityIndex = index;
                  BaseRefEntities.Add(entity3);
                }
              }
              else if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].GetType() != typeof (devDept.Eyeshot.Entities.Point))
              {
                Entity entity = buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]);
                ((CustomData) entity.EntityData).OriginalEntityIndex = index;
                BaseRefEntities.Add(entity);
              }
            }
          }
          SortSettings Settings2 = new SortSettings();
          SortResult Result = new SortResult();
          Settings2.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
          clsInit.cVector5.SortEntitiesByRefPoint(Points, ref BaseRefEntities, Settings2, ref SortedEntities, ref Result);
          List<List<Entity>> SplitedEntitites = new List<List<Entity>>();
          clsInit.cVector5.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
          for (int index = 0; index <= SplitedEntitites.Count - 1; ++index)
          {
            if (clsInit.cVector5.isEntitiesClosed(SplitedEntitites[index]))
            {
              List<Point3D> Points1 = new List<Point3D>();
              clsInit.cVector5.EntitiesToPointsWithCamDirection(SplitedEntitites[index], clsVar.varEntities.RegenDeviation, ref Points1);
              if (clsInit.cVector5.IsPointInsidePolygon(Points1, Points))
              {
                if (clsNesting.ParNest.AddPart.OutterContourLayerName.Trim().Length == 0)
                  entityListList.Add(SplitedEntitites[index]);
                else if (SplitedEntitites[index][0].LayerName == clsNesting.ParNest.AddPart.OutterContourLayerName)
                  entityListList.Add(SplitedEntitites[index]);
              }
            }
          }
          if (entityListList.Count <= 0)
            return;
          bool isSheet = true;
          if (ccVars.Action == actionTypeBU.nestingAddPartFromSelection)
            isSheet = false;
          int index1 = -1;
          for (int index2 = 0; index2 <= entityListList.Count - 1; ++index2)
          {
            List<int> intList2 = new List<int>();
            for (int index3 = 0; index3 <= entityListList[index2].Count - 1; ++index3)
              index1 = ((CustomData) entityListList[index2][index3].EntityData).OriginalEntityIndex;
            if (index1 >= 0 & index1 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
            {
              intList2.Add(index1);
              ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].Selected = true;
            }
            if (!clsInit.appNesting.doAddShapePartAndSheet(Points, isSheet, entityListList[index2]))
            {
              for (int index4 = 0; index4 <= intList2.Count - 1; ++index4)
                ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].Selected = false;
              index2 = entityListList.Count;
            }
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
          }
          if (!(clsNesting.ParNest.AddPart.DeleteSelectedAuxEntities | clsNesting.ParNest.AddPart.DeleteSelectedEntities))
            return;
          clsInit.appCommand.Delete(false);
          return;
        }
        if (e.Button == MouseButtons.Right)
        {
          bool isSheet = true;
          if (ccVars.Action == actionTypeBU.nestingAddPartFromSelection)
            isSheet = false;
          clsInit.appNesting.doAddShapePartAndSheet(Points, isSheet, new List<Entity>());
          return;
        }
      }
      if (ccVars.Action == actionTypeBU.cutterAddPartFromSelection)
      {
        List<Entity> selectedEntities = new List<Entity>();
        if (ccVars.SelectionOP.Selections.Count > 0)
        {
          SelectionOption Option = new SelectionOption();
          clsInit.appCommand.SelectionToEntities(ref selectedEntities, Option);
        }
        bool flag = false;
        if (selectedEntities.Count > 0)
          flag = clsInit.cVector5.isEntitiesClosed(selectedEntities);
        if (e.Button == MouseButtons.Right | flag)
        {
          clsInit.appNesting.doAddShapePartAndSheet(Points, false, new List<Entity>());
          return;
        }
      }
      if (ccVars.Action != actionTypeBU.diemakerSlotCam)
        return;
      if (e.Button == MouseButtons.Left & ViewportCC.currPickState != pickStateType.Crossing & ViewportCC.currPickState != pickStateType.Enclosed)
      {
        GetChainEntitiesSettings Settings = new GetChainEntitiesSettings(true, ViewportCC.entityPickIndex, clsVar.varSelection.UseSelectedEntityLayerForChainEntities);
        clsInit.cVector5.GetChainEntities(Points, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList<Entity>(), ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, Settings, ref ccVars.SelectionOP);
      }
      else
      {
        if (e.Button != MouseButtons.Right)
          return;
        clsInit.appDiemaker.doSlot();
      }
    }
  }

