  public void viewportSelectionChanged(object sender, SelectionChangedEventArgs e)
  {
    object[] objArray = new object[e.AddedItems.Count];
    int num = 0;
    MeasureItem measureItem = (MeasureItem) null;
    Brep refEntity = (Brep) null;
    Brep.Edge refEdge = (Brep.Edge) null;
    int SelectedIndex = -1;
    for (int index = 0; index < e.AddedItems.Count; ++index)
    {
      SelectedItem addedItem = e.AddedItems[index];
      switch (addedItem)
      {
        case SelectedFace _:
          SelectedFace selectedFace = (SelectedFace) addedItem;
          ISelectableItem selectableItem1 = selectedFace.Item;
          switch (selectableItem1)
          {
            case Brep _:
              refEntity = (Brep) selectableItem1;
              Brep brep1 = (Brep) selectableItem1;
              if (selectedFace.ShellIndex == 0)
              {
                brep1.Rebuild();
                ccVars.selectedFace = brep1.Faces[selectedFace.Index];
                measureItem = new MeasureItem((object) ccVars.selectedFace, selectionFilterType.Face, new Point3D());
                if (ccVars.Action == actionTypeBU.profileSelectPlaneThenOperation && ccVars.selectedFace != null)
                  clsInit.appProfile.doFindPlane(ccVars.selectedFace, true, true);
                if (ccVars.Action == actionTypeBU.profileSelectPlaneThenAdd && ccVars.selectedFace != null)
                {
                  clsInit.appProfile.doFindPlane(ccVars.selectedFace, false, true);
                  continue;
                }
                continue;
              }
              ccVars.selectedFace = brep1.Inners[selectedFace.ShellIndex - 1][selectedFace.Index];
              measureItem = new MeasureItem((object) ccVars.selectedFace, selectionFilterType.Face, new Point3D());
              continue;
            case Solid _:
              measureItem = new MeasureItem((object) ((Solid) selectableItem1).Faces[selectedFace.Index], selectionFilterType.Face, new Point3D());
              continue;
            default:
              continue;
          }
        case SelectedEdge _:
          SelectedEdge selectedEdge = (SelectedEdge) addedItem;
          ISelectableItem selectableItem2 = selectedEdge.Item;
          if (selectableItem2 is Brep)
          {
            if (clsInit.appPipeBending != null)
              clsInit.appPipeBending.SelectedIndex(selectedEdge.Index);
            SelectedIndex = selectedEdge.Index;
            refEntity = (Brep) selectableItem2;
            Brep brep2 = (Brep) selectableItem2;
            objArray[num++] = (object) brep2.Edges[selectedEdge.Index];
            refEdge = brep2.Edges[selectedEdge.Index];
            Point3D overPoint = new Point3D();
            clsInit.cVector5.GetPointOnEntity(ccVars.pntActive, (object) brep2.Edges[selectedEdge.Index].Curve, ref overPoint);
            measureItem = new MeasureItem((object) brep2.Edges[selectedEdge.Index], selectionFilterType.Edge, overPoint);
            measureItem.BoxMin = buVector5.ToPoint3D(((Entity) brep2.Edges[selectedEdge.Index].Curve).BoxMin);
            measureItem.BoxMax = buVector5.ToPoint3D(((Entity) brep2.Edges[selectedEdge.Index].Curve).BoxMax);
            break;
          }
          break;
        case SelectedVertex _:
          SelectedVertex selectedVertex = (SelectedVertex) addedItem;
          ISelectableItem selectableItem3 = selectedVertex.Item;
          if (selectableItem3 is Brep)
          {
            Brep brep3 = (Brep) selectableItem3;
            objArray[num++] = (object) brep3.Vertices[selectedVertex.Index];
            measureItem = new MeasureItem((object) brep3.Vertices[selectedVertex.Index], selectionFilterType.Vertex, new Point3D());
            break;
          }
          break;
        default:
          objArray[num++] = (object) e.AddedItems[index].Item;
          measureItem = new MeasureItem((object) e.AddedItems[index].Item, selectionFilterType.Entity, new Point3D());
          break;
      }
    }
    if (ccVars.Action == actionTypeBU.drawMeasure)
      this.MeasureUpdate(measureItem);
    if (!(ccVars.Action == actionTypeBU.camContours | ccVars.Action == actionTypeBU.camPocketing) || !(refEntity != null & refEdge != null & SelectedIndex >= 0) || refEntity == null)
      return;
    List<Entity> Curves = new List<Entity>();
    List<int> EdgeIndex = new List<int>();
    clsInit.cVector5.GetEdgesOfBrep(refEntity, refEdge, SelectedIndex, ref Curves, ref EdgeIndex);
    for (int index = 0; index <= EdgeIndex.Count - 1; ++index)
      ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[0]).SetEdgeSelection(EdgeIndex[index], true);
    if (Curves.Count <= 0)
      return;
    if (ccVars.entityEdges == null)
      ccVars.entityEdges = new List<List<Entity>>();
    ccVars.entityEdges.Clear();
    List<Entity> SortedEntities = new List<Entity>();
    List<int> SortedEntitesIndex = new List<int>();
    this.GetChainEntities(((ICurve) Curves[0]).StartPoint, Curves, false, ref SortedEntities, ref SortedEntitesIndex);
    ccVars.entityEdges.Add(SortedEntities);
    SortedEntitesIndex.Clear();
  }

