  public void ManageSelection(Entity ent, Keys ModifierKeys)
  {
    if (ModifierKeys == Keys.Control)
      ent.Selected = !ent.Selected;
    else
      ent.Selected = true;
  }

  public void ManageSelection(int ent, Keys ModifierKeys, List<int> added, List<int> removed)
  {
    bool Remove = false;
    if (ModifierKeys == Keys.Control)
    {
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected = !ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected;
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected)
        added.Add(ent);
      else
        removed.Add(ent);
      Remove = true;
    }
    else
    {
      if (!ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected)
        added.Add(ent);
      else if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent] is CompositeCurve)
        added.Add(ent);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected = true;
    }
    if (clsVar.varSelection.DontSelectGroupItem)
      return;
    this.ManageGroupSelection(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent], ent, Remove, added, removed);
  }

  public void ManageGroupSelection(
    Entity entSelected,
    int RefEntIndex,
    bool Remove,
    List<int> added,
    List<int> removed)
  {
    int groupIdIndex1 = clsInit.cVector5.GetGroupIdIndex(entSelected);
    if (groupIdIndex1 < 0)
      return;
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      int groupIdIndex2 = clsInit.cVector5.GetGroupIdIndex(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]);
      if (!Remove)
      {
        if (entSelected.Selected & !ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected && index != RefEntIndex & groupIdIndex1 == groupIdIndex2 & groupIdIndex2 >= 0)
        {
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
          added.Add(index);
        }
      }
      else if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected && index != RefEntIndex & groupIdIndex1 == groupIdIndex2)
      {
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = false;
        removed.Add(index);
      }
    }
  }

  public void SelectedToSelectionAdd(List<int> Added)
  {
    for (int index1 = 0; index1 <= Added.Count - 1; ++index1)
    {
      SelectionEntity SelEntity = new SelectionEntity(Added[index1]);
      SelEntity.SelectedEntity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[Added[index1]];
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[Added[index1]].Selected = true;
      clsInit.cVector5.DrawCurveOrBlockRef(SelEntity.SelectedEntity, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref SelEntity.SelectedVertices);
      if (SelEntity.SelectedEntity is ICurve)
      {
        double t = 0.0;
        ((ICurve) SelEntity.SelectedEntity).ClosestPointTo(ccVars.pntActive, out t);
        SelEntity.pntClickEntityOver = ((ICurve) SelEntity.SelectedEntity).PointAt(t);
      }
      if (SelEntity.SelectedEntity is CompositeCurve)
      {
        double num1 = double.MaxValue;
        for (int index2 = 0; index2 <= ((CompositeCurve) SelEntity.SelectedEntity).CurveList.Count - 1; ++index2)
        {
          ICurve curve = ((CompositeCurve) SelEntity.SelectedEntity).CurveList[index2];
          double t = 0.0;
          curve.ClosestPointTo(ccVars.pntActive, out t);
          Point3D point3D = curve.PointAt(t);
          double num2 = Point3D.Distance(point3D, ccVars.pntActive);
          if (t > 0.0 & t > curve.Domain.Min & t < curve.Domain.Max && num2 < num1)
          {
            num1 = num2;
            buEntity.Copy((Entity) curve, ref SelEntity.SelectedSubEntity);
            SelEntity.SubIndex = index2;
            SelEntity.pntClickEntityOver = buVector5.ToPoint3D(point3D);
          }
        }
      }
      SelEntity.SelectedLinearPaths = new List<Entity>();
      for (int index3 = 0; index3 <= SelEntity.SelectedVertices.Count - 1; ++index3)
      {
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) SelEntity.SelectedVertices[index3]);
        SelEntity.SelectedLinearPaths.Add((Entity) linearPath);
      }
      if (SelEntity.SelectedEntity.BoxMin == (Point3D) null)
        SelEntity.SelectedEntity.Regen(0.01);
      SelEntity.pntClick = buVector5.ToPoint3D(ccVars.pntActive);
      SelEntity.BoxMin = buVector5.ToPoint3D(SelEntity.SelectedEntity.BoxMin);
      SelEntity.BoxMax = buVector5.ToPoint3D(SelEntity.SelectedEntity.BoxMax);
      SelEntity.EntitiesBoxPointList.Add(SelEntity.BoxMin);
      SelEntity.EntitiesBoxPointList.Add(SelEntity.BoxMax);
      clsInit.cVector5.SelectionAlingPoints(ref SelEntity);
      ccVars.SelectionOP.Selections.Add(SelEntity);
    }
    this.SelectionBoxSizeCalculate();
  }

  public void SelectedToSelectionRemove(List<int> Removed)
  {
    for (int index1 = 0; index1 <= Removed.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= ccVars.SelectionOP.Selections.Count - 1; ++index2)
      {
        if (ccVars.SelectionOP.Selections[index2].Index == Removed[index1])
          ccVars.SelectionOP.Selections.RemoveAt(index2);
      }
    }
  }

  public void SelectionFromEntity(
    Point3D refPoint,
    int Index,
    entitySortDirection Direction,
    ref SelectionEntity S)
  {
    S = new SelectionEntity(Index);
    S.SelectedEntity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[Index];
    clsInit.cVector5.DrawCurveOrBlockRef(S.SelectedEntity, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref S.SelectedVertices);
    clsInit.cVector5.SetSortDirection(Direction, ref S.SelectedEntity);
    if (S.SelectedEntity is CompositeCurve)
    {
      double num1 = double.MaxValue;
      for (int index = 0; index <= ((CompositeCurve) S.SelectedEntity).CurveList.Count - 1; ++index)
      {
        ICurve curve = ((CompositeCurve) S.SelectedEntity).CurveList[index];
        double t = 0.0;
        curve.ClosestPointTo(refPoint, out t);
        double num2 = Point3D.Distance(curve.PointAt(t), refPoint);
        if (t > 0.0 & t > curve.Domain.Min & t < curve.Domain.Max && num2 < num1)
        {
          num1 = num2;
          S.SelectedSubEntity = (Entity) ((Entity) curve).Clone();
        }
      }
    }
    S.SelectedLinearPaths = new List<Entity>();
    for (int index = 0; index <= S.SelectedVertices.Count - 1; ++index)
    {
      LinearPath linearPath = new LinearPath((ICollection<Point3D>) S.SelectedVertices[index]);
      S.SelectedLinearPaths.Add((Entity) linearPath);
    }
    if (S.SelectedEntity.BoxMin == (Point3D) null)
      S.SelectedEntity.Regen(0.01);
    S.pntClick = buVector5.ToPoint3D(refPoint);
    S.BoxMin = buVector5.ToPoint3D(S.SelectedEntity.BoxMin);
    S.BoxMax = buVector5.ToPoint3D(S.SelectedEntity.BoxMax);
    S.EntitiesBoxPointList.Add(S.BoxMin);
    S.EntitiesBoxPointList.Add(S.BoxMax);
  }

  public void SelectionBoxSizeCalculate()
  {
    List<Point3D> pointList = new List<Point3D>();
    for (int index = 0; index <= ccVars.SelectionOP.Selections.Count - 1; ++index)
    {
      pointList.Add(ccVars.SelectionOP.Selections[index].BoxMin);
      pointList.Add(ccVars.SelectionOP.Selections[index].BoxMax);
    }
    Utility.BoundingBox((IList<Point3D>) pointList, out ccVars.SelectionOP.SelectionBoxMin, out ccVars.SelectionOP.SelectionBoxMax);
    ccVars.SelectionOP.SelectionBoxMid = clsInit.cVector5.MiddlePointOfLine(ccVars.SelectionOP.SelectionBoxMin, ccVars.SelectionOP.SelectionBoxMax);
  }

  public void SelectionToEntities(
    ref List<Entity> selectedEntities,
    SelectionToEntitiesOptions Options)
  {
    selectedEntities.Clear();
    for (int index1 = 0; index1 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index1)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].Selected)
      {
        Entity entity1 = buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1]);
        if (entity1 is CompositeCurve)
        {
          CompositeCurve compositeCurve = entity1 as CompositeCurve;
          for (int index2 = 0; index2 <= compositeCurve.CurveList.Count - 1; ++index2)
          {
            Entity entity2 = buVector5.CopyEntities((Entity) compositeCurve.CurveList[index2]);
            if (entity2.Vertices == null)
              entity2.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
            selectedEntities.Add(entity2);
          }
        }
        else if (entity1.GetType() == typeof (Circle) & Options.CircleToArc)
        {
          Circle circle = entity1 as Circle;
          Arc arc1 = new Arc(circle.Plane, circle.Center, circle.Radius, 0.0, Math.PI);
          arc1.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
          Arc arc2 = new Arc(circle.Plane, circle.Center, circle.Radius, Math.PI, 2.0 * Math.PI);
          arc2.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
          selectedEntities.Add((Entity) arc1);
          selectedEntities.Add((Entity) arc2);
        }
        else
        {
          if (entity1.Vertices == null)
            entity1.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
          selectedEntities.Add(entity1);
        }
      }
    }
  }

  public void SelectionToEntities(ref List<Entity> selectedEntities, SelectionOption Option)
  {
    selectedEntities.Clear();
    for (int index1 = 0; index1 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index1)
    {
      bool flag1 = false;
      bool flag2 = false;
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].Selected)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1] is devDept.Eyeshot.Entities.Point & Option.Point)
          flag1 = true;
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1] is Line & Option.Line && ((ICurve) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1]).Length() > 0.0)
