  public void SelectAllClosedAreaByPosition(Point3D refPoint)
  {
    try
    {
      List<Entity> entityList = new List<Entity>();
      buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref entityList);
      List<Entity> SortedEntities = new List<Entity>();
      List<int> intList = new List<int>();
      SelectionOperation selectionOperation = new SelectionOperation();
      SortSettings Settings = new SortSettings();
      SortResult Result = new SortResult();
      Settings.Option.IntersectionRules = SortingIntersectionRulesType.ClosestLength;
      clsInit.cVector5.GetClosedEntitiesByRefPointUsingCrossLines(refPoint, ref entityList, Settings, ref SortedEntities, ref Result);
      for (int index = 0; index <= SortedEntities.Count - 1; ++index)
      {
        CustomData entityData = (CustomData) SortedEntities[index].EntityData;
        if (entityData.OriginalEntityIndex >= 0 & entityData.OriginalEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[entityData.OriginalEntityIndex].Selected = true;
      }
      clsInit.appCommand.undoBuffer();
      for (int index = 0; index <= SortedEntities.Count - 1; ++index)
      {
        ccVars.UndoDont = true;
        SortedEntities[index].ColorMethod = colorMethodType.byEntity;
        SortedEntities[index].Color = Color.Lime;
        SortedEntities[index].LineWeightMethod = colorMethodType.byEntity;
        SortedEntities[index].LineWeight = 3f;
      }
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void SelectAll()
