  public void SelectionAnalyzeAfterSelected(Keys ModifierKeys)
  {
    List<int> Added = new List<int>();
    if (!(clsVar.varSelection.SelectInternalEntitiesWhenClick | ModifierKeys == Keys.Shift))
      return;
    for (int index1 = 0; index1 <= ccVars.SelectionOP.Selections.Count - 1; ++index1)
    {
      bool flag = false;
      List<Point3D> Points = new List<Point3D>();
      clsInit.cVector5.EntitiesToPointsWithCamDirection(ccVars.SelectionOP.Selections[index1].SelectedLinearPaths, 0.05, ref Points);
      if (Points.Count >= 2 && buCompare5.EQ(Points[0], Points[Points.Count - 1]))
        flag = true;
      if (flag)
      {
        for (int index2 = 0; index2 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index2)
        {
          Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2];
          if (!ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2].Selected & (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2] is ICurve | ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2] is Text))
          {
            if (entity.Vertices == null)
              entity.Regen(0.05);
            if (entity.Vertices.Length <= 10)
            {
              for (int index3 = 0; index3 <= entity.Vertices.Length - 1; ++index3)
              {
                if (clsInit.cVector5.IsPointInsidePolygon(Points, entity.Vertices[index3]))
                {
                  Added.Add(index2);
                  index3 = entity.Vertices.Length;
                }
              }
            }
            else
            {
              int num = entity.Vertices.Length / 10;
              for (int index4 = 0; index4 <= entity.Vertices.Length - 1; index4 += num)
              {
                if (clsInit.cVector5.IsPointInsidePolygon(Points, entity.Vertices[index4]))
                {
                  Added.Add(index2);
                  index4 = entity.Vertices.Length;
                }
              }
            }
          }
        }
      }
    }
    if (Added.Count > 0)
      this.SelectedToSelectionAdd(Added);
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void GetChainEntities(Point3D RefPoint, List<Entity> refEntities, bool AddToSelection)
  {
    List<Entity> SortedEntities = new List<Entity>();
    List<int> SortedEntitesIndex = new List<int>();
    this.GetChainEntities(RefPoint, refEntities, AddToSelection, ref SortedEntities, ref SortedEntitesIndex);
    SortedEntities.Clear();
    SortedEntitesIndex.Clear();
  }

  public void GetChainEntities(
    Point3D RefPoint,
    List<Entity> refEntities,
    bool AddToSelection,
    ref List<Entity> SortedEntities,
    ref List<int> SortedEntitesIndex)
  {
    try
    {
      int Sequence = -1;
      Point3D pntFound = new Point3D();
      StartEndType FoundLocation = StartEndType.Start;
      SortSettings Settings = new SortSettings();
      clsInit.cVector5.MostClosestPoint(RefPoint, refEntities, Settings, ref Sequence, ref pntFound, ref FoundLocation);
      SortedEntitesIndex.Clear();
      List<Entity> copiedEnt = new List<Entity>();
      buVector5.CopyEntities(refEntities, ref copiedEnt);
      bool flag = false;
      if (Sequence < 0)
        return;
      Point3D point3D = new Point3D();
      for (int index1 = 0; index1 <= copiedEnt.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= refEntities.Count - 1; ++index2)
        {
          if (refEntities[index2] is ICurve & refEntities[index2].Selectable)
          {
            ICurve refEntity1 = (ICurve) refEntities[index2];
            if (buCompare5.EQ(pntFound, refEntity1.StartPoint, buSystem.resolutionSorting))
            {
              if (!clsInit.cVector.IsIndexNumberAvailableAtList(SortedEntitesIndex, index2))
              {
                SortedEntitesIndex.Add(index2);
                Entity refEntity2 = buVector5.CopyEntities(refEntities[index2]);
                clsInit.cVector5.SetSortDirection(entitySortDirection.Normal, ref refEntity2);
                SortedEntities.Add(refEntity2);
                if (AddToSelection)
                {
                  SelectionEntity S = (SelectionEntity) null;
                  this.SelectionFromEntity(RefPoint, index2, entitySortDirection.Normal, ref S);
                  ccVars.SelectionOP.Selections.Add(S);
                }
                pntFound = buVector5.ToPoint3D(refEntity1.EndPoint);
                refEntities[index2].Selected = true;
                index2 = refEntities.Count;
                flag = true;
              }
            }
            else if (buCompare5.EQ(pntFound, refEntity1.EndPoint, buSystem.resolutionSorting))
            {
              if (!clsInit.cVector.IsIndexNumberAvailableAtList(SortedEntitesIndex, index2))
              {
                SortedEntitesIndex.Add(index2);
                Entity refEntity3 = buVector5.CopyEntities(refEntities[index2]);
                clsInit.cVector5.SetSortDirection(entitySortDirection.Reverse, ref refEntity3);
                SortedEntities.Add(refEntity3);
                if (AddToSelection)
                {
                  SelectionEntity S = (SelectionEntity) null;
                  this.SelectionFromEntity(RefPoint, index2, entitySortDirection.Normal, ref S);
                  ccVars.SelectionOP.Selections.Add(S);
                }
                pntFound = buVector5.ToPoint3D(refEntity1.StartPoint);
                refEntities[index2].Selected = true;
                index2 = refEntities.Count;
                flag = true;
              }
            }
            else if (refEntity1 is CompositeCurve)
            {
              CompositeCurve compositeCurve = refEntity1 as CompositeCurve;
              for (int index3 = 0; index3 <= compositeCurve.CurveList.Count - 1; ++index3)
              {
                ICurve curve = compositeCurve.CurveList[index3];
                if (buCompare5.EQ(pntFound, curve.StartPoint, buSystem.resolutionSorting))
                {
                  if (!clsInit.cVector.IsIndexNumberAvailableAtList(SortedEntitesIndex, index2))
                  {
                    SortedEntitesIndex.Add(index2);
                    Entity refEntity4 = buVector5.CopyEntities(refEntities[index2]);
                    clsInit.cVector5.SetSortDirection(entitySortDirection.Normal, ref refEntity4);
                    SortedEntities.Add(refEntity4);
                    if (AddToSelection)
                    {
                      SelectionEntity S = (SelectionEntity) null;
                      this.SelectionFromEntity(RefPoint, index2, entitySortDirection.Normal, ref S);
                      ccVars.SelectionOP.Selections.Add(S);
                    }
                    pntFound = buVector5.ToPoint3D(curve.EndPoint);
                    refEntities[index2].Selected = true;
                    index2 = refEntities.Count;
                    flag = true;
                  }
                }
                else if (buCompare5.EQ(pntFound, curve.EndPoint, buSystem.resolutionSorting) && !clsInit.cVector.IsIndexNumberAvailableAtList(SortedEntitesIndex, index2))
                {
                  SortedEntitesIndex.Add(index2);
                  Entity refEntity5 = buVector5.CopyEntities(refEntities[index2]);
                  clsInit.cVector5.SetSortDirection(entitySortDirection.Reverse, ref refEntity5);
                  SortedEntities.Add(refEntity5);
                  if (AddToSelection)
                  {
                    SelectionEntity S = (SelectionEntity) null;
                    this.SelectionFromEntity(RefPoint, index2, entitySortDirection.Normal, ref S);
                    ccVars.SelectionOP.Selections.Add(S);
                  }
                  pntFound = buVector5.ToPoint3D(curve.StartPoint);
                  refEntities[index2].Selected = true;
                  index2 = refEntities.Count;
                  flag = true;
                }
              }
            }
          }
        }
      }
      if (!flag || !AddToSelection)
        return;
      ccVars.SelectionOP.ClickList.Add(buVector5.ToPoint3D(RefPoint));
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void MeasureCommands(object Data)
  {
    if (Data == null)
      return;
    if (Data.ToString() == "face")
      this.cmdSelectDynamicFace();
    if (Data.ToString() == "edge")
      this.cmdSelectDynamicEdge();
    if (Data.ToString() == "entity")
      this.cmdSelectDynamicEntity();
    if (Data.ToString() == "vertex")
      this.cmdSelectDynamicVertex();
    if (Data.ToString() == "point")
      this.cmdSelectDynamicPoint();
    if (Data.ToString() == "min")
    {
      clsVar.varSelection.DynamicSelectionDistanceType = MinMaxType.Min;
      if (ccVars.LastMeasured >= 0)
        this.MeasureShow(ccVars.LastMeasured);
    }
    if (Data.ToString() == "max")
    {
      clsVar.varSelection.DynamicSelectionDistanceType = MinMaxType.Max;
      if (ccVars.LastMeasured >= 0)
        this.MeasureShow(ccVars.LastMeasured);
    }
    if (Data.ToString() == "xenable")
    {
      clsVar.varInterface.DynamicSelectionX = true;
      if (ccVars.LastMeasured >= 0)
        this.MeasureShow(ccVars.LastMeasured);
    }
    if (Data.ToString() == "xdisable")
    {
      clsVar.varInterface.DynamicSelectionX = false;
      if (ccVars.LastMeasured >= 0)
        this.MeasureShow(ccVars.LastMeasured);
    }
    if (Data.ToString() == "yenable")
    {
      clsVar.varInterface.DynamicSelectionY = true;
      if (ccVars.LastMeasured >= 0)
        this.MeasureShow(ccVars.LastMeasured);
    }
    if (Data.ToString() == "ydisable")
    {
      clsVar.varInterface.DynamicSelectionY = false;
      if (ccVars.LastMeasured >= 0)
        this.MeasureShow(ccVars.LastMeasured);
    }
    if (Data.ToString() == "zenable")
    {
      clsVar.varInterface.DynamicSelectionZ = true;
      if (ccVars.LastMeasured >= 0)
        this.MeasureShow(ccVars.LastMeasured);
    }
    if (Data.ToString() == "zdisable")
    {
      clsVar.varInterface.DynamicSelectionZ = false;
      if (ccVars.LastMeasured >= 0)
        this.MeasureShow(ccVars.LastMeasured);
    }
    if (Data.ToString() == "clearlast")
    {
      ccVars.MeasureObjects.Clear();
      clsItem.FrmMeasure.lbl_selected.Text = "";
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is Brep)
        {
          ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearEdgesSelection((Stack<BlockReference>) null);
          ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearFacesSelection((Stack<BlockReference>) null);
          ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearVerticesSelection((Stack<BlockReference>) null);
        }
      }
    }
    if (Data.ToString() == "clearall" && clsItem.FrmMeasure != null)
    {
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is Brep)
        {
          ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearEdgesSelection((Stack<BlockReference>) null);
          ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearFacesSelection((Stack<BlockReference>) null);
          ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearVerticesSelection((Stack<BlockReference>) null);
        }
      }
      clsItem.FrmMeasure.tree_item.Nodes.Clear();
      ccVars.SelectedMeasureObjects.Clear();
      ccVars.pntDrawDynamicMeasure.Clear();
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    }
    if (Data.ToString() == "clear" && clsItem.FrmMeasure != null)
    {
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is Brep)
        {
          ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearEdgesSelection((Stack<BlockReference>) null);
          ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearFacesSelection((Stack<BlockReference>) null);
          ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearVerticesSelection((Stack<BlockReference>) null);
        }
      }
      clsItem.FrmMeasure.txt_explanation.Text = "";
      ccVars.pntDrawDynamicMeasure.Clear();
      if (ccVars.LastMeasured >= 0 & ccVars.LastMeasured <= ccVars.SelectedMeasureObjects.Count - 1)
      {
        ccVars.SelectedMeasureObjects.RemoveAt(ccVars.LastMeasured);
        this.MeasureFill();
        if (ccVars.SelectedMeasureObjects.Count > 0)
        {
          if (ccVars.LastMeasured > ccVars.SelectedMeasureObjects.Count - 1)
            ccVars.LastMeasured = 0;
          this.MeasureShow(ccVars.LastMeasured);
        }
        else
          ccVars.LastMeasured = -1;
      }
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    }
    // ISSUE: reference to a compiler-generated field
    if (this.formUpdate_0 == null)
      return;
    // ISSUE: reference to a compiler-generated field
    this.formUpdate_0(false, true, false);
  }

  public void MeasureUpdate(MeasureItem item)
  {
    try
    {
      if (item == null)
        return;
      string str1 = "";
      if (item.Type == selectionFilterType.Face)
      {
        str1 = $"Face{ccVars.MeasureObjects.Count.ToString()}- ";
