            Line curve = (Line) edge.Curve;
            str1 = $"{$"{$"{$"{str1} buLine - Length: {curve.Length().ToString("f3")}"} - ( dX: {(curve.BoxMax.X - curve.BoxMin.X).ToString("f3")}"} , dY: {(curve.BoxMax.Y - curve.BoxMin.Y).ToString("f3")}"} , dZ: {(curve.BoxMax.Z - curve.BoxMin.Z).ToString("f3")} )";
          }
