          {
            Curve curve = (Curve) edge.Curve;
            curve.Regen(0.01);
            str1 = $"{$"{$"{$"{str1}Curve - Length : {Math.Round(curve.Length(), 3).ToString("f3")}"} - ( dX: {(curve.BoxMax.X - curve.BoxMin.X).ToString("f3")}"} , dY: {(curve.BoxMax.Y - curve.BoxMin.Y).ToString("f3")}"} , dZ: {(curve.BoxMax.Z - curve.BoxMin.Z).ToString("f3")} )";
          }
          if (edge.Curve is LinearPath)
          {
            LinearPath curve = (LinearPath) edge.Curve;
            string str2 = str1;
            double num = Math.Round(curve.Length(), 3);
            string str3 = num.ToString("f3");
            string str4 = $"{str2}LinearPath - Length : {str3}";
            num = curve.BoxMax.X - curve.BoxMin.X;
            string str5 = num.ToString("f3");
            string str6 = $"{str4} - ( dX: {str5}";
            num = curve.BoxMax.Y - curve.BoxMin.Y;
            string str7 = num.ToString("f3");
            string str8 = $"{str6} , dY: {str7}";
            num = curve.BoxMax.Z - curve.BoxMin.Z;
            string str9 = num.ToString("f3");
            str1 = $"{str8} , dZ: {str9} )";
          }
        }
      }
      else if (item.Type == selectionFilterType.Entity)
      {
        str1 += " ";
        Entity entity = (Entity) item.Object;
        if (entity is devDept.Eyeshot.Entities.Point)
        {
          devDept.Eyeshot.Entities.Point point = (devDept.Eyeshot.Entities.Point) entity;
          str1 = $"{$"{$"{str1 + " Point "} - ( X: {point.StartPoint.X.ToString("f3")}"} , Y: {point.StartPoint.Y.ToString("f3")}"} , Z: {point.StartPoint.Z.ToString("f3")} )";
        }
        if (entity is Line)
        {
          Line line = (Line) entity;
          str1 = $"{$"{$"{$"{str1} Line - Length: {line.Length().ToString("f3")}"} - ( dX: {(line.BoxMax.X - line.BoxMin.X).ToString("f3")}"} , dY: {(line.BoxMax.Y - line.BoxMin.Y).ToString("f3")}"} , dZ: {(line.BoxMax.Z - line.BoxMin.Z).ToString("f3")} )";
        }
        if (entity is Arc)
        {
          Arc arc = (Arc) entity;
          arc.Regen(0.01);
          str1 = $"{$"{$"{$"{str1}Arc - Radius : {Math.Round(arc.Radius, 3).ToString("f3")}"} - ( dX: {(arc.BoxMax.X - arc.BoxMin.X).ToString("f3")}"} , dY: {(arc.BoxMax.Y - arc.BoxMin.Y).ToString("f3")}"} , dZ: {(arc.BoxMax.Z - arc.BoxMin.Z).ToString("f3")} )";
        }
        if (entity is Curve)
        {
          Curve curve = (Curve) entity;
          curve.Regen(0.01);
          str1 = $"{$"{$"{$"{str1}Curve - Length : {Math.Round(curve.Length(), 3).ToString("f3")}"} - ( dX: {(curve.BoxMax.X - curve.BoxMin.X).ToString("f3")}"} , dY: {(curve.BoxMax.Y - curve.BoxMin.Y).ToString("f3")}"} , dZ: {(curve.BoxMax.Z - curve.BoxMin.Z).ToString("f3")} )";
        }
        if (entity is LinearPath)
        {
          LinearPath linearPath = (LinearPath) entity;
          str1 = $"{$"{$"{$"{str1}LinearPath - Length : {Math.Round(linearPath.Length(), 3).ToString("f3")}"} - ( dX: {(linearPath.BoxMax.X - linearPath.BoxMin.X).ToString("f3")}"} , dY: {(linearPath.BoxMax.Y - linearPath.BoxMin.Y).ToString("f3")}"} , dZ: {(linearPath.BoxMax.Z - linearPath.BoxMin.Z).ToString("f3")} )";
        }
      }
      else if (item.Type == selectionFilterType.Vertex)
      {
        str1 = $"Vertex{ccVars.MeasureObjects.Count.ToString()}- ";
        if (item.Object is Brep.Vertex)
          str1 = $"{$"{$"{str1} - Position ( X: {((Point2D) item.Object).X.ToString("f3")}"} , Y: {((Point2D) item.Object).Y.ToString("f3")}"} , Z: {((Point3D) item.Object).Z.ToString("f3")} )";
      }
      item.Explanation = str1;
      ccVars.MeasureObjects.Add(item);
      if (ccVars.MeasureObjects.Count < 2)
        clsItem.FrmMeasure.lbl_selected.Text = str1;
      else
        this.MeasureAdd();
    }
    catch (Exception ex)
    {
      throw;
    }
  }

  public void MeasureAdd()
  {
    int count = ccVars.SelectedMeasureObjects.Count;
    TreeNodeSettings node = new TreeNodeSettings("Group" + count.ToString());
    node.ClassIndex = count;
    node.Nodes.Add((TreeNode) new TreeNodeSettings(ccVars.MeasureObjects[0].Explanation)
    {
      ClassIndex = count
    });
    node.Nodes.Add((TreeNode) new TreeNodeSettings(ccVars.MeasureObjects[1].Explanation)
    {
      ClassIndex = count
    });
    clsItem.FrmMeasure.tree_item.Nodes.Add((TreeNode) node);
    clsItem.FrmMeasure.tree_item.ExpandAll();
    clsItem.FrmMeasure.lbl_selected.Text = "";
    ccVars.SelectedMeasureObjects.Add(ccVars.MeasureObjects);
    ccVars.MeasureObjects = new List<MeasureItem>();
    this.MeasureShow(ccVars.SelectedMeasureObjects.Count - 1);
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is Brep)
      {
        ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearEdgesSelection((Stack<BlockReference>) null);
        ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearFacesSelection((Stack<BlockReference>) null);
        ((Brep) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]).ClearVerticesSelection((Stack<BlockReference>) null);
      }
    }
  }

  public void MeasureFill()
  {
    clsItem.FrmMeasure.tree_item.Nodes.Clear();
    for (int index = 0; index <= ccVars.SelectedMeasureObjects.Count - 1; ++index)
    {
      int num = index;
      TreeNodeSettings node = new TreeNodeSettings("Group" + num.ToString());
      node.ClassIndex = num;
      node.Nodes.Add((TreeNode) new TreeNodeSettings(ccVars.SelectedMeasureObjects[index][0].Explanation)
      {
        ClassIndex = num
      });
      node.Nodes.Add((TreeNode) new TreeNodeSettings(ccVars.SelectedMeasureObjects[index][1].Explanation)
      {
        ClassIndex = num
      });
      clsItem.FrmMeasure.tree_item.Nodes.Add((TreeNode) node);
    }
    clsItem.FrmMeasure.tree_item.ExpandAll();
  }

  public void MeasureShow(int MeasureIndex)
  {
    ccVars.LastMeasured = MeasureIndex;
    string str = "";
    DistanceData Distance = new DistanceData();
    Point3D FirstFoundPoints = new Point3D();
    Point3D SecondFoundPoints = new Point3D();
    Entity FirstEntity = (Entity) null;
    Entity SecondEntity = (Entity) null;
    if (ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Brep.Edge)
      FirstEntity = (Entity) ((Brep.Edge) ccVars.SelectedMeasureObjects[MeasureIndex][0].Object).Curve;
    else if (ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Brep.Face)
    {
      Brep.Face face = (Brep.Face) ccVars.SelectedMeasureObjects[MeasureIndex][0].Object;
      if (face.Parametric == null || face.Parametric.Length == 0)
        ;
    }
    else if (ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Brep.Vertex)
    {
      Point3D point3D = (Point3D) ccVars.SelectedMeasureObjects[MeasureIndex][0].Object;
      FirstEntity = (Entity) new devDept.Eyeshot.Entities.Point(point3D.X, point3D.Y, point3D.Z);
    }
    else if (ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Entity)
      FirstEntity = (Entity) ((Entity) ccVars.SelectedMeasureObjects[MeasureIndex][0].Object).Clone();
    if (ccVars.SelectedMeasureObjects[MeasureIndex][1].Object is Brep.Edge)
      SecondEntity = (Entity) ((Brep.Edge) ccVars.SelectedMeasureObjects[MeasureIndex][1].Object).Curve;
    else if (ccVars.SelectedMeasureObjects[MeasureIndex][1].Object is Brep.Face)
    {
      Brep.Face face = (Brep.Face) ccVars.SelectedMeasureObjects[MeasureIndex][1].Object;
      if (face.Parametric == null || face.Parametric.Length == 0)
        ;
    }
    else if (ccVars.SelectedMeasureObjects[MeasureIndex][1].Object is Brep.Vertex)
    {
      Point3D point3D = (Point3D) ccVars.SelectedMeasureObjects[MeasureIndex][1].Object;
      SecondEntity = (Entity) new devDept.Eyeshot.Entities.Point(point3D.X, point3D.Y, point3D.Z);
    }
    else if (ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Entity)
      SecondEntity = (Entity) ((Entity) ccVars.SelectedMeasureObjects[MeasureIndex][1].Object).Clone();
    if (FirstEntity != null & SecondEntity != null)
    {
      if (clsVar.varSelection.DynamicSelectionDistanceType == MinMaxType.Min)
        clsInit.cVector5.GetClosestPointsOfTwoEntity(FirstEntity, SecondEntity, ref FirstFoundPoints, ref SecondFoundPoints);
      if (clsVar.varSelection.DynamicSelectionDistanceType == MinMaxType.Max)
        clsInit.cVector5.GetLongestPointsOfTwoEntity(FirstEntity, SecondEntity, ref FirstFoundPoints, ref SecondFoundPoints);
      clsInit.cVector5.GetInformationBetweenTwoPoints(FirstFoundPoints, SecondFoundPoints, ref Distance);
      str = $"{$"{$"{$" L =  {Distance.Length.ToString("f3")}{Environment.NewLine}"} dx =  {Distance.dX.ToString("f3")}{Environment.NewLine}"} dy =  {Distance.dY.ToString("f3")}{Environment.NewLine}"} dz =  {Distance.dZ.ToString("f3")}";
      ccVars.pntDrawDynamicMeasure.Clear();
      MeasureData measureData1 = new MeasureData();
      measureData1.Points.Add(FirstFoundPoints);
      measureData1.Points.Add(SecondFoundPoints);
      measureData1.Text = "L = ";
      measureData1.Length = Math.Round(Point3D.Distance(FirstFoundPoints, SecondFoundPoints), 3);
      measureData1.PntText = Point3D.MidPoint(FirstFoundPoints, SecondFoundPoints);
      double length = measureData1.Length;
      ccVars.pntDrawDynamicMeasure.Add(measureData1);
      MeasureData measureData2 = new MeasureData();
      Point3D a1 = new Point3D(FirstFoundPoints.X, FirstFoundPoints.Y, FirstFoundPoints.Z);
      Point3D b1 = new Point3D(SecondFoundPoints.X, FirstFoundPoints.Y, FirstFoundPoints.Z);
      measureData2.Points.Add(a1);
      measureData2.Points.Add(b1);
      measureData2.Length = Math.Round(Point3D.Distance(a1, b1), 3);
      measureData2.PntText = Point3D.MidPoint(a1, b1);
      measureData2.Text = "dX = ";
      if (buCompare.EQ(length, measureData2.Length, 0.001))
        measureData2.Length = 0.0;
      if (!clsVar.varInterface.DynamicSelectionX)
      {
        measureData2.Length = 0.0;
        measureData2.Points.Clear();
      }
      if (buCompare.EQ(measureData2.Length, 0.0, 0.001))
        measureData2.Text = "";
      ccVars.pntDrawDynamicMeasure.Add(measureData2);
      MeasureData measureData3 = new MeasureData();
      Point3D a2 = new Point3D(FirstFoundPoints.X, FirstFoundPoints.Y, FirstFoundPoints.Z);
      Point3D b2 = new Point3D(FirstFoundPoints.X, SecondFoundPoints.Y, FirstFoundPoints.Z);
      measureData3.Points.Add(a2);
      measureData3.Points.Add(b2);
      measureData3.Length = Math.Round(Point3D.Distance(a2, b2), 3);
      measureData3.PntText = Point3D.MidPoint(a2, b2);
      measureData3.Text = "dY = ";
      if (buCompare.EQ(length, measureData3.Length, 0.001))
        measureData3.Length = 0.0;
      if (!clsVar.varInterface.DynamicSelectionY)
      {
        measureData3.Length = 0.0;
        measureData3.Points.Clear();
      }
      if (buCompare.EQ(measureData3.Length, 0.0, 0.001))
        measureData3.Text = "";
      ccVars.pntDrawDynamicMeasure.Add(measureData3);
      MeasureData measureData4 = new MeasureData();
      Point3D a3 = new Point3D(FirstFoundPoints.X, FirstFoundPoints.Y, FirstFoundPoints.Z);
      Point3D b3 = new Point3D(FirstFoundPoints.X, FirstFoundPoints.Y, SecondFoundPoints.Z);
      measureData4.Points.Add(a3);
      measureData4.Points.Add(b3);
      measureData4.Length = Point3D.Distance(a3, b3);
      measureData4.PntText = Point3D.MidPoint(a3, b3);
      measureData4.Text = "dZ = ";
      if (buCompare.EQ(length, measureData4.Length, 0.001))
        measureData4.Length = 0.0;
      if (!clsVar.varInterface.DynamicSelectionZ)
      {
        measureData4.Length = 0.0;
        measureData4.Points.Clear();
      }
      if (buCompare.EQ(measureData4.Length, 0.0, 0.001))
        measureData4.Text = "";
      ccVars.pntDrawDynamicMeasure.Add(measureData4);
    }
    clsItem.FrmMeasure.txt_explanation.Text = str;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void Measure_AfterSelect(object sender, TreeViewEventArgs e)
  {
    TreeNodeSettings selectedNode = (TreeNodeSettings) ((TreeView) sender).SelectedNode;
    if (selectedNode.ClassIndex < 0)
      return;
    int classIndex = selectedNode.ClassIndex;
    if (classIndex > ccVars.SelectedMeasureObjects.Count - 1)
      return;
    this.MeasureShow(classIndex);
  }

  public void OsnapCalculationByThread()
  {
    clsVar.threadCalculations = new Thread(new ThreadStart(clsInit.appCommand.ThreadCalculationLoop));
    ThreadCommands.OsnapCalculationAll = true;
    clsVar.threadCalculations.Start();
  }

  public void OsnapEnableDisableByLayerAndEntityVisiblityThread()
  {
    if (ThreadCommands.OsnapEnableDisableByLayerVisible)
      return;
    clsVar.threadCalculations = new Thread(new ThreadStart(clsInit.appCommand.ThreadCalculationLoop));
    ThreadCommands.OsnapEnableDisableByLayerVisible = true;
    clsVar.threadCalculations.Start();
  }

  public void OsnapEnableDisableByLayerAndEntityVisiblity()
  {
    try
    {
      if (ccVars.Pages.Count <= 0)
        return;
      for (int index1 = ccVars.Pages[ccVars.PageIndex].OsnapPoints.Count - 1; index1 >= 0; --index1)
      {
        bool flag1 = true;
        bool flag2 = true;
        for (int index2 = 0; index2 <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; ++index2)
        {
          if (ccVars.Pages[ccVars.PageIndex].OsnapPoints[index1].LayerName == ccVars.Pages[ccVars.PageIndex].Layers[index2].Name)
          {
            flag1 = ccVars.Pages[ccVars.PageIndex].Layers[index2].Enable;
            index2 = ccVars.Pages[ccVars.PageIndex].Layers.Count;
          }
        }
        for (int index3 = 0; index3 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index3)
        {
          if (index3 < ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
          {
            string entityName = clsInit.cVector5.GetEntityName(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index3]);
            if (ccVars.Pages[ccVars.PageIndex].OsnapPoints[index1].EntName == entityName & entityName.Length > 0)
              flag2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index3].Visible;
          }
        }
        ccVars.Pages[ccVars.PageIndex].OsnapPoints[index1].Enable = flag1 & flag2;
      }
    }
    catch (Exception ex)
    {
    }
  }

  public void OsnapDelete()
  {
    for (int index = 0; index <= clsVar.OsnapDeleteList.Count - 1; ++index)
      this.OsnapDeleteByEntityName(clsVar.OsnapDeleteList[index]);
    clsVar.OsnapDeleteList.Clear();
  }

  public void OsnapCalculationAll()
  {
    try
    {
      if (ccVars.Pages.Count <= 0)
        return;
      ccVars.Pages[ccVars.PageIndex].OsnapPoints.Clear();
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities == null)
        return;
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
        clsInit.appCommand.OsnapCalculation(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index], index + 1);
    }
    catch (Exception ex)
    {
    }
  }

  public void OsnapCalculation(Entity refEnt) => this.OsnapCalculation(refEnt, 0);

  public void OsnapCalculation(Entity refEnt, int ListStartIndex)
  {
    try
    {
      if (ccVars.OsnapDont || !clsVar.varProgram.OsnapCalculation)
        return;
      switch (refEnt)
      {
        case devDept.Eyeshot.Entities.Point _:
          devDept.Eyeshot.Entities.Point refEntity = (devDept.Eyeshot.Entities.Point) refEnt;
          if (!clsVar.varMouse.Osnap.OsnapPoint)
            break;
          Point3D vertex = refEnt.Vertices[0];
          if (clsInit.cVector5.isOsnapPointAvailable(vertex, ccVars.Pages[ccVars.PageIndex].OsnapPoints))
            break;
          ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(vertex, osnapType.Point, clsInit.cVector5.GetEntityCustomData((Entity) refEntity).EntityName, refEntity.LayerName, ""));
          break;
        case Line _:
          Line line = (Line) refEnt;
          if (clsVar.varMouse.Osnap.OsnapPoint)
          {
            if (!clsInit.cVector5.isOsnapPointAvailable(line.StartPoint, ccVars.Pages[ccVars.PageIndex].OsnapPoints))
              ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(line.StartPoint, osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, line.LayerName, ""));
            if (!clsInit.cVector5.isOsnapPointAvailable(line.EndPoint, ccVars.Pages[ccVars.PageIndex].OsnapPoints))
              ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(line.EndPoint, osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, line.LayerName, ""));
          }
          if (clsVar.varMouse.Osnap.OsnapMiddle && !clsInit.cVector5.isOsnapPointAvailable(line.MidPoint, ccVars.Pages[ccVars.PageIndex].OsnapPoints))
            ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(line.MidPoint, osnapType.Middle, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, line.LayerName, ""));
          if (!clsVar.varMouse.Osnap.OsnapIntersection)
            break;
          clsInit.cVector5.IntersectionOfEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList<Entity>(), refEnt, -1, ListStartIndex, ref ccVars.Pages[ccVars.PageIndex].OsnapPoints);
          break;
        case LinearPath _:
          LinearPath linearPath = (LinearPath) refEnt;
          if (clsVar.varMouse.Osnap.OsnapPoint)
          {
            for (int index = 0; index <= linearPath.Vertices.Length - 1; ++index)
              ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(linearPath.Vertices[index], osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, linearPath.LayerName, ""));
          }
          if (clsVar.varMouse.Osnap.OsnapMiddle)
          {
            for (int index = 1; index <= linearPath.Vertices.Length - 1; ++index)
              ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(Point3D.MidPoint(linearPath.Vertices[index - 1], linearPath.Vertices[index]), osnapType.Middle, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, linearPath.LayerName, ""));
          }
          if (!clsVar.varMouse.Osnap.OsnapIntersection)
            break;
          clsInit.cVector5.IntersectionOfEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList<Entity>(), refEnt, -1, ListStartIndex, ref ccVars.Pages[ccVars.PageIndex].OsnapPoints);
          break;
        case CompositeCurve _:
          CompositeCurve compositeCurve = (CompositeCurve) refEnt;
          if (clsVar.varMouse.Osnap.OsnapPoint)
          {
            if (compositeCurve.CurveList.Count > 0)
            {
              for (int index = 0; index <= compositeCurve.CurveList.Count - 1; ++index)
              {
                if (index == 0)
                {
                  ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(compositeCurve.CurveList[index].StartPoint, osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, compositeCurve.LayerName, ""));
                  ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(compositeCurve.CurveList[index].EndPoint, osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, compositeCurve.LayerName, ""));
                }
                else
                  ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(compositeCurve.CurveList[index].EndPoint, osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, compositeCurve.LayerName, ""));
              }
            }
            foreach (ICurve curve in compositeCurve.CurveList)
              ;
          }
          if (clsVar.varMouse.Osnap.OsnapMiddle)
          {
            foreach (ICurve curve in compositeCurve.CurveList)
            {
              switch (curve)
              {
                case Arc _:
                  ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(((Arc) curve).MidPoint, osnapType.Middle, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, compositeCurve.LayerName, ""));
                  continue;
                case Line _:
                  ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(((Line) curve).MidPoint, osnapType.Middle, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, compositeCurve.LayerName, ""));
                  continue;
                case LinearPath _:
                  for (int index = 1; index <= ((Entity) curve).Vertices.Length - 1; ++index)
                    ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(Point3D.MidPoint(((Entity) curve).Vertices[index - 1], ((Entity) curve).Vertices[index]), osnapType.Middle, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, compositeCurve.LayerName, ""));
                  continue;
                default:
                  ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(curve.PointAt(0.5), osnapType.Middle, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, compositeCurve.LayerName, ""));
                  continue;
              }
            }
          }
          if (clsVar.varMouse.Osnap.OsnapCenter)
          {
            foreach (ICurve curve in compositeCurve.CurveList)
