            ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(point3D7.X, point3D7.Y, surface.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
          }
          if (!clsVar.varMouse.Osnap.OsnapPoint)
            break;
          if (surface.Vertices == null)
            surface.Regen(0.01);
          for (int index = 0; index <= surface.Vertices.Length - 1; ++index)
            ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(surface.Vertices[index], osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
          break;
      }
    }
    catch (Exception ex)
    {
    }
  }

  public void OsnapDeleteByEntityName(string EntName)
  {
    for (int index = ccVars.Pages[ccVars.PageIndex].OsnapPoints.Count - 1; index >= 0; --index)
    {
      if (ccVars.Pages[ccVars.PageIndex].OsnapPoints[index].EntName == EntName)
      {
        ccVars.Pages[ccVars.PageIndex].OsnapPoints.RemoveAt(index);
        index = 0;
      }
      else if ((index > ccVars.Pages[ccVars.PageIndex].OsnapPoints.Count - 1 ? 0 : (ccVars.Pages[ccVars.PageIndex].OsnapPoints[index].OtherEntName == EntName ? 1 : 0)) != 0)
      {
        ccVars.Pages[ccVars.PageIndex].OsnapPoints.RemoveAt(index);
        index = 0;
      }
    }
  }

  public void CoordinateCalculation(Point3D refPoint)
  {
    if (refPoint == (Point3D) null)
      return;
    ccVars.OsnapCatchPoint.Found = false;
    ccVars.OsnapCatchPoint.OrthoFound = false;
    ccVars.OsnapCatchPoint.OverFound = false;
    ccVars.OsnapCatchPoint.SnapFound = false;
    ccVars.OsnapCatchPoint.TrackFound = false;
    ccVars.OsnapCatchPoint.OsnapFound = false;
    if (clsVar.varMouse.Osnap.Snap)
    {
      ccVars.OsnapCatchPoint.Point = buConversion5.Pnt3DToPoint3D(clsInit.cVector.SnapFunction(buConversion5.Point3DToPnt3D(refPoint), clsVar.varMouse.Osnap.SnapDistance, buVector5.PlaneToWorkPlane(ccVars.planeActive)));
      ccVars.OsnapCatchPoint.SnapFound = true;
      ccVars.pntActive = buVector5.ToPoint3D(ccVars.OsnapCatchPoint.Point);
      ccVars.OsnapCatchPoint.Type = osnapType.None;
      ccVars.OsnapCatchPoint.Method = osnapMethodType.Snap;
    }
    if (ccVars.Action != 0 & clsVar.varMouse.Osnap.OrthoAuto & !ccVars.selectionProcess)
    {
      double num1 = Math.Abs(clsInit.cVector5.PointAngle(refPoint, ccVars.pntBase, ccVars.planeActive) % 90.0);
      double num2 = Math.Abs(num1 - 90.0);
      if (num1 <= clsVar.varMouse.Osnap.OrthoAutoAngle | num2 <= clsVar.varMouse.Osnap.OrthoAutoAngle)
      {
        int OrthoDir = 0;
        Pnt3D OrthoPnt = new Pnt3D();
        clsInit.cVector.OrthoFunction(buConversion5.Point3DToPnt3D(refPoint), buConversion5.Point3DToPnt3D(ccVars.pntBase), buVector5.PlaneToWorkPlane(ccVars.planeActive), ref OrthoPnt, ref OrthoDir);
        ccVars.OsnapCatchPoint.Point = buConversion5.Pnt3DToPoint3D(OrthoPnt);
        ccVars.OsnapCatchPoint.OrthoFound = true;
        ccVars.OsnapCatchPoint.Found = false;
        ccVars.pntActive = buVector5.ToPoint3D(ccVars.OsnapCatchPoint.Point);
      }
    }
    if (clsVar.varMouse.Osnap.Ortho & !ccVars.OsnapCatchPoint.Found & !ccVars.disableOrtho & !ccVars.selectionProcess & ccVars.stpDrawing > 1)
    {
      int OrthoDir = 0;
      ccVars.planeActive.Project(ccVars.pntBase);
      ccVars.planeActive.Project(ccVars.pntActive);
      Vector3D vector3D = new Vector3D(ccVars.pntBase.X - ccVars.pntActive.X, ccVars.pntBase.Y - ccVars.pntActive.Y, ccVars.pntBase.Z - ccVars.pntActive.Z);
      Pnt3D OrthoPnt = new Pnt3D();
      clsInit.cVector.OrthoFunction(buConversion5.Point3DToPnt3D(ccVars.pntActive), buConversion5.Point3DToPnt3D(ccVars.pntBase), buVector5.PlaneToWorkPlane(ccVars.planeActive), ref OrthoPnt, ref OrthoDir);
      ccVars.OsnapCatchPoint.Point = buConversion5.Pnt3DToPoint3D(OrthoPnt);
      ccVars.OsnapCatchPoint.OrthoFound = true;
      ccVars.OsnapCatchPoint.Found = false;
      ccVars.pntActive = buVector5.ToPoint3D(ccVars.OsnapCatchPoint.Point);
    }
    if (clsVar.varMouse.Osnap.Osnap & clsVar.varMouse.Osnap.OsnapZeroPoint && clsInit.cVector.IsPointInsideWindow(buConversion5.Point3DToPnt3D(refPoint), new Pnt3D(), clsVar.varMouse.Osnap.CatchResolution * ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ZoomRatio, buVector5.PlaneToWorkPlane(ccVars.planeActive)))
    {
      ccVars.OsnapCatchPoint.Found = true;
      ccVars.OsnapCatchPoint.Point = new Point3D();
      ccVars.OsnapCatchPoint.Type = osnapType.Point;
      ccVars.OsnapCatchPoint.Method = osnapMethodType.Osnap;
      ccVars.pntActive = new Point3D();
    }
    if (clsVar.varMouse.Osnap.Over & !ccVars.OsnapCatchPoint.Found & ccVars.OsnapCatchPoint.UnderEntityIndex >= 0)
    {
      ccVars.OsnapCatchPoint.OverFound = true;
      ccVars.pntActive = buVector5.ToPoint3D(ccVars.OsnapCatchPoint.EntityPoint);
      ccVars.OsnapCatchPoint.Found = false;
    }
    if (clsVar.varMouse.Osnap.Osnap & !ccVars.OsnapCatchPoint.Found & (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count > 0 | ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0))
    {
      OsnapPoint foundPoint1 = new OsnapPoint();
      if (clsVar.varMouse.Osnap.OsnapEntities)
        ccVars.OsnapCatchPoint.Found = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.FindClosestPointForOsnap(new List<OsnapPoint>(), ref foundPoint1);
      if (ccVars.OsnapCatchPoint.Found)
      {
        ccVars.OsnapCatchPoint.Point = buVector5.ToPoint3D((Point3D) foundPoint1);
        ccVars.OsnapCatchPoint.Type = foundPoint1.Type;
        ccVars.pntActive = new Point3D(foundPoint1.X, foundPoint1.Y, foundPoint1.Z);
      }
      else
      {
        OsnapPoint foundPoint2 = new OsnapPoint();
        ccVars.OsnapCatchPoint.Found = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.FindClosestPointForOsnap(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints, ref foundPoint2);
        if (ccVars.OsnapCatchPoint.Found)
        {
          ccVars.OsnapCatchPoint.Point = buVector5.ToPoint3D((Point3D) foundPoint2);
          ccVars.OsnapCatchPoint.Type = foundPoint2.Type;
          ccVars.pntActive = new Point3D(foundPoint2.X, foundPoint2.Y, foundPoint2.Z);
        }
        else
        {
          foundPoint2 = new OsnapPoint();
          ccVars.OsnapCatchPoint.Found = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.FindClosestPointForOsnap(ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints, ref foundPoint2);
          if (ccVars.OsnapCatchPoint.Found)
          {
            ccVars.OsnapCatchPoint.Point = buVector5.ToPoint3D((Point3D) foundPoint2);
            ccVars.OsnapCatchPoint.Type = foundPoint2.Type;
            ccVars.pntActive = new Point3D(foundPoint2.X, foundPoint2.Y, foundPoint2.Z);
          }
        }
      }
    }
    if (!clsVar.varInterface.ConstantDistanceEnable)
      return;
    if (buVector5.isPlaneXYorYX(ccVars.planeActive))
      ccVars.pntActive.Z = clsVar.varInterface.ConstantDistanceValue;
    if (buVector5.isPlaneXZorZX(ccVars.planeActive))
      ccVars.pntActive.Y = clsVar.varInterface.ConstantDistanceValue;
    if (!buVector5.isPlaneYZorZY(ccVars.planeActive))
      return;
    ccVars.pntActive.X = clsVar.varInterface.ConstantDistanceValue;
  }

  public void GetLayerFromEntitiesColor(ref List<LayerBase5> Layers, ref List<Entity> calcEntities)
  {
    calcEntities.Clear();
    calcEntities = new List<Entity>();
    for (int index1 = 0; index1 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index1)
    {
      string str = "";
      bool flag1 = false;
      Entity entity = (Entity) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].Clone();
      for (int index2 = 0; index2 <= clsVar.Cf2Properties.Count - 1; ++index2)
      {
        Color color = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].Color;
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].ColorMethod == colorMethodType.byLayer)
          color = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1].LayerName].Color;
        if (color.ToArgb() == clsVar.Cf2Properties[index2].MatchColor.ToArgb())
        {
          flag1 = true;
          entity.Color = clsVar.Cf2Properties[index2].Color;
          str = $"{clsVar.Cf2Properties[index2].CodeType.ToString()}-{clsVar.Cf2Properties[index2].PtRealValue.ToString()} Pt";
          if (Layers.Count == 0)
          {
            LayerBase5 layerBase5 = new LayerBase5()
            {
              Diemaker = new LayerDiemakerProps()
            };
            layerBase5.Diemaker.Pt = clsVar.Cf2Properties[index2].PtRealValue;
            layerBase5.Diemaker.Type = clsVar.Cf2Properties[index2].CodeType;
            layerBase5.LayerColor = clsVar.Cf2Properties[index2].Color;
            layerBase5.LayerThickness = (float) clsVar.Cf2Properties[index2].Thickness;
            layerBase5.Name = str;
            Layers.Add(layerBase5);
          }
          else
          {
            bool flag2 = false;
            for (int index3 = 0; index3 <= Layers.Count - 1; ++index3)
            {
              if (Layers[index3].Name == str)
                flag2 = true;
            }
            if (!flag2)
            {
              LayerBase5 layerBase5 = new LayerBase5()
              {
                Diemaker = new LayerDiemakerProps()
              };
              layerBase5.Diemaker.Pt = clsVar.Cf2Properties[index2].PtRealValue;
              layerBase5.Diemaker.Type = clsVar.Cf2Properties[index2].CodeType;
              layerBase5.LayerColor = clsVar.Cf2Properties[index2].Color;
              layerBase5.LayerThickness = (float) clsVar.Cf2Properties[index2].Thickness;
              layerBase5.Name = str;
              Layers.Add(layerBase5);
            }
          }
        }
      }
      if (flag1)
      {
        entity.ColorMethod = colorMethodType.byLayer;
        entity.LineTypeMethod = colorMethodType.byLayer;
        entity.LineWeightMethod = colorMethodType.byLayer;
      }
      else
      {
        entity.ColorMethod = colorMethodType.byEntity;
        entity.LineTypeMethod = colorMethodType.byEntity;
        entity.LineWeightMethod = colorMethodType.byEntity;
      }
      entity.LayerName = str;
      calcEntities.Add(entity);
    }
  }

