  public void ShowActionData(
    object Data,
    int FormHeight,
    int ParCount,
    bool ShowOk,
    bool ShowCancel)
  {
    int num = FormHeight;
    if (ParCount >= 0)
      num = 56 + 33 * ParCount;
    if (ParCount == 1)
      num += 2;
    if (clsItem.FrmMain == null)
      return;
    clsItem.FrmActionData.Height = num;
    clsItem.FrmActionData.Left = clsItem.FrmMain.Left + 1;
    clsItem.FrmActionData.Top = clsItem.FrmMain.Height - num - 122;
    clsItem.FrmActionData.buClassViewer1.ShowOkButton = ShowOk;
    clsItem.FrmActionData.buClassViewer1.ShowCancelButton = ShowCancel;
    clsItem.FrmActionData.buClassViewer1.RowSpace = 1;
    clsItem.FrmActionData.buClassViewer1.Visible = true;
    clsItem.FrmActionData.buClassViewer1.ValueWidth = Convert.ToInt32((float) clsItem.FrmActionData.buClassViewer1.Width / 2f) - 5;
    clsItem.FrmActionData.buClassViewer1.ClassObject = Data;
    clsItem.FrmActionData.buClassViewer1.OwnerForm = (Form) clsItem.FrmActionData;
    clsItem.FrmActionData.buClassViewer1.Init();
    clsItem.FrmActionData.TopMost = true;
    clsItem.FrmActionData.Show();
  }

