  public void GetDrawingInfo(
    Point3D pntBase,
    Point3D pntActive,
    bool Len,
    bool Ang,
    bool dx,
    bool dy,
    bool dz)
  {
    dynamicInfo.Len = Point3D.Distance(ccVars.pntActive, ccVars.pntBase);
    dynamicInfo.Ang = clsInit.cVector.PointAngle(buConversion5.Point3DToPnt3D(ccVars.pntActive), buConversion5.Point3DToPnt3D(ccVars.pntBase), buVector5.PlaneToWorkPlane(ccVars.planeActive));
    dynamicInfo.dX = clsInit.cVector5.DeltaX(ccVars.pntActive, ccVars.pntBase);
    dynamicInfo.dY = clsInit.cVector5.DeltaY(ccVars.pntActive, ccVars.pntBase);
    dynamicInfo.dZ = clsInit.cVector5.DeltaZ(ccVars.pntActive, ccVars.pntBase);
    dynamicInfo.Command = AppLanguage.CadCamCommand[1];
    dynamicInfo.Info = $"{AppLanguage.CadCamDynamic[0]}: {dynamicInfo.Len.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} - {AppLanguage.CadCamDynamic[2]}: {dynamicInfo.Ang.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}º";
    if (!clsVar.varView.ShowDxDyDzValuesDynamicText)
      return;
    dynamicInfo.Info = $"{dynamicInfo.Info} dx: {dynamicInfo.dX.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} dy: {dynamicInfo.dY.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())} dz: {dynamicInfo.dZ.ToString("f" + clsVar.varProgram.DecimalVisiblePoint.ToString())}";
  }

  public void ShowPreview(
    List<Entity> Entities,
    BlockKeyedCollection Blocks,
    LayerKeyedCollection Layers)
  {
    if (clsItem.FrmPreview == null)
    {
      clsItem.FrmPreview = new F_Preview();
      clsInit.cVector5.CreateModelControl(ref clsItem.FrmPreview.viewportLayout, clsVar.UnlockKey, new CreateModelProperties()
      {
        CoordinateSystemIconVisible = false,
        ViewCubeIconVisible = false,
        OrigineCaptionVisible = false,
        ToolBorVisible = false
      });
    }
    clsItem.FrmPreview.viewportLayout.Entities.Clear();
    clsItem.FrmPreview.viewportLayout.Layers = buConversion5.CopyEyeLayerToEyeLayer(Layers);
    for (int index = clsItem.FrmPreview.viewportLayout.Blocks.Count - 1; index >= 1; --index)
      clsItem.FrmPreview.viewportLayout.Blocks.RemoveAt(index);
    clsItem.FrmPreview.viewportLayout.Blocks.AddRange((IEnumerable<Block>) clsInit.cVector5.CopyEyeBlockToEyeBlock(clsItem.FrmPreview.viewportLayout.Blocks, Blocks));
    for (int index = 0; index <= Entities.Count - 1; ++index)
    {
      Entity entity = (Entity) Entities[index].Clone();
      clsItem.FrmPreview.viewportLayout.Entities.Add(entity);
    }
    clsItem.FrmPreview.viewportLayout.SetView(viewType.Trimetric, true, false);
    clsItem.FrmPreview.Init();
    clsItem.FrmPreview.Show();
  }

  public void ShowToolTip()
  {
    if (ccVars.Pages.Count <= 0 || !(ViewportCC.UnderMouseEntityIndex >= 0 & ViewportCC.UnderMouseEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1))
      return;
    Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ViewportCC.UnderMouseEntityIndex];
    string sInfo = "";
    this.GetEntityInfo(entity, ref sInfo);
    if (sInfo == null || sInfo.Length <= 0)
      return;
    System.Drawing.Point point = new System.Drawing.Point(ViewportCC.mouseLocation.X + 10, ViewportCC.mouseLocation.Y + 10);
    ccVars.Pages[ccVars.PageIndex].Form.lbl_tooltip.Text = sInfo;
    ccVars.Pages[ccVars.PageIndex].Form.lbl_tooltip.Location = point;
    ccVars.Pages[ccVars.PageIndex].Form.lbl_tooltip.Visible = true;
  }

