  public void ClassViewValueChanged(object sender, object value, cParameter Parameter)
  {
    if (ccVars.Action == actionTypeBU.drawVectorText && clsItem.FrmActionData.buClassViewer1.ClassObject != null && clsItem.FrmActionData.buClassViewer1.ClassObject is TextVectorRuntimeData)
    {
      ccVars.VectorTextRunVar.Alignment = ((TextVectorRuntimeData) clsItem.FrmActionData.buClassViewer1.ClassObject).Alignment;
