  public void RunSyCmd(string C)
  {
    string[] strArray = C.Split(';');
    if (strArray == null)
      return;
    if (strArray.Length == 2)
    {
      strArray[0].ToLower().Trim();
      string str = strArray[1].ToLower().Trim();
      if (!(strArray[0].ToLower().Trim() == "bucadcam") || !(str.ToLower() == "sendinfo"))
        return;
      string info = "";
      clsInit.appSystem.getProgramInfo(ref info);
      clsInit.cNet.SendEmailFromCmdConfirm("report@cmdsoft.com.tr", $"buCadCam - [Send Info] | cusID = {clsVar.appDefination.CustomerID.ToString()} , cusName = {clsVar.appDefination.CustomerInfo} , Mode = {clsVar.appDefination.Mode}", info, new List<string>());
      clsInit.cNet.DeleteEmailFromCmdConfirm(true);
    }
    else
    {
      if (strArray.Length <= 7)
        return;
      strArray[0].ToLower().Trim();
      string str1 = strArray[1].ToLower().Trim();
      strArray[2].ToLower().Trim();
      string str2 = strArray[3].ToLower().Trim();
      string str3 = strArray[4].ToLower().Trim();
      strArray[5].ToLower().Trim();
      strArray[6].ToLower().Trim();
      strArray[7].ToLower().Trim();
      string str4 = strArray[8].ToLower().Trim();
      if (!(strArray[0].ToLower().Trim() == "bucadcam"))
        return;
      if (str3.ToLower() == "sendinfo" & (str1.Length == 0 | str1 == "0" | str1 == clsVar.appDefination.CustomerID.ToString()) & (str2.Length == 0 | str2 == "0" | str2 == clsVar.appDefination.ProgramCode))
      {
        string info = "";
        clsInit.appSystem.getProgramInfo(ref info);
        clsInit.cNet.SendEmailFromCmdConfirm("report@cmdsoft.com.tr", $"buCadCam - [Send Info] | cusID = {clsVar.appDefination.CustomerID.ToString()} , cusName = {clsVar.appDefination.CustomerInfo} , Mode = {clsVar.appDefination.Mode}", info, new List<string>());
        if (!(str4.Length == 0 | str4 == "1"))
          return;
        clsInit.cNet.DeleteEmailFromCmdConfirm(true);
      }
      else if (str3.ToLower() == "blockallcustomerprogram" & str1 == clsVar.appDefination.CustomerID.ToString() & (str2.Length == 0 | str2 == "0" | str2 == clsVar.appDefination.ProgramCode))
      {
        string info = "";
        clsInit.appSystem.SetTr(567.003);
        clsInit.appSystem.getProgramInfo(ref info);
        clsInit.cNet.SendEmailFromCmdPrg("report@cmdsoft.com.tr", $"buCadCam - [Block All Customer Program] | cusID = {clsVar.appDefination.CustomerID.ToString()} , cusName = {clsVar.appDefination.CustomerInfo} , Mode = {clsVar.appDefination.Mode}", info, new List<string>());
        if (!(str4.Length == 0 | str4 == "1"))
          return;
        clsInit.cNet.DeleteEmailFromCmdPrg(true);
      }
      else
      {
        if (!(str3.ToLower() == "blockcustomerprogram" & str1 == clsVar.appDefination.CustomerID.ToString() & str2 == clsVar.appDefination.ProgramCode))
          return;
        string info = "";
        clsInit.appSystem.SetTr(567.003);
        clsInit.appSystem.getProgramInfo(ref info);
        clsInit.cNet.SendEmailFromCmdPrg("report@cmdsoft.com.tr", $"buCadCam - [Block Customer Program] | cusID = {clsVar.appDefination.CustomerID.ToString()} , cusName = {clsVar.appDefination.CustomerInfo} , Mode = {clsVar.appDefination.Mode}", info, new List<string>());
