  public int doWireframeContour(
    MWCalculationOptions MWCalcoptions,
    ToolBase5 Tool,
    actionTypeBU Action,
    ref camTp Cam)
  {
    Cam = new camTp();
    if (Action == actionTypeBU.camContours)
      buMWCalcs.CopyCamParameter(clsVar.varCamWFContourPars, ref buMWCalcs.varCamWFContourPars);
    if (Action == actionTypeBU.camContours4AX)
      buMWCalcs.CopyCamParameter(clsVar.varCamWFContour4XPars, ref buMWCalcs.varCamWFContour4XPars);
    if (Action == actionTypeBU.camPocketing)
      buMWCalcs.CopyCamParameter(clsVar.varCamWFPocketPars, ref buMWCalcs.varCamWFPocketPars);
    if (ccVars.MaterialList.Count > 0 && ccVars.MaterialList[clsVar.varInterface.MaterialIndex].Enable)
    {
      MWCalcoptions.CheckBoxBounding = true;
      MWCalcoptions.BoxBoundingMin.X = ccVars.MaterialList[clsVar.varInterface.MaterialIndex].BoxMinPoint.X;
      MWCalcoptions.BoxBoundingMin.Y = ccVars.MaterialList[clsVar.varInterface.MaterialIndex].BoxMinPoint.Y;
      MWCalcoptions.BoxBoundingMin.Z = 0.0;
