  public void PostFileGet(string pathPost, ref List<FileEventArg> PostList)
  {
    try
    {
      List<string> Files = new List<string>();
      buFile.getFiles(pathPost, ref Files);
      PostList.Clear();
      clsVar.PostAvailableNames.Clear();
      for (int index = 0; index <= Files.Count - 1; ++index)
      {
        FileInfo fileInfo = new FileInfo(Files[index]);
        if (fileInfo.Exists & fileInfo.Extension.ToLower() == ".bupost")
        {
          FileEventArg FileArg = new FileEventArg();
          buFile.GetFileArgumans(fileInfo.FullName, ref FileArg);
          FileArg.JustFileNameWithoutExtension = buFile.getFileNameWithoutExtension(fileInfo.FullName);
          FileArg.FileName = fileInfo.FullName;
          FileArg.FilePath = buFile.GetPath(fileInfo.FullName);
          PostList.Add(FileArg);
        }
      }
      buLog.addLog(nameof (PostFileGet), "Ok", MethodBase.GetCurrentMethod().Name, "", "", 0.0, 0.0);
    }
    catch (Exception ex)
    {
      this.PostUpdating = false;
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void PostUpdate(string PostName, ref List<string> PostList, ref string FoundPost)
  {
    try
    {
      List<string> Files = new List<string>();
      bool flag = false;
      buFile.getFiles(AppPath.PostProcessor, ref Files);
      PostList.Clear();
      this.PostUpdating = true;
      clsVar.PostAvailableNames.Clear();
      for (int index = 0; index <= Files.Count - 1; ++index)
      {
        FileInfo fileInfo = new FileInfo(Files[index]);
        if (fileInfo.Exists & fileInfo.Extension.ToLower() == ".bupost")
        {
          FileEventArg FileArg = new FileEventArg();
          buFile.GetFileArgumans(fileInfo.FullName, ref FileArg);
          PostList.Add(buFile.getFileNameWithoutExtension(fileInfo.FullName));
          FileArg.FileName = fileInfo.FullName;
          FileArg.FilePath = buFile.GetPath(fileInfo.FullName);
          clsVar.PostAvailableNames.Add(FileArg);
          if (buFile.getFileNameWithoutExtension(fileInfo.FullName) == PostName)
            flag = true;
        }
      }
      if (PostList.Count <= 0)
        return;
      this.PostUpdating = false;
      FoundPost = !flag ? clsVar.PostAvailableNames[0].JustFileNameWithoutExtension : PostName;
      buLog.addLog("Post File Updated", "Ok", MethodBase.GetCurrentMethod().Name, PostName, "", 0.0, 0.0);
    }
    catch (Exception ex)
    {
      this.PostUpdating = false;
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public bool PostLoad(string PostName)
  {
    try
    {
      for (int index = 0; index <= clsVar.PostAvailableNames.Count - 1; ++index)
      {
        if (clsVar.PostAvailableNames[index].JustFileNameWithoutExtension == PostName | clsVar.PostAvailableNames[index].JustFileName == PostName | clsVar.PostAvailableNames[index].FileName == PostName)
        {
          buFile.OpenPostProcessorFile(clsVar.PostAvailableNames[index].FileName, ref ccVars.PostActive);
          int count = clsVar.PostAvailableNames.Count;
          return true;
        }
      }
      if (clsVar.PostAvailableNames.Count <= 0)
        return false;
      buFile.OpenPostProcessorFile(clsVar.PostAvailableNames[0].FileName, ref ccVars.PostActive);
      return true;
    }
    catch (Exception ex)
    {
      string str = "PostName: " + PostName;
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, str);
      return false;
    }
  }

  public void MiscControlResize(bool Vertical, bool Horizontal)
  {
    try
    {
      int height = clsItem.tabcontrolLeft.Height;
      int width = clsItem.tabcontrolLeft.Width;
      if (clsVar.varProgram.MiscLocation == LeftRightAlignment.Right)
      {
        height = clsItem.tabcontrolRight.Height;
        width = clsItem.tabcontrolRight.Width;
      }
      if (Vertical)
        clsItem.FrmTempMisc.pnl_controls.Height = height;
      if (!Horizontal)
        return;
      clsItem.FrmTempMisc.pnl_controls.Width = width - 50;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, str);
    }
  }

  public static Bitmap ChangeColor(Bitmap scrBitmap)
  {
    Color red = Color.Red;
    Bitmap bitmap = new Bitmap(scrBitmap.Width, scrBitmap.Height);
    for (int x = 0; x < scrBitmap.Width; ++x)
    {
      for (int y = 0; y < scrBitmap.Height; ++y)
      {
        Color pixel = scrBitmap.GetPixel(x, y);
        if (pixel.A > (byte) 150)
          bitmap.SetPixel(x, y, red);
        else
          bitmap.SetPixel(x, y, pixel);
      }
    }
    return bitmap;
  }

  public void ThreadCalculationLoop()
  {
    while (true)
    {
      if (ThreadCommands.OsnapCalculationAll)
        goto label_6;
label_1:
      if (ThreadCommands.OsnapEnableDisableByLayerVisible)
      {
        this.OsnapEnableDisableByLayerAndEntityVisiblity();
        ThreadCommands.OsnapEnableDisableByLayerVisible = false;
      }
      if (ThreadCommands.OsnapDelete)
      {
        this.OsnapDelete();
        ThreadCommands.OsnapDelete = false;
      }
      clsVar.threadCalculations.Abort();
      continue;
label_6:
      this.OsnapCalculationAll();
      ThreadCommands.OsnapCalculationAll = false;
      goto label_1;
    }
  }
}
